window.EXPL={"관세사2017_34-02-1":{"f":"","w":"이 문항은 미납세반출에 해당하는 것을 묻는다. 재수출할 물품을 보세구역에서 반출하는 것으로서 관세가 면제되는 것은 미납세반출이 아니라 조건부면세 대상이다(개별소비세법 제18조제1항제8호).","c":"상","v":1},"관세사2017_34-02-2":{"f":"","w":"이 문항은 미납세반출에 해당하는 것을 묻는다. 거주 이전 외의 목적으로 입국하는 사람이 휴대하거나 따로 수입하는 자가사용 물품으로서 관세가 면제되는 것은 미납세반출이 아니라 무조건 면세 대상이다(개별소비세법 제19조제9호).","c":"상","v":1},"관세사2017_34-02-3":{"f":"","w":"이 문항은 미납세반출에 해당하는 것을 묻는다. 거주자가 받는 소액물품으로서 관세가 면제되는 것은 미납세반출이 아니라 무조건 면세 대상이다(개별소비세법 제19조제11호).","c":"상","v":1},"관세사2017_34-02-4":{"f":"","w":"이 문항은 미납세반출에 해당하는 것을 묻는다. 우리나라에 주둔하는 외국군대(주한외국군)에 납품하는 것은 미납세반출이 아니라 수출 및 군납 면세 대상이다(개별소비세법 제15조제1항제2호).","c":"중","v":1},"관세사2017_34-04-4":{"f":"반출되는 물품의 운송비를 그 운송거리나 운송방법에 상관없이 같은 금액으로 하여 그 반출가격에 포함시키거나 그 금액을 별도로 받는 경우에는 그 운송비를 포함한 가격에 상당하는 금액으로 계산한다.","w":"운송비를 일률적으로 반출가격에 넣거나 따로 받는 경우에는 운송비를 포함한 가격을 과세표준으로 한다. 운송비를 빼는 것이 아니다.","c":"중","v":1},"관세사2017_34-05-3":{"f":"미납세반출자와 그 반출된 물품을 반입한 자가 동일한 사업자인 경우에는 해당 물품을 반입지에서 판매 또는 반출할 때 미납세반출자가 해당 물품에 대한 개별소비세를 관할 세무서장 또는 세관장에게 신고·납부할 수 있다.","w":"반입한 자가 다른 사업자이면 반입한 자가 판매·반출할 때 납세의무를 진다. 미납세반출자가 대신 신고·납부하는 것은 동일한 사업자인 경우이다.","c":"중","v":1},"관세사2018_35-35-3":{"f":"과세유흥장소의 영업을 사실상 폐업한 자는 폐업한 날이 속하는 달의 다음 달 25일까지 관할 세무서장에게 개별소비세를 신고·납부하여야 한다.","w":"과세유흥장소를 폐업한 경우에는 폐업한 날이 속한 달의 다음 달 25일까지 신고·납부한다. 다음 해 3월 말일이 아니다.","c":"상","v":1},"관세사2019_36-32-3":{"f":"입찰의 방법으로 물품을 반출할 때 입찰견적서에 운송비가 따로 계상되어 있더라도 그 낙찰가격에 운송비를 포함하고 있는 경우에는 그 운송비를 포함한 가격에 상당하는 금액으로 한다.","w":"낙찰가격에 운송비가 들어 있으면 운송비가 견적서에 따로 적혀 있어도 운송비를 포함한 금액이 반출가격이다.","c":"중","v":1},"관세사2019_36-34-1":{"f":"","w":"이 문항은 미납세반출에 해당하지 않는 것을 묻는다. 외국에서 개최되는 박람회등에 출품하기 위하여 해외로 반출하는 물품은 미납세반출이 아니라 무조건 면세 대상이다(개별소비세법 제19조제13호).","c":"상","v":1},"관세사2020_37-31-2":{"f":"","w":"재수출할 물품을 보세구역에서 반출하는 것으로서 관세가 면제되는 것은 재수출 이행을 조건으로 면제하는 조건부 면세이다. 무조건 면세가 아니다.","c":"중","v":1},"관세사2020_37-33-1":{"f":"국내 또는 국외에서 개최한 박람회등에 출품한 물품을 제조장에 환입(還入)하거나 보세 구역에서 반출하는 것은 개별소비세를 징수하지 아니한다.","w":"박람회 출품 물품의 환입이나 보세구역 반출은 미납세반출 사유로 개별소비세를 징수하지 않는다.","c":"중","v":1},"관세사2020_37-33-2":{"f":"과세물품을 제조ㆍ가공하기 위한 원료로 사용하기 위하여 다른 제조장으로 반출하는 것은 개별소비세를 징수하지 아니한다.","w":"과세물품의 원료로 쓰기 위해 다른 제조장으로 반출하는 것은 미납세반출 대상이라 징수하지 않는다.","c":"중","v":1},"관세사2020_37-33-3":{"f":"원료를 공급받거나 위탁 공임만을 받고 제조한 물품을 제조장에서 위탁자의 제품 저장 창고에 반출하는 것은 개별소비세를 징수하지 아니한다.","w":"위탁 공임만 받고 제조한 물품을 위탁자의 저장창고에 반출하는 것은 미납세반출 대상이다.","c":"상","v":1},"관세사2020_37-33-5":{"f":"수출물품 또는 수출물품의 제조ㆍ가공을 위한 물품을 원내국신용장에 의하여 수출업자 또는 수출물품의 제조ㆍ가공업자에게 반출하는 것은 개별소비세를 징수하지 아니한다.","w":"수출용 물품을 내국신용장에 의해 수출업자나 가공업자에게 반출하는 것은 미납세반출 대상이다.","c":"중","v":1},"관세사2020_37-35-3":{"f":"유흥주점의 경영자가 과세유흥장소의 영업을 사실상 폐업한 경우에는 폐업사유가 발생한 날이 속한 달의 다음 달 25일까지 관할 세무서장에게 개별소비세를 신고ㆍ납부하여야 한다.","w":"폐업 신고·납부 기한은 폐업일이 속한 달의 다음 달 25일이다. 분기 기준이 아니다.","c":"상","v":1},"관세사2022_39-31-2":{"f":"납세의무자가 귀금속제품을 보세구역에서 반출할 때 개별소비세 과세표준은 해당 물품을 수입신고할 때의 관세의 과세가격과 관세를 합한 금액 중 기준가격을 초과하는 부분의 가격으로 한다.","w":"귀금속제품은 기준가격(1개당 500만원)을 초과하는 부분의 가격만 과세표준이 된다. 보세구역 반출 물품의 과세표준인 관세의 과세가격과 관세를 합한 금액에서도 기준가격 초과분만 잡는다(개별소비세법 제8조제1항 단서·제3호, 시행령 제4조제1호).","c":"상","v":1},"관세사2022_39-32-4":{"f":"과세물품이 제조장 밖에 있는 해당 기업의 기초연구진흥 및 기술개발지원에 관한 법률에 따른 기업부설연구소로 옮겨져서 시험ㆍ연구 목적으로 사용되는 경우에는 제조장에서 반출하는 것으로 보지 아니한다.","w":"기업부설연구소나 연구개발전담부서는 제조장 밖에 있어도 같은 제조장에 있는 것으로 보므로, 그곳에서 시험·연구 목적으로 사용하는 것은 반출로 보지 않는다(개별소비세법 제6조제1항제1호 단서, 시행령 제6조제1항제2호).","c":"상","v":1},"관세사2022_39-34-2":{"f":"산업용 등 대통령령으로 정하는 용도로 사용하는 유연탄에 대해서는 조건부면세 조항을 적용하여 개별소비세를 면제한다.","w":"유연탄의 면세는 용도 외 사용 시 징수하는 조건부 면세이다. 무조건 면세가 아니다.","c":"중","v":1},"관세사2022_39-34-3":{"f":"수출 물품의 용기로서 재수입하는 것의 경우에는 무조건 면세 조항을 적용하여 개별소비세를 면제한다.","w":"수출 물품의 용기로서 재수입하는 것은 조건 없이 면제하는 무조건 면세이다.","c":"상","v":1},"관세사2022_39-34-4":{"f":"개별소비세가 부과된 물품으로서 수출한 후 개별소비세법에 따른 환급이나 공제를 받은 사실이 없다는 것을 관할 세무서장이 증명하는 물품이 재수입되어 보세구역에서 반출하는 것의 경우에는 무조건 면세 조항을 적용하여 개별소비세를 면제한다.","w":"증명하는 기관은 관할 세관장이 아니라 관할 세무서장이다.","c":"중","v":1},"관세사2022_39-34-5":{"f":"조건부면세 조항을 적용한 물품으로서 반입지에 반입한 사실을 증명하지 아니한 것에 대해서는 개별소비세를 징수한다.","w":"반입 사실을 증명하지 못하면 징수하는 것은 조건부 면세이다. 무조건 면세는 조건이 없으므로 이런 추징이 없다.","c":"상","v":1},"관세사2022_39-35-1":{"f":"개별소비세 과세물품을 관세법에 따라 세관장에게 수입신고하는 자는 수입신고를 하면 개별소비세법에 따른 과세표준을 신고한 것으로 본다.","w":"보세구역에서 반출하는 자가 수입신고를 하면 개별소비세 과세표준도 신고한 것으로 본다. 수입신고 수리 후에 별도로 신고하는 것이 아니다.","c":"중","v":1},"관세사2023_40-34-3":{"f":"과세물품이 개별소비세가 과세되지 않는 석유류의 제조용 원재료로 정유공정에 그대로 사용되는 경우에는 제조장에서 반출하는 것으로 보지 아니한다.","w":"과세되지 않는 석유류의 제조 원재료로 정유공정에 그대로 사용되는 경우는 반출로 보지 않는다.","c":"중","v":1},"관세사2024_41-31-3":{"f":"캠핑용 트레일러는 개별소비세 과세물품인 캠핑용자동차에 포함한다.","w":"캠핑용자동차에는 캠핑용 트레일러도 포함된다.","c":"중","v":1},"관세사2024_41-32-5":{"f":"과세영업장소에서의 영업행위의 경우 과세시기는 영업행위를 할 때이다.","w":"과세영업장소(카지노 등)의 과세시기는 영업행위를 할 때이다. 분기 말일이 아니다.","c":"중","v":1},"관세사2024_41-33-1":{"f":"동일 제조장에서 과세물품이 다른 과세물품의 원재료로 사용되는 경우 반출하는 것으로 보지 아니한다.","w":"같은 제조장에서 과세물품의 원재료로 쓰는 것은 최종 제품에서 과세하므로 반출로 보지 않는다.","c":"상","v":1},"관세사2024_41-33-2":{"f":"동일 제조장에서 과세물품에 특수한 장식을 하여 소비하는 경우 반출하는 것으로 본다.","w":"제조장에서 사용되거나 소비되면 반출하는 것으로 본다. 예외는 같은 제조장에서 원재료나 시험·연구·검사용으로 쓰는 경우, 비과세 석유류의 원재료로 정유공정에 그대로 쓰는 경우뿐이고 장식을 하여 소비하는 것은 여기에 들지 않는다(개별소비세법 제6조제1항제1호, 시행령 제6조제1항).","c":"상","v":1},"관세사2024_41-33-3":{"f":"과세물품이 납세 보증으로 보존되는 경우 반출하는 것으로 보지 아니한다.","w":"납세 보증으로 보존하는 것은 물품이 제조장에 머무는 것이라 반출로 보지 않는다.","c":"중","v":1},"관세사2024_41-33-5":{"f":"동일 제조장에서 과세물품에 가치를 높이기 위한 가공을 하는 경우 반출하는 것으로 보지 아니한다.","w":"같은 제조장 안에서 가치를 높이는 가공을 하는 것만으로는 반출이 아니다.","c":"중","v":1},"관세사2025_42-31-4":{"f":"18세 미만의 자녀 3명 이상을 양육하는 사람이 구입하는 승용자동차에 대한 개별소비세는 300만원을 한도로 하여 면제한다.","w":"다자녀(18세 미만 자녀 3명 이상) 양육자의 승용자동차 개별소비세 면제 한도는 300만원이다.","c":"중","v":1},"관세사2025_42-32-5":{"f":"외상으로 유흥음식행위를 하게 한 것으로서 경영을 폐지한 때의 외상매출금 잔액은 과세유흥장소의 영업 폐업에 따른 신고 시의 과세표준에 포함한다.","w":"폐업 시 외상매출금 잔액은 폐업 신고의 과세표준에 포함해 신고한다. 제외하지 않는다.","c":"중","v":1},"관세사2025_42-34-1":{"f":"「체육시설의 설치ㆍ이용에 관한 법률」 제10조의2제2항에 따라 문화체육관광부장관이 지정한 대중형 골프장은 과세장소에서 제외한다.","w":"대중형 골프장의 입장행위는 개별소비세를 부과하지 않는다.","c":"상","v":1},"관세사2025_42-34-3":{"f":"잠정세율은 기본세율 및 탄력세율에 우선하여 적용한다.","w":"기본세율과 탄력세율(제1조제7항)에 우선하는 것은 잠정세율이다. 탄력세율이 잠정세율에 앞서는 것이 아니다(개별소비세법 제1조의2제3항).","c":"상","v":1},"관세사2025_42-34-4":{"f":"발전사업용 유연탄은 조건부면세대상에 해당한다.","w":"발전사업용 유연탄의 면세는 용도 외 사용 시 징수하는 조건부 면세이다.","c":"중","v":1},"관세사2025_42-34-5":{"f":"1개당 판매가격이 500만원인 고급시계는 과세물품에 해당하며 이에 대해서는 기준가격을 초과하는 금액에 100분의 20의 세율을 적용한다.","w":"고급시계의 기준가격은 1개당 200만원이므로 500만원짜리 시계는 과세물품이다. 세율 100분의 20은 판매가격 전체가 아니라 기준가격을 초과하는 부분에 적용한다(개별소비세법 제1조제2항제2호, 시행령 제4조제2호).","c":"상","v":1},"관세사2026_43-31-1":{"f":"외국인전용판매장에서 개별소비세가 면제되는 물품을 구입한 자가 출국 당시 그 물품을 소지하지 아니한 경우에는 개별소비세를 징수한다.","w":"면세로 구입한 물품을 출국 당시 소지하지 않으면 면제받은 개별소비세를 징수한다.","c":"상","v":1},"관세사2026_43-31-2":{"f":"화투류는 외국인전용판매장 면세 대상 물품에 해당한다.","w":"화투류는 골패와 함께 외국인전용판매장에서 개별소비세를 면제받을 수 있는 물품이다(개별소비세법 시행령 제27조제3호).","c":"상","v":1},"관세사2026_43-31-3":{"f":"관할 세무서장은 외국인전용판매장의 지정을 받은 자가 해당 판매장을 대여한 경우 그 지정을 취소할 수 있다.","w":"외국인전용판매장의 지정을 받은 자가 해당 판매장을 양도하거나 대여하면 관할 세무서장은 지정을 취소할 수 있다(개별소비세법 시행령 제28조제3항제5호).","c":"상","v":1},"관세사2026_43-31-4":{"f":"개별소비세를 면제받아 외국인전용판매장에 반입된 물품을 해당 판매장에서 구입할 수 없는 자가 소지한 경우에는 그 소지자로부터 개별소비세를 징수한다.","w":"구입할 수 없는 자가 면세 반입 물품을 소지하면 과태료를 매기는 것이 아니라 그 소지자로부터 개별소비세를 징수한다. 경영자나 구입자에게서 이미 징수했으면 징수하지 않는다(개별소비세법 제17조제6항).","c":"상","v":1},"관세사2026_43-35-1":{"f":"과세물품이 제조장에 있다가 파산절차로 환가되는 경우에는 제조장에서 반출하는 것으로 본다.","w":"공매·경매·파산절차로 환가되는 경우는 반출한 것으로 본다.","c":"상","v":1},"관세사2026_43-35-2":{"f":"공업용 다이아몬드가 제조장에 있다가 동일 제조장에서 과세물품의 원재료로 사용되는 경우에는 제조장에서 반출하는 것으로 보지 아니하여 개별소비세를 부과하지 아니한다.","w":"같은 제조장에서 과세물품의 원재료로 사용되면 반출로 보지 않는다. 공업용 다이아몬드는 과세물품에서도 제외된다.","c":"중","v":1},"관세사2026_43-35-3":{"f":"제조장 외의 장소에서 규격 검사를 받기 위하여 과세물품을 제조장에서 반출하는 것은 미납세반출 대상 물품에 해당한다.","w":"규격 검사를 받기 위한 반출은 미납세반출 대상이다.","c":"상","v":1},"관세사2026_43-35-4":{"f":"수출물품의 가공을 위한 물품을 제2차 내국신용장에 의하여 수출물품의 가공업자에게 반출하는 것은 미납세반출 대상 물품에 해당한다.","w":"제2차 내국신용장에 의한 반출도 미납세반출 대상에 들어간다.","c":"중","v":1},"관세사2017_34-08-2":{"f":"","w":"무형문화재(현 무형유산) 기능보유자가 제조한 주류는 무형문화재 공개에 사용되는 것만 주세가 면제된다. 제조하여 판매하는 것은 면세 대상이 아니다(현행 주세법 제20조제1항제7호).","c":"중","v":1},"관세사2017_34-09-1":{"f":"관할 세무서장은 주세 보전을 위하여 필요한 경우 주류 제조자에 대하여 대통령령으로 정하는 바에 따라 주세에 대한 담보를 제공하거나 납세 보증으로서 담보액에 상당하는 가액의 주류를 보존할 것을 명할 수 있다.","w":"담보 제공이나 주류 보존을 명하는 대상은 주류 제조자이다. 판매자가 아니다.","c":"중","v":1},"관세사2017_34-09-2":{"f":"납세의무자가 주세법에 따라 납세 보증으로서 보존하는 주류에 대하여 기한까지 주세를 납부하지 아니하는 경우 납세 보증으로서 보존하는 주류를 국세징수법에서 정하는 절차에 따라 공매한 금액으로 주세를 충당하여야 한다.","w":"납세보증주류는 국세징수법에 따라 공매하여 그 금액으로 주세를 충당한다.","c":"상","v":1},"관세사2017_34-09-4":{"f":"관할 세무서장은 주세에 대한 담보제공기간이 2 이상의 주조연도에 걸치는 경우에는 매년 1월에 담보의 내용과 적정여부를 조사해야 한다.","w":"담보나 보존 기간이 2주조연도 이상이면 매년 1월에 내용과 적정성을 조사한다. 주조연도 말이 아니다.","c":"중","v":1},"관세사2017_34-09-5":{"f":"납세의 보증으로 보존하는 주류의 가격은 통상가격으로 한다.","w":"보존하는 주류의 가격은 제조원가가 아니라 통상가격이다.","c":"상","v":1},"관세사2018_35-36-3":{"f":"주정 외의 주류에 대한 주세의 과세표준은 수입하는 경우에는 수입신고하는 때의 관세의 과세가격과 관세를 합한 금액으로 한다.","w":"수입 주류의 가격은 관세의 과세가격에 관세를 더한 금액이다. 과세가격만이 아니다.","c":"상","v":1},"관세사2018_35-37-1":{"f":"관할 세무서장은 주세 보전을 위하여 필요하다고 인정되면 주류 제조자에 대하여 주세액에 상당하는 가액(價額)의 주류를 보존할 것을 명할 수 있다.","w":"보존을 명하는 가액은 주세액에 상당하는 가액이고 120퍼센트가 아니다. 필요하다고 인정될 때 명할 수 있다.","c":"중","v":1},"관세사2018_35-37-2":{"f":"납세의무자가 주세법에 따라 납세 보증으로서 보존하는 주류에 대하여 기한까지 주세를 납부하지 아니하는 경우에는 납세 보증으로서 보존하는 주류를 국세징수법에서 정하는 바에 따라 공매한 금액으로 주세를 충당하여야 한다.","w":"보존 주류는 공매하여 주세를 충당한다. 판매하는 것이 아니다.","c":"상","v":1},"관세사2018_35-37-3":{"f":"납세의 보증으로 보존하는 주류의 가격은 통상가격으로 한다.","w":"보존하는 주류의 가격은 통상가격이다.","c":"상","v":1},"관세사2018_35-37-5":{"f":"관할 세무서장의 승인을 받아 술덧을 처분하는 경우 해당 술덧은 탁주로 보아그 제조자로부터 주세를 지체 없이 징수한다.","w":"출제 당시 주세법(2020.12.29 전부개정 전) 제41조제2항은 승인을 받아 처분하는 밑술·술덧을 청주가 아니라 탁주로 보아 그 제조자로부터 주세를 지체 없이 징수하게 했다.","c":"중","v":1},"관세사2019_36-37-2":{"f":"주류 제조자는 관할 세무서장의 주세보전을 위한 담보제공 또는 주류 보존 명령을 이행하지 않은 경우 그 사유가 발생한 날이 속하는 달의 다음 달 말일까지 그 출고된 주류 또는 출고된 것으로 보는 주류에 대한 신고서를 관할 세무서장에게 제출하여야 한다.","w":"담보 제공이나 주류 보존 명령을 이행하지 않아 출고된 것으로 보는 주류의 신고기한은 사유가 발생한 날이 속하는 분기가 아니라 달의 다음 달 말일이다(출제 당시 주세법 제23조제2항, 현행 제9조제2항).","c":"상","v":1},"관세사2019_36-39-4":{"f":"주류 제조면허가 취소된 후 1년이 지난 자가 주류 제조면허 신청을 한 경우 관할 세무서장은 해당 면허를 하지 아니할 수 있다.","w":"면허 취소 후 2년이 지나지 않으면 면허를 하지 않을 수 있다. 1년이 지났다고 반드시 면허를 주어야 하는 것은 아니다.","c":"중","v":1},"관세사2020_37-38-5":{"f":"주류 제조면허를 받은 자가 그 주류 제조장에서 원료용으로 밑술 또는 술덧을 제조하려는 경우에는 별도의 면허를 받지 아니하여도 된다.","w":"제조면허를 받은 자가 그 제조장에서 원료용 밑술·술덧을 만드는 경우는 별도 면허가 필요 없다.","c":"중","v":1},"관세사2020_37-40-3":{"f":"주정, 탁주 및 맥주 외의 주류를 주류 제조장에서 출고할 때의 가격에는 그 주류의 주세액에 해당하는 금액을 포함하지 아니한다.","w":"주류의 가격에는 주세와 교육세 등 세액이 들어가지 않는다.","c":"상","v":1},"관세사2022_39-38-3":{"f":"납세의무자가 주세를 납부할 목적으로 하는 경우에도 관할 세무서장이 보존을 명한 납세보증주류를 처분하거나 제조장에서 반출할 수 없다.","w":"납세보증주류는 처분하거나 반출할 수 없다. 주세를 납부할 목적이라는 예외는 없다.","c":"중","v":1},"관세사2022_39-40-1":{"f":"주정, 탁주 및 맥주의 과세표준은 그 수량으로 하고 그 외 주류의 과세표준은 주류의 가격으로 한다.","w":"수량을 과세표준으로 하는 것은 주정뿐 아니라 탁주와 맥주도 포함한다.","c":"상","v":1},"관세사2022_39-40-2":{"f":"수입하는 주류의 가격은 관세법 제241조에 따라 수입신고하는 때의 관세의 과세가격과 관세를 합한 금액으로 한다.","w":"수입 주류의 가격은 관세의 과세가격에 관세를 더한 금액이다.","c":"상","v":1},"관세사2022_39-40-4":{"f":"외상 방식으로 통상가격보다 높은 가격으로 반출하는 경우에는 그 반출가격으로 하고, 선매 방식으로 통상가격보다 낮은 가격에 반출하는 경우 반출하는 주류의 가격은 그 통상가격으로 한다.","w":"외상 방식으로 통상가격보다 높게 반출하면 그 반출가격이 주류의 가격이지만, 선매 방식으로 통상가격보다 낮게 반출하면 통상가격으로 한다(주세법 시행령 제5조제1항제2호가목·나목).","c":"상","v":1},"관세사2022_39-40-5":{"f":"무상으로 반출하는 경우로서 통상가격을 산출할 수 없는 때에는 제조원가(원료비ㆍ부원료비ㆍ노무비ㆍ경비 및 일반관리비 중 해당 주류에 배분되어야 할 부분)에 10 % 상당 이윤을 가산한 가격으로 한다.","w":"가산하는 통상이윤은 제조원가의 100분의 10이 맞다. 다만 이때의 제조원가는 회계학상 개념이 아니라 원료비·부원료비·노무비·경비 및 일반관리비(판매비 포함) 중 해당 주류에 배분될 부분으로 구성되는 총금액이다(주세법 시행령 제5조제1항제2호라목).","c":"중","v":1},"관세사2023_40-38-1":{"f":"수입하는 맥주의 과세표준은 수입신고를 하는 때의 수량으로 한다.","w":"맥주의 과세표준은 수량이다. 가격이 아니다.","c":"상","v":1},"관세사2023_40-38-2":{"f":"주류 제조장에서 반출하는 위스키의 반출하는 때의 가격에는 그 주류의 용기 또는 포장에 붙여 반출되는 것으로서 상품정보를 무선으로 식별하도록 제작된 전자인식표의 가격을 포함하지 아니한다.","w":"전자인식표의 가격은 주류의 가격에서 제외한다.","c":"상","v":1},"관세사2023_40-38-4":{"f":"알코올분 95도인 주정에 대한 세율은 1킬로리터당 5만 7천원이다.","w":"알코올분 95도 이하 주정의 세율은 1킬로리터당 5만 7천원이다.","c":"중","v":1},"관세사2023_40-38-5":{"f":"발효주류인 청주에 대한 세율은 100분의 30이다.","w":"청주·약주·과실주(전통주 제외)의 세율은 100분의 30이다. 100분의 72는 증류주류 세율이다.","c":"상","v":1},"관세사2023_40-39-1":{"f":"주류 제조장에서 주류를 반출한 자는 매 분기 주류 제조장에서 반출한 주류의 종류, 알코올분, 수량, 가격, 세율, 산출세액, 공제세액, 환급세액, 납부세액 등을 적은 신고서를 반출한 날이 속하는 분기의 다음 달 25일까지 관할 세무서장에게 제출하여야 한다.","w":"주세의 신고·납부는 분기별이고 기한은 반출한 날이 속한 분기의 다음 달 25일이다. 월별이거나 20일이 아니다.","c":"중","v":1},"관세사2023_40-40-5":{"f":"「주세법」 제21조에 따라 관할 세무서장은 주세 보존을 위하여 필요하다고 인정하는 경우에는 주류 제조자에 대해 납세 보증으로 보존해야 하는 주류의 가격을 정하여 명할 수 있으며 그 주류의 보존기간도 정하여 명할 수 있다.","w":"관할 세무서장은 보존할 주류의 가격뿐 아니라 보존기간도 정하여 명할 수 있다.","c":"중","v":1},"관세사2024_41-37-4":{"f":"밑술이란 효모를 배양ㆍ증식한 것으로서 당분이 포함되어 있는 물질을 알코올 발효시킬 수 있는 재료를 말한다.","w":"효모를 배양·증식한 재료는 밑술이다. 술덧은 발효 원료에 밑술 등을 섞어 발효시킨 것이다.","c":"중","v":1},"관세사2024_41-40-1":{"f":"명예영사관이 공용품으로 직접 수입하는 주류의 경우에는 주세가 면제되지 아니한다.","w":"주세가 면제되는 공용품 직접 수입 기관은 대사관·공사관·총영사관·영사관 등이고, 영사관 중 명예영사관은 제외된다(주세법 제20조제2항제1호, 시행령 제20조제2항제1호라목).","c":"상","v":1},"관세사2025_42-37-1":{"f":"수입하는 주류의 가격은 「관세법」에 따라 수입신고를 하는 때의 관세의 과세가격과 관세를 합한 금액으로 한다.","w":"수입 주류의 가격은 과세가격에 관세를 더한 금액이다.","c":"상","v":1},"관세사2025_42-37-3":{"f":"전통주가 아닌 약주ㆍ과실주ㆍ청주의 세율은 100분의 30으로 한다.","w":"전통주가 아닌 약주·과실주·청주의 세율은 100분의 30이다.","c":"상","v":1},"관세사2025_42-37-4":{"f":"알코올분이 95도를 초과하지 아니하는 주정에 대한 세율은 1킬로리터당 5만 7천원으로 한다.","w":"알코올분 95도 이하 주정의 세율은 1킬로리터당 5만 7천원이다.","c":"중","v":1},"관세사2025_42-37-5":{"f":"주정, 탁주 및 맥주 외의 주류를 주류 제조장에서 반출하는 때의 가격에는 그 주류의 주세액에 해당하는 금액을 포함하지 아니한다.","w":"반출 가격에 주세액은 들어가지 않는다.","c":"상","v":1},"관세사2026_43-37-1":{"f":"주정은 주류의 종류 중 발효주류에 해당하지 아니한다.","w":"주세법은 주류를 주정, 발효주류, 증류주류, 기타 주류로 나눈다. 주정은 발효주류가 아니다.","c":"상","v":1},"관세사2026_43-37-3":{"f":"알코올분 97도인 주정에 대한 세율은 1킬로리터당 5만 8,200원이다.","w":"95도를 넘는 주정은 1도를 초과할 때마다 600원을 더하므로 97도는 5만 7천원에 1,200원을 더한 5만 8,200원이다.","c":"중","v":1},"관세사2026_43-37-4":{"f":"주정으로서 연료용으로 사용되는 것은 면세 대상에 해당한다.","w":"연료용 등 대통령령이 정하는 용도로 쓰는 주정은 주세 면세 대상이다.","c":"중","v":1},"관세사2026_43-37-5":{"f":"주정 중 조주정(粗酒精)에 대해서도 주정과 같은 세율을 적용한다.","w":"조주정은 주정에 포함되고(주세법 제2조제1호가목) 주정 세율인 1킬로리터당 5만 7천원(95도 초과분은 1도마다 600원 가산)을 그대로 적용한다. 조주정의 세율을 경감하는 규정은 없다(제8조제1항제1호).","c":"중","v":1},"관세사2026_43-38-3":{"f":"주류 제조장에서 반출하는 경우 증류주류에 대한 주세의 과세표준은 반출하는 때의 가격으로 한다.","w":"수량을 과세표준으로 하는 것은 주정·탁주·맥주이고, 증류주류는 가격이다.","c":"상","v":1},"관세사2017_34-11-2":{"f":"우정사업 운영에 관한 특례법에 따른 우정사업조직이 제공하는 우편법상 소포 우편물을 방문접수하여 배달하는 용역은 과세가 적용된다.","w":"우정사업조직이 제공하는 우편 용역은 면세이지만, 소포 우편물을 방문접수하여 배달하는 용역은 면세에서 제외되어 과세된다(부가가치세법 시행령 제46조 제1호 가목).","c":"상","v":1},"관세사2017_34-14-1":{"f":"면세사업자와 달리 영세율사업자는 부가가치세법상 납세의무자이다.","w":"영세율은 과세사업이라 영세율사업자는 납세의무자이고 매입세액을 환급받는다. 면세사업자만 납세의무자가 아니다.","c":"상","v":1},"관세사2017_34-22-2":{"f":"재화를 수입하는 자는 사업자에 해당하지 않아도 부가가치세를 납부할 의무가 있다.","w":"재화의 수입은 수입하는 자가 사업자인지와 관계없이 부가가치세 납세의무가 있다(부가가치세법 제3조).","c":"상","v":1},"관세사2017_34-29-2":{"f":"외상판매의 경우 재화가 인도되거나 이용 가능하게 되는 때를 재화의 공급시기로 본다.","w":"외상판매는 대금 수령과 관계없이 재화가 인도되거나 이용 가능하게 되는 때가 공급시기이다. 대가의 각 부분을 받기로 한 때는 완성도기준·중간지급조건부 같은 경우의 공급시기이다.","c":"상","v":1},"관세사2018_35-06-1":{"f":"사업자가 농산물ㆍ축산물ㆍ수산물ㆍ임산물 등의 면세 재화를 운반ㆍ가공하거나 판매 대행하는 등의 용역을 제공하고 그 대가를 받는 경우에는 과세대상이다.","w":"면세 재화 자체의 공급은 면세이지만, 그 재화를 운반·가공·판매대행하는 용역은 면세 대상이 아니므로 과세된다.","c":"상","v":1},"관세사2018_35-11-3":{"f":"미가공 식료품 중 농산물, 축산물, 수산물 및 임산물을 단순히 혼합한 것은 면세 대상에 포함된다.","w":"미가공식료품을 단순히 혼합한 것은 면세 대상에 포함된다(부가가치세법 시행령 제34조).","c":"상","v":1},"관세사2019_36-01-2":{"f":"수출신고가 수리된 물품으로서 선적(船積)되지 아니한 물품을 보세구역에서 반입하는 것은 재화의 수입에 해당하지 아니한다.","w":"수출신고가 수리되었으나 선적되지 않은 물품을 보세구역에서 반입하는 것은 재화의 수입에서 제외된다(부가가치세법 제13조).","c":"상","v":1},"관세사2019_36-02-3":{"f":"주된 사업에 부수되는 것으로서 주된 사업과 관련하여 우연히 또는 일시적으로 공급되는 재화 또는 용역의 공급은 별도의 공급에 해당하며, 그 과세·면세 여부는 주된 사업을 따른다.","w":"우연히·일시적으로 공급되는 재화나 용역은 주된 사업에 포함되지 않고 별도의 공급이다. 다만 과세인지 면세인지는 주된 사업을 따른다.","c":"상","v":1},"관세사2019_36-11-3":{"f":"관세가 무세(無稅)인 재화로서 수입신고한 물품 중 수입신고 수리 전에 변질 또는 손상된 것에 대하여는 부가가치세를 면제한다.","w":"부가가치세가 면제되는 것은 수입신고 수리 전에 변질·손상된 물품이다. 수리 후에 변질·손상된 것은 해당하지 않는다.","c":"중","v":1},"관세사2020_37-05-4":{"f":"「소득세법 시행령」 제9조제1항에 따른 민박, 음식물 판매, 특산물 제조, 전통차 제조 및 그 밖에 이와 유사한 활동은 부가가치세법상 재화 또는 용역을 공급하는 사업을 구분할 때 독립된 사업으로 본다.","w":"소득세법 시행령 제9조 제1항에 따른 민박·음식물 판매·특산물 제조·전통차 제조 등의 활동은 독립된 사업으로 본다.","c":"상","v":1},"관세사2020_37-06-1":{"f":"고용관계에 따라 근로를 제공하는 것은 용역의 공급에 해당하지 아니한다.","w":"고용관계에 따른 근로 제공은 독립성이 없어 용역의 공급으로 보지 않는다.","c":"상","v":1},"관세사2020_37-06-2":{"f":"산업상ㆍ상업상 또는 과학상의 지식ㆍ경험 또는 숙련에 관한 정보를 제공하는 것은 용역의 공급에 해당한다.","w":"산업상·상업상·과학상의 지식·경험·숙련에 관한 정보를 제공하는 것은 재화가 아닌 용역의 공급이다.","c":"상","v":1},"관세사2020_37-06-3":{"f":"사업자가 위탁가공을 위하여 원자재를 국외의 수탁가공 사업자에게 대가 없이 반출하는 것(영세율이 적용되는 것은 제외한다)은 재화의 공급에 해당하지 아니한다.","w":"위탁가공을 위해 원자재를 국외 수탁가공 사업자에게 대가 없이 반출하는 것은 원칙적으로 재화의 공급이 아니다. 영세율이 적용되는 반출은 재화의 공급으로 본다.","c":"상","v":1},"관세사2020_37-06-4":{"f":"계약상 시설물, 권리 등 재화를 사용하게 하는 것은 용역의 공급에 해당한다.","w":"시설물·권리 등 재화를 사용하게 하는 것은 재화의 공급이 아니라 용역의 공급이다(부가가치세법 제11조 제1항 제2호).","c":"상","v":1},"관세사2020_37-08-3":{"f":"재화 또는 용역의 공급시기가 세금계산서 발급일이 속하는 과세기간 내에 도래하는 경우에는 재화 또는 용역을 공급하는 사업자가 그 재화 또는 용역의 공급시기가 되기 전에 세금계산서를 발급하고 그 세금계산서 발급일부터 7일이 지난 후 대가를 받더라도 해당 세금계산서를 발급한 때를재화 또는 용역의 공급시기로 본다.","w":"7일이 지난 뒤 대가를 받아도 세금계산서 발급일을 공급시기로 보는 경우는 계약서에 대금 청구시기와 지급시기를 따로 적고 그 사이가 30일 이내이거나, 공급시기가 세금계산서 발급일이 속하는 과세기간 안에 도래하는 경우다(부가가치세법 제17조 제3항). 청구시기와 지급시기가 같은 과세기간에 있다는 요건은 없다.","c":"중","v":1},"관세사2022_39-07-5":{"f":"수출신고가 수리된 물품으로서 선적되지 아니한 물품을 보세구역에서 반입하는 것은 재화의 수입에 해당하지 아니한다.","w":"수출신고 수리 후 선적되지 않은 물품의 보세구역 반입은 재화의 수입에서 제외된다.","c":"상","v":1},"관세사2022_39-09-1":{"f":"재화의 이동이 필요한 경우 재화의 이동이 개시되는 장소를 공급장소로 한다.","w":"재화의 이동이 필요한 경우 공급장소는 이동이 개시되는 장소이다. 도착하는 장소가 아니다(부가가치세법 제19조).","c":"상","v":1},"관세사2022_39-09-3":{"f":"시설물, 권리 등 재화가 사용되는 경우 해당 재화가 사용되는 장소를 공급장소로 한다.","w":"용역의 공급장소는 역무가 제공되거나 시설물·권리 등 재화가 사용되는 장소이다. 재화 제공자의 주소지가 아니다.","c":"상","v":1},"관세사2022_39-09-4":{"f":"국외사업자가 공급하는 전자적 용역의 경우 용역을 공급받는 자의 사업장 소재지, 주소지 또는 거소지를 공급장소로 한다.","w":"전자적 용역은 공급받는 자의 사업장 소재지, 주소지 또는 거소지가 공급장소이다.","c":"상","v":1},"관세사2022_39-09-5":{"f":"국제운송의 경우 사업자가 비거주자이면 여객이 탑승하거나 화물이 적재되는 장소를 공급장소로 한다.","w":"국내외에 걸친 국제운송에서 사업자가 비거주자나 외국법인이면 여객이 탑승하거나 화물이 적재되는 장소가 공급장소이다(부가가치세법 제20조 제1항 제2호). 비거주자의 거소지는 기준이 아니다.","c":"상","v":1},"관세사2022_39-13-1":{"f":"중계무역 방식의 거래로서 국내 사업장에서 계약과 대가 수령 등 거래가 이루어지는 것은 영세율 적용대상이다.","w":"영세율이 적용되는 중계무역 방식의 수출은 국내 사업장에서 계약과 대가 수령이 이루어지는 경우이다. 국외 사업장에서 이루어진 거래는 국외거래로 과세대상이 아니다.","c":"상","v":1},"관세사2022_39-13-3":{"f":"수산생물질병 관리법에 따른 수산동물에 대한 진료용역은 부가가치세 면세대상이다.","w":"가축·수산동물에 대한 진료용역은 면세 대상이다.","c":"상","v":1},"관세사2022_39-13-4":{"f":"수집용 우표의 공급은 과세대상이다.","w":"우표는 면세이지만 수집용 우표는 면세에서 제외되어 과세된다.","c":"상","v":1},"관세사2022_39-13-5":{"f":"국외에서 공급하는 용역은 영세율을 적용한다.","w":"국외에서 공급하는 용역에는 영세율을 적용한다(부가가치세법 제22조).","c":"상","v":1},"관세사2023_40-06-4":{"f":"사업자가 자기생산ㆍ취득재화를 자기의 고객에게 증여하는 경우로서 증여하는 재화의 대가가 주된 거래인 재화의 공급에 대한 대가에 포함되는 경우는 재화의 공급으로 보지 아니한다.","w":"고객에게 증여하는 재화의 대가가 주된 거래의 공급대가에 포함되는 경우에는 사업상 증여(공급 간주)에서 제외된다.","c":"상","v":1},"관세사2023_40-11-1":{"f":"위탁가공무역 방식의 수출로서 국내 사업장에서 계약과 대가 수령 등 거래가 이루어지는 것은 영세율 적용대상 수출에 해당한다.","w":"위탁가공무역 방식의 수출로 국내 사업장에서 계약과 대가 수령이 이루어지면 영세율 적용 대상이다.","c":"상","v":1},"관세사2023_40-12-4":{"f":"「산업교육진흥 및 산학연협력촉진에 관한 법률」 제25조에 따른 산학협력단에서 수강생에게 지식을 가르치는 것은 면세하는 교육 용역에 해당한다.","w":"산학협력단의 교육용역은 면세하는 교육 용역에 해당한다.","c":"상","v":1},"관세사2023_40-14-1":{"f":"외화를 획득하기 위한 용역의 공급으로서 수출업자와 직접 도급계약에 의하여 수출재화를 임가공하는 수출재화임가공용역의 사업자가 부가가치세를 별도로 적은 세금계산서를 발급한 경우 그 수출재화임가공용역에 대하여 영세율을 적용하지 아니한다.","w":"수출재화임가공용역은 영세율이 적용되지만, 사업자가 부가가치세를 별도로 적은 세금계산서를 발급하면 영세율을 적용하지 않는다.","c":"상","v":1},"관세사2023_40-14-2":{"f":"골동품(「관세법」별표 관세율표 번호 제9706호의 것)은 면세하는 예술창작품에 해당하지 않는다.","w":"골동품은 예술창작품 면세 대상에서 제외되어 과세된다.","c":"상","v":1},"관세사2023_40-14-4":{"f":"면세의 포기를 신고한 사업자는 신고한 날부터 3년간 부가가치세를 면제받지 못한다.","w":"면세를 포기하면 신고한 날부터 3년간 면세를 다시 적용받을 수 없다. 5년이 아니다.","c":"상","v":1},"관세사2023_40-14-5":{"f":"「항공사업법」에 따른 상업서류 송달용역은 영세율이 적용되는 외국항행용역의 범위에 포함된다.","w":"상업서류 송달용역은 외국항행용역에 포함되어 영세율이 적용된다.","c":"상","v":1},"관세사2024_41-06-4":{"f":"사업자가 위탁가공을 위하여 영세율을 적용받은 원자재를 국외의 수탁가공 사업자에게 대가 없이 반출하는 것은 재화의 공급으로 본다.","w":"위탁가공용 원자재의 무상 반출은 재화의 공급이 아니지만, 영세율을 적용받는 경우에는 재화의 공급으로 본다.","c":"상","v":1},"관세사2024_41-07-4":{"f":"과세사업자가 재화를 수입하는 경우 부가가치세를 신고 납부하면 그 부가가치세 납부세액은 매입세액으로 공제 받을 수 있다.","w":"과세사업에 사용할 재화를 수입하며 낸 부가가치세는 수입세금계산서에 따라 매입세액으로 공제받을 수 있다.","c":"상","v":1},"관세사2024_41-08-5":{"f":"주된 사업에 부수되는 것으로서 주된 사업과 관련하여 우연히 공급되는 재화의 공급은 별도의 공급으로 본다.","w":"우연히·일시적으로 공급되는 재화는 주된 사업에 포함되지 않고 별도의 공급이며, 과세·면세 여부만 주된 사업을 따른다.","c":"상","v":1},"관세사2024_41-10-4":{"f":"","w":"내국신용장이나 구매확인서에 의한 재화 공급은 영세율이 적용되지만 금지금(金地金)은 그 대상에서 빠진다(부가가치세법 제21조 제2항 제3호, 시행령 제31조 제2항 제1호).","c":"상","v":1},"관세사2024_41-14-5":{"f":"영세율과 면세에 동시에 해당되는 경우에는 면세가 적용되므로, 영세율을 적용받기 위해서는 면세를 포기하여야 한다.","w":"영세율과 면세에 동시에 해당하면 면세가 적용되고, 영세율을 적용받으려면 면세 포기를 신고해야 한다.","c":"상","v":1},"관세사2025_42-03-1":{"f":"수출신고가 수리된 물품으로서 선적되지 아니한 물품을 보세구역에서 반입하는 경우 재화의 수입에 해당하지 아니한다.","w":"수출신고가 수리된 물품이 선적되지 않은 채 보세구역에서 반입되는 것은 재화의 수입에서 제외된다.","c":"상","v":1},"관세사2025_42-03-2":{"f":"사업자가 자기의 과세사업을 위하여 사용할 목적으로 수입하는 재화의 수입에 대한 부가가치세액은 매출세액에서 공제한다.","w":"과세사업용으로 수입하는 재화의 부가가치세액은 매입세액으로 매출세액에서 공제한다.","c":"상","v":1},"관세사2025_42-03-3":{"f":"외국으로부터 국내에 도착한 물품으로서 수입신고가 수리되기 전의 것을 국내에 반입하는 것은 재화의 수입에 해당한다.","w":"외국에서 도착한 물품이 수입신고 수리 전에 국내로 반입되면 재화의 수입에 해당한다.","c":"상","v":1},"관세사2025_42-03-5":{"f":"외국 선박에 의하여 공해에서 잡힌 수산물로서 수입신고가 수리되기 전의 것을 국내에 반입하는 것은 재화의 수입에 해당한다.","w":"외국 선박이 공해에서 잡은 수산물도 수입신고 수리 전에 국내에 반입되면 재화의 수입이다. 대한민국 선박이 잡은 수산물은 수입이 아니다.","c":"상","v":1},"관세사2025_42-05-4":{"f":"건설업의 경우 건설사업자가 건설자재의 전부 또는 일부를 부담하는 것은 용역의 공급으로 본다.","w":"건설업은 건설사업자가 자재를 전부 또는 일부 부담해도 용역의 공급으로 본다.","c":"상","v":1},"관세사2025_42-10-1":{"f":"공급단위를 구획할 수 없는 용역을 계속적으로 공급하는 경우에는 대가의 각 부분을 받기로 한 때를 공급시기로 본다.","w":"공급단위를 구획할 수 없는 용역의 계속 공급은 대가의 각 부분을 받기로 한 때가 공급시기이다. 역무 제공이 끝난 때가 아니다.","c":"상","v":1},"관세사2025_42-10-2":{"f":"조건부 판매의 경우에는 조건이 성취되는 때를 공급시기로 본다.","w":"조건부 판매와 기한부 판매는 조건이 성취되거나 기한이 지나 판매가 확정되는 때가 공급시기이다.","c":"상","v":1},"관세사2025_42-10-4":{"f":"국외사업자가 전자적 용역을 국내에 제공하는 경우 용역을 공급받는 자의 사업장 소재지, 주소지 또는 거소지를 용역의 공급장소로 한다.","w":"전자적 용역은 공급받는 자의 사업장 소재지·주소지·거소지가 공급장소이다.","c":"상","v":1},"관세사2025_42-10-5":{"f":"재화의 이동이 필요한 경우 재화의 이동이 개시되는 장소를 재화의 공급장소로 한다.","w":"재화의 이동이 필요하면 이동이 개시되는 장소가 공급장소이다.","c":"상","v":1},"관세사2025_42-11-2":{"f":"영세율이 적용되는 재화를 공급하는 사업자가 예정ㆍ확정신고 시 영세율 첨부서류를 제출하지 아니하더라도 영세율은 적용되며, 가산세가 부과된다.","w":"영세율 첨부서류를 제출하지 않았다고 영세율 적용이 배제되지는 않는다. 영세율 과세표준 신고불성실 가산세 등 불이익이 따른다.","c":"중","v":1},"관세사2025_42-13-3":{"f":"부가가치세가 면세되는 인적용역으로서 개인이 공급하는 학술연구용역은 「부가가치세법 시행령」제57조에 따라 면세 포기를 신고할 수 없다.","w":"시행령 제57조가 면세 포기 신고 대상으로 정한 것은 영세율 적용 대상과, 학술등 연구단체가 연구와 관련해 실비나 무상으로 공급하는 재화·용역이다. 개인이 인적용역으로 공급하는 학술연구용역은 여기에 들지 않는다.","c":"중","v":1},"관세사2026_43-06-1":{"f":"","w":"질권·저당권·양도담보의 목적으로 동산, 부동산 및 부동산상의 권리를 제공하는 것은 재화의 공급으로 보지 않는다(부가가치세법 제10조 제9항 제1호).","c":"상","v":1},"관세사2026_43-06-3":{"f":"","w":"민사집행법에 따른 경매로 재화를 인도하거나 양도하는 것은 재화의 공급으로 보지 않는다.","c":"상","v":1},"관세사2026_43-06-4":{"f":"","w":"국세징수법에 따른 공매로 재화를 인도하거나 양도하는 것은 재화의 공급으로 보지 않는다.","c":"상","v":1},"관세사2026_43-06-5":{"f":"","w":"도시 및 주거환경정비법 등에 따른 수용절차에서 수용된 재화의 대가를 받는 것은 재화의 공급으로 보지 않는다.","c":"상","v":1},"관세사2026_43-08-4":{"f":"납세의무가 있는 사업자가 「여신전문금융업법」에 따라 등록한 시설대여업자로부터 시설 등을 임차하고 그 시설 등을 공급자로부터 직접 인도받은 경우 해당 사업자가 공급자로부터 재화를 직접 공급받은 것으로 보아 공급시기의 규정을 적용한다.","w":"시설대여업자에게서 임차한 시설을 공급자로부터 직접 인도받으면 임차한 사업자가 공급자로부터 재화를 직접 공급받은 것으로 보아 공급시기를 정한다.","c":"상","v":1},"관세사2026_43-10-4":{"f":"수출업자와 직접 도급계약에 의하여 수출재화를 임가공하는 수출재화임가공용역(수출 재화염색임가공을 포함)은 사업자가 부가가치세를 별도로 적은 세금계산서를 발급한 경우에는 영세율을 적용하지 아니한다.","w":"수출재화임가공용역은 영세율 대상이지만, 부가가치세를 별도로 적은 세금계산서를 발급했다면 영세율을 적용하지 않는다.","c":"상","v":1},"관세사2026_43-11-3":{"f":"장의업자가 제공하는 장의용역은 부가가치세를 면제한다.","w":"장의업자가 제공하는 장의용역은 면세이다.","c":"상","v":1},"관세사2026_43-12-1":{"f":"공동주택 임대용역은 그 공동주택이 국민주택규모를 초과하는 경우에도 부가가치세를 면제한다.","w":"주택 임대용역은 규모와 관계없이 면세이다. 국민주택규모 초과 여부로 갈리는 것은 주택의 양도(공급)이다.","c":"상","v":1},"관세사2026_43-13-1":{"f":"학술 등 연구단체가 그 연구와 관련하여 재화 또는 용역을 실비 또는 무상으로 공급하는 경우 부가가치세 면세포기가 가능하다.","w":"학술·기술 연구단체가 연구와 관련해 실비 또는 무상으로 공급하는 용역이 면세 포기가 가능한 대상이다. 실비나 무상이 아닌 공급은 처음부터 면세 대상이 아니다.","c":"상","v":1},"관세사2026_43-13-2":{"f":"면세의 포기를 신고한 사업자는 신고한 날부터 3년간 부가가치세를 면제받지 못한다.","w":"면세를 포기한 사업자는 신고한 날부터 3년간 면세를 다시 적용받지 못한다. 5년이 아니다.","c":"상","v":1},"관세사2026_43-13-3":{"f":"면세를 포기하려는 사업자는 면세포기신고서를 관할 세무서장에게 제출(국세정보통신망에 의한 제출 포함)하여야 한다. 이 경우 지체 없이 사업자등록을 하여야 한다.","w":"면세포기신고서는 관할 세무서장에게 내고 지체 없이 사업자등록을 한다. 관할 지방국세청장에게 제출하는 것이 아니고, 30일이라는 기한도 없다.","c":"상","v":1},"관세사2026_43-13-4":{"f":"","w":"면세 포기를 신고한 사업자가 신고한 날부터 3년이 지난 뒤 면세를 받으려면 면세적용신고서를 제출한다. 6개월 전까지라는 기한은 맞지 않다.","c":"중","v":1},"관세사2017_34-15-5":{"f":"사업자가 개인서비스용역을 제공하고 그 대가와 함께 받는 종업원의 봉사료를 자기의 수입금액에 계상하는 경우 그 봉사료는 공급가액에 포함한다.","w":"봉사료를 종업원에게 그대로 지급하고 별도로 구분 기록하면 공급가액에서 제외되지만, 사업자가 자기의 수입금액에 계상하면 공급가액에 포함된다.","c":"상","v":1},"관세사2017_34-18-5":{"f":"세관장이 수정수입세금계산서를 발급하는 경우에는 추가되는 금액은 검은색 글씨로 쓰고, 차감되는 금액은 붉은색 글씨로 쓰거나 음의 표시를 하여 발급한다.","w":"수정세금계산서에서 추가되는 금액은 검은색 글씨, 차감되는 금액은 붉은색 글씨 또는 음(-)의 표시로 쓴다. 색깔이 거꾸로 되어 있다.","c":"상","v":1},"관세사2017_34-20-4":{"f":"대손세액공제를 받은 사업자가 대손금액의 전부 또는 일부를 회수한 경우에는 회수한 대손금액에 관련된 대손세액을 회수한 날이 속하는 과세기간의 매출세액에 더한다.","w":"회수한 대손세액은 공급일이 아니라 회수한 날이 속하는 과세기간의 매출세액에 가산하고, 수정신고로 처리하지 않는다.","c":"상","v":1},"관세사2017_34-31-3":{"f":"사업자가 부가가치세의 예정신고와 납부를 할 때에는 가산세에 관한 규정을 적용하지 아니한다.","w":"예정신고·납부에는 부가가치세법상 가산세와 국세기본법상 무신고·과소신고·납부불성실 가산세를 적용하지 않는다. 확정신고에서 정산한다.","c":"상","v":1},"관세사2017_34-32-1":{"f":"사업자가 사업자등록 신청 기한까지 등록을 신청하지 아니한 경우의 가산세는 사업 개시일부터 등록을 신청한 날의 직전일까지의 공급가액 합계액의 1퍼센트에 해당하는 금액으로 한다.","w":"사업자등록 미등록 가산세는 공급가액의 1퍼센트이다(부가가치세법 제60조).","c":"상","v":1},"관세사2017_34-32-2":{"f":"사업자가 세금계산서의 발급시기가 지난 후 해당 재화 또는 용역의 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 세금계산서를 발급하는 경우의 가산세는 그 공급가액의 1퍼센트에 해당하는 금액으로 한다.","w":"세금계산서를 늦게 발급한 경우(확정신고기한 이내)의 가산세는 공급가액의 1퍼센트이다.","c":"상","v":1},"관세사2017_34-32-3":{"f":"사업자가 세금계산서의 발급시기가 지난 후 해당 재화 또는 용역의 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 세금계산서를 발급하지 아니한 경우의 가산세는 그 공급가액의 2퍼센트에 해당하는 금액으로 한다.","w":"확정신고기한까지도 세금계산서를 발급하지 않으면 가산세는 공급가액의 2퍼센트이다. 0.5퍼센트가 아니다.","c":"상","v":1},"관세사2017_34-32-5":{"f":"사업자가 재화 또는 용역을 공급받고 실제로 재화 또는 용역을 공급하는 자가 아닌 자의 명의로 세금계산서를 발급받은 경우의 가산세는 그 공급가액의 2퍼센트에 해당하는 금액으로 한다.","w":"타인 명의로 세금계산서를 발급받으면 공급가액의 2퍼센트 가산세가 붙는다. 1퍼센트가 아니다.","c":"상","v":1},"관세사2017_34-34-2":{"f":"사업자가 감가상각자산인 사업 설비를 확장 또는 증축하는 경우에는 조기환급 대상이 된다.","w":"사업설비를 신설·취득·확장·증축하는 경우는 조기환급 사유이다.","c":"상","v":1},"관세사2017_34-35-5":{"f":"주로 최종소비자를 대상으로 거래하는 음식 및 숙박업과 서비스업에 대해서는 추계 결정·경정 방법으로서 국세청장이 정하는 입회조사기준에 따라 계산하는 방법을 적용할 수 있다.","w":"음식·숙박업과 서비스업처럼 주로 최종소비자를 대상으로 하는 업종은 입회조사기준에 따라 추계로 결정·경정할 수 있다.","c":"상","v":1},"관세사2017_34-36-1":{"f":"간이과세자의 해당 과세기간에 대한 공급대가의 합계액이 4천800만원 미만이면 부가가치세 납부세액의 납부의무를 면제한다.","w":"간이과세자의 해당 과세기간 공급대가 합계액이 4천800만원 미만이면 납부의무가 면제된다(부가가치세법 제69조 제1항). 출제 당시(2017) 기준금액은 2천400만원이었고, 2019년 3천만원을 거쳐 2021년부터 4천800만원이 되었다.","c":"중","v":1},"관세사2017_34-39-2":{"f":"사업자는 장부와 발급하거나 발급받은 세금계산서, 수입세금계산서 또는 영수증을 그 거래사실이 속하는 과세기간에 대한 확정신고 기한 후 5년간 보존하여야 한다.","w":"부가가치세법상 장부와 증빙의 보존기간은 확정신고 기한 후 5년이다.","c":"상","v":1},"관세사2018_35-12-4":{"f":"위탁판매의 경우 수탁자가 재화를 인도할 때에 위탁자를 알 수 있는 경우에는 위탁자의 명의로 세금계산서를 발급하며, 이 경우 수탁자의 등록번호를 덧붙여 적는다.","w":"위탁자를 알 수 있으면 위탁자 명의로 발급하고 수탁자의 등록번호를 덧붙여 적는다. 수탁자 명의로 발급하는 것은 위탁자를 알 수 없는 경우이다.","c":"하","v":1},"관세사2018_35-13-1":{"f":"매입자발행세금계산서를 발행하려는 사업자는 해당 재화 또는 용역의 공급시기가 속하는 과세기간의 종료일부터 1년 이내에 거래사실확인신청서에 거래사실을 객관적으로 입증할 수 있는 서류를 첨부하여 신청인 관할 세무서장에게 거래사실의 확인을 신청하여야 한다.","w":"거래사실 확인 신청 기한은 공급시기가 속하는 과세기간의 종료일부터 1년 이내이다(부가가치세법 시행령 제71조의2 제3항). 출제 당시(2018)에는 3개월이었고, 2019년 6개월, 2024년 1년으로 늘었다.","c":"중","v":1},"관세사2018_35-15-5":{"f":"대손세액 공제의 범위는 사업자가 부가가치세가 과세되는 재화 또는 용역을 공급한 후 그 공급일부터 10년이 지난 날이 속하는 과세기간에 대한 확정신고 기한까지 파산ㆍ강제집행이나 그 밖에 대통령령으로 정하는 사유로 확정되는 대손세액(결정 또는 경정으로 증가된 과세표준에 대하여 부가가치세액을 납부하지 아니한 경우 해당 대손세액은 제외)으로 한다.","w":"결정·경정으로 증가된 과세표준에 대한 부가가치세를 납부하지 않았다면 그 대손세액은 공제 범위에서 빠진다. 납부한 경우가 아니다. 대손 확정 기한도 2020년 개정으로 공급일부터 5년에서 10년으로 늘었다.","c":"중","v":1},"관세사2018_35-17-1":{"f":"통상적으로 용기 또는 포장을 해당 사업자에게 반환할 것을 조건으로 그 용기대금과 포장비용을 공제한 금액으로 공급하는 경우 그 용기대금과 포장비용은 공급가액에 포함하지 아니한다.","w":"반환을 조건으로 용기·포장 대금을 뺀 금액으로 공급하는 경우 그 용기대금과 포장비용은 공급가액에 넣지 않는다.","c":"상","v":1},"관세사2018_35-19-3":{"f":"의제매입세액 공제신고서를 국세기본법 시행령 제25조제1항에 따라 과세표준수정 신고서와 함께 제출하는 경우에도 의제매입세액을 공제한다.","w":"의제매입세액 공제신고서를 과세표준수정신고서와 함께 제출하는 경우에도 공제를 받을 수 있다(부가가치세법 시행령 제84조 제7항, 제74조 제1호).","c":"중","v":1},"관세사2018_35-22-1":{"f":"재화의 공급으로 보지 않는 사업의 양도에 따라 그 사업을 양수받는 자는 그 대가를 지급하는 때에 그 대가를 받은 자로부터 부가가치세를 징수하여 그 대가를 지급하는 날이 속하는 달의 다음 달 25일까지 사업장 관할 세무서장에게 납부할 수 있다.","w":"사업양수자의 대리납부는 재화의 공급으로 보지 않는 사업양도(해당 여부가 분명하지 않은 경우 포함)에 대해 할 수 있는 제도로, 대가를 지급한 날이 속하는 달의 다음 달 25일까지 납부한다(부가가치세법 제52조 제4항). 10일 이내라는 기한도 없고 반드시 납부해야 하는 의무도 아니다.","c":"상","v":1},"관세사2018_35-24-4":{"f":"재해 또는 그 밖의 불가항력으로 인하여 발급받은 세금계산서가 소멸되어 제출하지 못한 경우 거래상대방이 제출한 세금계산서에 의하여 매입세액이 확인되면 납부세액을 계산할 때 이를 공제한다.","w":"불가항력으로 세금계산서가 없어졌더라도 거래상대방이 제출한 세금계산서로 매입세액이 확인되면 공제한다.","c":"상","v":1},"관세사2018_35-25-2":{"f":"납부유예를 승인받은 경우 유예기간은 승인일부터 1년으로 하며, 1년을 넘겨 계속 적용받을 수는 없다.","w":"납부유예는 정해진 기간 동안만 적용된다. 취소사유가 없다고 해서 1년을 넘어 계속 적용되는 것이 아니다.","c":"중","v":1},"관세사2018_35-28-1":{"f":"세금계산서를 발급하거나 발급받을 수 있으므로 세금계산서와 관련된 가산세가 적용되는 경우가 있다.","w":"간이과세자도 세금계산서를 발급하거나 발급받을 수 있고, 세금계산서 불성실이나 합계표 불성실 등의 가산세가 적용된다.","c":"중","v":1},"관세사2018_35-28-2":{"f":"제조업을 경영하는 간이과세자는 농어민이나 개인으로부터 직접 공급받은 면세 농산물등에 대해서 의제매입세액공제를 적용받을 수 없다.","w":"2020년 12월 개정(2021년 7월 시행)으로 간이과세자의 의제매입세액공제가 없어져 지금은 간이과세자가 이 공제를 받지 못한다. 출제 당시에도 공제신고서만 내면 되는 경우는 제조업자가 농어민에게서 직접 공급받은 때였고, 개인에게서 산 것은 계산서 등을 함께 내야 했다.","c":"중","v":1},"관세사2018_35-28-3":{"f":"납부할 의무가 면제되는 경우에는 대통령령으로 정하는 고정 사업장이 없는 경우에 한하여 사업자 미등록에 따른 가산세를 부과하지 아니한다.","w":"납부의무가 면제되는 간이과세자라도 대통령령이 정하는 고정 사업장이 있으면 미등록 가산세가 부과된다.","c":"상","v":1},"관세사2018_35-28-4":{"f":"간이과세자는 공급받는 자의 파산 등으로 대손이 되어도 대손세액공제를 적용받을 수 없다.","w":"대손세액공제는 일반과세자에게만 적용하고 간이과세자에게는 적용하지 않는다.","c":"상","v":1},"관세사2018_35-29-4":{"f":"조기환급세액은 영의 세율이 적용되는 공급분에 관련된 매입세액ㆍ시설투자에 관련된 매입세액 또는 국내공급분에 대한 매입세액을 구분하지 아니하고 사업장별로 해당 매출세액에서 매입세액을 공제하여 계산한다.","w":"조기환급세액은 영세율 공급분·시설투자분·국내공급분 매입세액을 나누지 않고 사업장별로 매출세액에서 매입세액 전체를 빼서 계산한다.","c":"중","v":1},"관세사2019_36-05-1":{"f":"사업자는 장부와 세금계산서, 수입세금계산서 또는 영수증을 그 거래사실이 속하는 과세기간에 대한 확정신고 기한 후 5년간 보존하여야 한다.","w":"부가가치세법상 보존기간은 5년이다.","c":"상","v":1},"관세사2019_36-05-2":{"f":"납부세액에서 부가가치세법 및 다른 법률에서 규정하고 있는 부가가치세의 감면세액 및 공제세액을 빼고 가산세를 더한 세액의 1천분의 747을 부가가치세로, 1천분의 253을 지방소비세로 한다.","w":"현행 배분 비율은 부가가치세 74.7퍼센트, 지방소비세 25.3퍼센트이다(부가가치세법 제72조 제1항). 출제 당시(2019)에는 85 대 15였다.","c":"중","v":1},"관세사2019_36-05-4":{"f":"납세관리인을 정한 사업자가 이를 변경한 경우에는 납세지 관할 세무서장에게 신고하여야 한다.","w":"납세관리인을 정하거나 변경하면 납세지 관할 세무서장에게 신고해야 한다.","c":"상","v":1},"관세사2019_36-05-5":{"f":"납세지 관할 세무서장은 부가가치세의 납세보전 또는 조사를 위하여 납세의무자에게 부가 가치세와 관계되는 사항을 질문할 수 있으며, 장부ㆍ서류 또는 그 밖의 물건의 제출을 명할 수 있다.","w":"세무서장은 질문뿐 아니라 장부·서류·물건의 제출을 명할 수 있다.","c":"상","v":1},"관세사2019_36-17-1":{"f":"세관장은 수입되는 재화에 대한 부가가치세를 징수할 때에는 수입세금계산서를 수입하는 자에게 발급하여야 한다.","w":"수입세금계산서는 수입하는 자에게 발급한다. 세관 소재지 관할 세무서장에게 발급하지 않는다.","c":"상","v":1},"관세사2019_36-17-3":{"f":"","w":"수입세금계산서는 일반 세금계산서 발급 규정(부가가치세법 제32조 제1항)을 준용해 발급한다(시행령 제72조 제1항). 그 필요적 기재사항은 공급하는 자의 등록번호와 명칭, 공급받는 자의 등록번호, 공급가액과 부가가치세액, 작성 연월일이고 관세의 과세표준과 관세액은 들어 있지 않다.","c":"중","v":1},"관세사2019_36-17-4":{"f":"부가가치세가 면제되는 경우 그 면제되는 사유는 수입세금계산서의 필요적 기재사항이 아니다.","w":"면제 사유는 수입세금계산서의 필요적 기재사항이 아니다.","c":"중","v":1},"관세사2019_36-17-5":{"f":"수입세금계산서에 기재되어 있는 부가가치세액에 대해서는 사업에 사용했거나 사용할 목적이라면 매입세액공제를 적용한다.","w":"수입세금계산서의 부가가치세액은 사업을 위한 것이면 매입세액으로 공제된다.","c":"상","v":1},"관세사2019_36-22-1":{"f":"간이과세자의 해당 과세기간에 대한 공급대가의 합계액이 4천800만원 미만이면 그 과세기간의 납부세액에 대한 납부의무는 면제된다.","w":"(출제 당시 기준 3천만원 미만이어서 X. 현행은 4천800만원 미만이므로 3천600만원이면 면제된다.)","c":"중","v":1,"old":1,"ow":"출제 당시 정답 X. 2020.12.22 개정(2021.7.1 시행)으로 간이과세자 납부의무 면제 기준이 공급대가 4천800만원 미만으로 올라 3,600만원이면 납부의무가 면제되므로 지금은 맞는 문장이다(부가가치세법 제69조제1항)."},"관세사2019_36-22-2":{"f":"음식점업을 영위하는 간이과세자가 부가가치세가 과세되는 재화 또는 용역을 공급하고 세금계산서의 발급시기에 신용카드매출전표를 발급하는 경우에는 그 발급금액의 1.3 %에 해당하는 금액을 연간 1천만원을 한도로 하여 납부세액에서 공제한다.","w":"현행 신용카드매출전표 발급 세액공제는 발급금액의 1.3퍼센트, 연간 1천만원 한도이다(2026년 12월 31일까지. 그 뒤에는 1퍼센트, 500만원 한도. 부가가치세법 제46조 제1항 제3호). 출제 당시에는 음식점업·숙박업 간이과세자의 공제율이 2.6퍼센트였다.","c":"중","v":1},"관세사2019_36-22-3":{"f":"결정 또는 경정한 공급대가의 합계액이 간이과세자 기준금액 이상인 개인사업자는 그 결정 또는 경정한 날이 속하는 과세기간까지 간이과세자로 본다.","w":"결정·경정한 공급대가가 기준금액 이상이어도 그 결정·경정한 날이 속하는 과세기간까지는 간이과세자로 본다. 다음 과세기간까지가 아니다.","c":"중","v":1},"관세사2019_36-22-5":{"f":"사업장 관할 세무서장은 간이과세자에 대하여 직전 과세기간에 대한 납부세액의 50퍼센트를 1월 1일부터 6월 30일까지(예정부과기간)의 납부세액으로 결정하여 예정부과기간이 끝난 후 25일 이내까지 징수한다.","w":"간이과세자의 예정부과기간은 1월 1일부터 6월 30일이고 징수는 그 기간이 끝난 후 25일 이내이다.","c":"상","v":1},"관세사2019_36-23-1":{"f":"세금계산서의 발급시기가 지난 후 해당 재화 또는 용역의 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 세금계산서를 발급하는 경우의 가산세는 그 공급가액의 1퍼센트에 해당하는 금액으로 한다.","w":"지연발급 가산세는 공급가액의 1퍼센트이다.","c":"상","v":1},"관세사2019_36-23-2":{"f":"발급한 세금계산서의 필요적 기재사항의 전부 또는 일부가 착오 또는 과실로 적혀 있지 아니하거나 사실과 다른 경우(해당 세금계산서에 적힌 나머지 필요적 기재사항 또는 임의적 기재사항으로 보아 거래사실이 확인되는 경우는 제외한다)의 가산세는 그 공급가액의 1퍼센트에 해당하는 금액으로 한다.","w":"필요적 기재사항 누락·오기 가산세는 공급가액의 1퍼센트이다.","c":"상","v":1},"관세사2019_36-23-3":{"f":"재화 또는 용역을 공급하고 실제로 재화 또는 용역을 공급하는 자가 아닌 자 또는 실제로 재화 또는 용역을 공급받는 자가 아닌 자의 명의로 세금계산서를 발급한 경우의 가산세는 그 공급가액의 2퍼센트에 해당하는 금액으로 한다.","w":"타인 명의로 세금계산서를 발급한 경우의 가산세는 공급가액의 2퍼센트이다.","c":"상","v":1},"관세사2019_36-23-5":{"f":"전자세금계산서를 발급하여야 할 의무가 있는 자가 전자세금계산서를 발급하지 아니하고 세금계산서의 발급시기에 전자세금계산서 외의 세금계산서를 발급한 경우의 가산세는 그 공급가액의 1퍼센트에 해당하는 금액으로 한다.","w":"전자세금계산서 의무자가 종이로 발급하면 가산세는 공급가액의 1퍼센트이다.","c":"상","v":1},"관세사2019_36-24-2":{"f":"부가가치세 납부유예 대상인 중소기업은 직전 사업연도에 공급한 재화 또는 용역의 공급 가액의 합계액에서 수출액이 차지하는 비율이 30퍼센트 이상이거나 수출액이 50억원 이상의 요건을 충족하여야 한다.","w":"납부유예 요건은 중소기업이면 직전 사업연도 공급가액 중 수출액 비율이 30퍼센트 이상이거나 수출액이 50억원 이상, 중견기업이면 수출액 비율 30퍼센트 이상이다(부가가치세법 시행령 제91조의2 제1항 제2호). 두 기준을 함께 갖출 필요는 없다.","c":"중","v":1},"관세사2019_36-25-4":{"f":"국내사업장이 없는 비거주자 또는 외국법인으로부터 국내에서 용역 또는 권리를 공급받는 자는 대가를 지급하는 때에 그 공급하는 자로부터 부가가치세를 징수하여야 한다.","w":"대리납부는 대가를 지급하는 때에 징수한다. 예정신고기간이나 과세기간 종료일이 아니다.","c":"상","v":1},"관세사2019_36-26-4":{"f":"납세지 관할 세무서장은 조기환급기간에 대한 환급세액을 각 조기환급기간별로 해당 조기환급신고기한이 지난 후 15일 이내에 사업자에게 환급하여야 한다.","w":"조기환급은 신고기한이 지난 후 15일 이내에 환급한다. 일반 환급의 30일보다 짧다.","c":"상","v":1},"관세사2019_36-28-1":{"f":"법인사업자와 직전 연도의 사업장별 재화 및 용역의 공급가액(면세공급가액을 포함한다)의 합계액이 8천만원 이상인 개인사업자는 전자세금계산서를 발급하여야 한다.","w":"(출제 당시 기준 3억원 이상이어서 X. 현행은 면세공급가액을 포함한 합계 8천만원 이상.)","c":"중","v":1},"관세사2019_36-28-2":{"f":"전자세금계산서를 발급하여야 할 사업자가 전자세금계산서를 발급하였을 때에는 전자세금계산서 발급일의 다음 날까지 전자세금계산서 발급명세를 국세청장에게 전송하여야 한다.","w":"발급명세 전송기한은 발급일의 다음 날까지이다.","c":"상","v":1},"관세사2019_36-28-3":{"f":"관계 증명서류 등에 따라 실제거래사실이 확인되는 경우로서 해당 거래일을 작성 연월일로 하여 세금계산서를 발급하는 경우에는 재화 또는 용역의 공급일이 속하는 달의 다음 달 10일까지 세금계산서를 발급할 수 있다.","w":"실제거래사실이 확인되는 경우에는 해당 거래일을 작성 연월일로 하여 다음 달 10일까지 발급할 수 있다(부가가치세법 제34조 제3항 제3호). 달의 말일을 작성 연월일로 하는 것은 거래처별로 한 달 공급가액을 합쳐 발급하는 경우다.","c":"상","v":1},"관세사2019_36-28-5":{"f":"위탁매입 또는 대리인에 의한 매입의 경우에는 공급자가 위탁자 또는 본인을 공급받는 자로 하여 세금계산서를 발급하며, 이 경우 수탁자 또는 대리인의 등록번호를 덧붙여 적어야 한다.","w":"위탁매입은 공급자가 위탁자 또는 본인을 공급받는 자로 하여 발급하고 수탁자(대리인)의 등록번호를 덧붙여 적는다.","c":"상","v":1},"관세사2019_36-30-4":{"f":"휴업 또는 사업 부진으로 인하여 각 예정신고기간의 공급가액이 직전 과세기간의 공급가액의 3분의 1에 미달하는 개인사업자는 예정신고를 할 수 있다.","w":"개인사업자는 원칙적으로 예정고지를 받고, 휴업이나 사업 부진으로 공급가액이 직전 과세기간의 3분의 1에 미달하면 예정신고를 할 수 있다. 3분의 2가 아니고 의무도 아니다.","c":"상","v":1},"관세사2020_37-18-1":{"f":"발급받은 세금계산서에 필요적 기재사항의 일부가 사실과 다르게 적힌 경우의 매입세액은 거래사실이 확인되는 경우를 제외하고는 공급시기가 속하는 과세기간 내에 발급받았더라도 관련 매출세액에서 공제되지 않는다.","w":"필요적 기재사항이 사실과 다르면 매입세액이 불공제된다. 나머지 기재사항으로 거래사실이 확인되는 경우만 예외이다.","c":"중","v":1},"관세사2020_37-18-2":{"f":"사업자가 과세사업과 면세사업등을 겸영하는 경우 과세사업과 면세사업등에 관련된 매입세액의 계산은 실지귀속에 따르고, 실지귀속을 알 수 없는 공통매입세액에 한하여 공통매입세액 안분기준을 적용하여 안분 계산한다.","w":"실지귀속이 확인되면 그에 따르고, 구분되지 않는 공통매입세액만 안분한다. 안분기준을 우선 적용하지 않는다.","c":"상","v":1},"관세사2020_37-18-3":{"f":"공통매입세액에 대하여 면세사업등에 관련된 매입세액을 안분하여 계산하는 경우, 건물을 취득하여 과세사업과 면세사업등에 제공할 예정면적을 구분할 수 있는 경우에는 예정사용면적의 비율을 우선하여 적용한다.","w":"건물을 취득하여 예정면적을 구분할 수 있으면 총매입가액 비율이 아니라 예정사용면적 비율로 안분한다.","c":"상","v":1},"관세사2020_37-18-5":{"f":"신용카드 등의 사용에 따른 세액공제를 적용받을 수 있는 사업자의 범위에 법인사업자는 포함되지 않으나 간이과세자는 포함된다.","w":"신용카드 발행세액공제는 법인사업자에게는 적용되지 않고 간이과세자에게는 별도로 적용된다.","c":"중","v":1},"관세사2020_37-19-1":{"f":"재화의 수입에 대한 부가가치세 과세표준은 그 재화에 대한 관세의 과세가격에 관세, 개별소비세, 주세, 교육세, 농어촌특별세 및 교통ㆍ에너지ㆍ환경세를 더한 금액으로 한다.","w":"수입재화의 과세표준은 관세의 과세가격에 관세와 개별소비세·주세·교육세·농어촌특별세·교통에너지환경세를 더한 금액이다. 차감하지 않는다.","c":"상","v":1},"관세사2020_37-19-2":{"f":"재화 또는 용역을 공급하고 금전 외의 대가를 받는 경우 해당 공급에 대한 부가가치세 과세표준은 자기가 공급한 재화 또는 용역의 시가로 한다.","w":"금전 외의 대가를 받으면 과세표준은 받은 재화·용역이 아니라 자기가 공급한 재화·용역의 시가이다.","c":"상","v":1},"관세사2020_37-19-3":{"f":"사업자가 둘 이상의 과세기간에 걸쳐 용역을 제공하고 그 대가를 선불로 받는 경우, 해당 용역의 과세표준은 선불로 받은 금액을 계약기간의 개월 수로 나눈 금액의 각 과세대상기간의 합계액으로 한다.","w":"둘 이상의 과세기간에 걸친 용역의 대가를 선불로 받으면 받은 금액을 계약기간 개월 수로 나눠 각 과세대상기간에 배분한 금액이 과세표준이다(부가가치세법 시행령 제61조 제2항 제6호). 공급시기도 예정신고기간 또는 과세기간의 종료일이다(제29조 제2항 제3호).","c":"상","v":1},"관세사2020_37-19-5":{"f":"통상적으로 용기를 해당 사업자에게 반환할 것을 조건으로 그 용기대금을 공제한 금액으로 공급하는 경우 그 용기대금은 공급가액에 포함하지 아니한다.","w":"반환 조건부 용기대금은 공급가액에 포함하지 않는다.","c":"상","v":1},"관세사2020_37-25-1":{"f":"사업자는 세금계산서를 발급하였거나 발급받은 경우에는 매출처별 세금계산서합계표와 매입처별 세금계산서합계표를 해당 예정신고 또는 확정신고를 할 때 함께 제출하여야 한다.","w":"세금계산서 합계표는 세금계산서 자체로 갈음해 제출하는 것이 아니라 합계표를 신고 때 함께 제출한다. 전자세금계산서 발급명세를 기한 내에 전송한 경우에만 합계표 제출이 생략된다.","c":"상","v":1},"관세사2020_37-25-2":{"f":"전자세금계산서를 발급하거나 발급받고 전자세금계산서 발급명세를 공급시기가 속하는 과세기간(예정신고 시 예정신고기간) 마지막 날의 다음 달 11일까지 국세청장에게 전송한 경우에는 해당 예정신고 또는 확정신고 시 매출ㆍ매입처별 세금계산서합계표를 제출하지 아니할 수 있다.","w":"합계표 제출이 생략되려면 발급명세를 그 과세기간(예정신고기간) 마지막 날의 다음 달 11일까지 전송해야 한다. 15일이 아니다.","c":"상","v":1},"관세사2020_37-25-3":{"f":"예정신고를 하는 사업자가 각 예정신고와 함께 매출ㆍ매입처별 세금계산서합계표를 제출하지 못하는 경우에 해당 예정신고기간이 속하는 과세기간의 확정신고를 할 때 함께 제출할 수 있다.","w":"예정신고 때 내지 못한 합계표는 확정신고 때 함께 제출할 수 있다. 수정신고나 경정청구로만 제출해야 하는 것이 아니다.","c":"상","v":1},"관세사2020_37-25-4":{"f":"수입세금계산서를 발급한 세관장은 매출처별 세금계산서합계표를 해당 세관 소재지를 관할하는 세무서장에게 제출하여야 한다.","w":"세관장이 발급한 수입세금계산서의 합계표는 세관 소재지 관할 세무서장에게 제출한다. 지방자치단체장이 아니다.","c":"상","v":1},"관세사2020_37-27-1":{"f":"사업자가 영세율을 적용받는 경우 조기환급대상에 해당한다.","w":"영세율을 적용받는 경우는 조기환급 사유이다.","c":"상","v":1},"관세사2020_37-27-2":{"f":"사업자가 감가상각자산인 비품을 취득하는 경우 조기환급대상에 해당한다.","w":"감가상각자산을 신설·취득·확장·증축하는 경우는 조기환급 사유에 해당한다.","c":"상","v":1},"관세사2020_37-27-3":{"f":"부동산매매업자가 매매목적의 건물을 신축하는 경우 조기환급대상에 해당하지 아니한다.","w":"매매목적 건물은 재고자산이지 감가상각자산이 아니므로 조기환급 사유가 아니다.","c":"상","v":1},"관세사2020_37-27-5":{"f":"조기환급에 해당하지 않는 환급의 경우 확정신고기한이 지난 후 30일 이내에 환급하여야 한다.","w":"조기환급이 아닌 일반 환급은 확정신고기한이 지난 후 30일 이내에 한다. 예정신고기간의 환급세액은 확정신고에서 정산하며 따로 환급하지 않는다.","c":"상","v":1},"관세사2020_37-30-3":{"f":"결제대행업체는 재화 또는 용역의 공급과 관련하여 국내에서 결제를 대행하는 경우 월별 거래 명세를 매 분기 말일의 다음 달 15일까지 국세청장, 납세지 관할 지방국세청장 또는 납세지 관할 세무서장에게 제출하여야 한다.","w":"결제대행업체의 거래 명세 제출기한은 매 분기 말일의 다음 달 15일이다(부가가치세법 제75조 제1항). 25일이 아니다.","c":"중","v":1},"관세사2022_39-16-3":{"f":"전자세금계산서 의무발급 개인사업자가 전자세금계산서를 발급하여야 하는 기간은 사업장별 공급가액 합계액이 의무발급기준액 이상이 되는 해의 다음 해 7월 1일부터 그 다음 해 6월 30일까지로 한다.","w":"의무발급 기간은 기준액 이상이 된 해의 다음 해 7월 1일부터 1년간이다. 다음 해 1월부터가 아니다.","c":"상","v":1},"관세사2022_39-17-3":{"f":"매입자발행세금계산서의 발행신청은 공급자로부터 세금계산서를 발급받지 못한 거래 중 거래건당 공급대가가 5만원 이상인 거래에 대하여 적용할 수 있다.","w":"매입자발행세금계산서는 거래건당 공급대가가 5만원 이상인 거래만 신청할 수 있다. 모든 거래가 대상이 아니다.","c":"상","v":1},"관세사2022_39-19-2":{"f":"공급시기 이후에 발급받은 세금계산서는 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 발급받은 경우 등에 한하여 그 매입세액을 공제한다.","w":"공급시기 뒤에 받은 세금계산서는 공급시기가 속하는 과세기간의 확정신고기한까지 받으면 공제되고, 그 뒤라도 확정신고기한 다음 날부터 1년 이내에 받아 수정신고·경정청구를 하거나 경정을 받으면 공제된다(부가가치세법 시행령 제75조 제3호·제7호). 발급시기와 관계없이 공제되지는 않는다.","c":"상","v":1},"관세사2022_39-19-3":{"f":"기업업무추진비의 지출에 관련된 매입세액은 사업과 관련된 금액이라도 공제하지 아니한다.","w":"기업업무추진비 관련 매입세액은 사업 관련 여부와 관계없이 불공제이다.","c":"상","v":1},"관세사2022_39-19-4":{"f":"공급시기가 속하는 과세기간이 끝난 후 20일 이내에 사업자등록을 신청한 경우 사업자등록을 신청하기 전의 매입세액이라도 공급시기가 속하는 과세기간 기산일까지 역산한 기간 내의 것이면 공제한다.","w":"등록 전 매입세액은 공급시기가 속하는 과세기간이 끝난 후 20일 이내에 등록을 신청한 경우에만 공제된다. 30일이 아니다.","c":"상","v":1},"관세사2022_39-19-5":{"f":"면세사업과 과세사업을 겸영하는 사업자의 공통사용재화 매입과 관련된 매입세액 중 면세관련 세액은 매입세액으로 공제하지 아니한다.","w":"면세사업에 관련된 매입세액은 불공제이다. 공통매입세액 중 면세 몫도 공제하지 않는다.","c":"상","v":1},"관세사2022_39-20-4":{"f":"같은 과세기간 내에 공통매입세액이 각각 2만원, 2만원인 매입거래가 있는 경우 이 매입세액은 전부 공제되는 매입세액으로 한다.","w":"공통매입세액이 5만원 미만이어서 전부 공제하는 예외는 해당 과세기간 공통매입세액의 합계액으로 판단한다. 4만원과 3만원이면 합계 7만원이므로 안분 대상이다.","c":"상","v":1},"관세사2022_39-25-1":{"f":"부가가치세 과세표준의 결정ㆍ경정은 각 납세지 관할 세무서장이 한다.","w":"결정·경정은 각 납세지 관할 세무서장이 하고, 국세청장이 특히 중요하다고 인정하는 경우에는 관할 지방국세청장이나 국세청장이 할 수 있다. 지방국세청장만 하는 것이 아니다.","c":"상","v":1},"관세사2022_39-25-2":{"f":"주사업장 총괄 납부를 하는 경우에도 각 납세지 관할 세무서장 또는 납세지 관할 지방국세청장은 과세표준과 납부세액 또는 환급세액을 결정할 수 있다.","w":"총괄 납부는 납부만 한곳에서 하는 제도이므로 결정·경정은 각 사업장 관할에서 한다.","c":"상","v":1},"관세사2022_39-25-4":{"f":"국세청장이 정하는 업종을 경영하는 사업자로서 같은 장소에서 계속하여 5년 이상 사업을 경영한 자에 대해서는 객관적인 증명자료로 보아 과소하게 신고한 것이 분명한 경우에만 경정한다.","w":"영수증 발급대상 중 국세청장이 정한 업종을 같은 장소에서 5년 이상 경영한 사업자는 과소신고가 분명한 경우에만 경정한다. 3년이 아니고, 경정을 아예 하지 않는 것도 아니다.","c":"상","v":1},"관세사2022_39-25-5":{"f":"신용카드가맹점 가입 대상자로 지정받은 사업자가 신용카드가맹점으로 가입하지 아니한 경우에는 납세지 관할 세무서장이 부가가치세 과세표준을 결정한다.","w":"가맹점 미가입은 결정·경정 사유이고 결정은 원칙대로 납세지 관할 세무서장이 한다.","c":"중","v":1},"관세사2022_39-30-2":{"f":"과태료는 국세청장, 납세지 관할 지방국세청장 또는 납세지 관할 세무서장이 부과한다.","w":"과태료 부과권자는 국세청장, 납세지 관할 지방국세청장, 납세지 관할 세무서장이다. 국세청장만이 아니다.","c":"상","v":1},"관세사2023_40-25-1":{"f":"영수증 발급대상 사업 중 국세청장이 정하는 업종을 경영하는 사업자로서 같은 장소에서 계속하여 5년 이상 사업을 경영한 자에 대해서는 객관적인 증명자료로 보아 과소하게 신고한 것이 분명한 경우에만 경정할 수 있다.","w":"계속 사업 기간 요건은 3년이 아니라 5년 이상이다.","c":"상","v":1},"관세사2023_40-26-3":{"f":"사업 설비(「법인세법 시행령」에 따른 감가상각자산)를 확장하는 경우는 조기환급 사유에 해당한다.","w":"감가상각자산인 사업설비의 신설·취득·확장·증축은 조기환급 사유이다.","c":"상","v":1},"관세사2023_40-28-5":{"f":"甲이 세금계산서를 발급받고 매입처별 세금계산서 합계표를 제출한 경우(모두 공제대상 매입세액으로 가정함), 해당 과세기간에 발급받은 세금계산서상 공급대가에 0.5퍼센트를 곱한 금액은 납부세액에서 공제하되, 납부세액을 초과하는 부분은 환급하지 아니한다.","w":"간이과세자의 세금계산서 등 수취세액공제는 납부세액을 한도로 공제하며 초과분은 환급되지 않는다.","c":"상","v":1},"관세사2024_41-18-1":{"f":"사업자가 부가가치세가 면제되는 재화를 공급하는 경우에는 세금계산서가 아니라 계산서를 발급한다.","w":"부가가치세가 면제되는 재화·용역을 공급하는 경우에는 세금계산서를 발급하지 않고 계산서를 발급한다.","c":"상","v":1},"관세사2024_41-18-2":{"f":"전자세금계산서 의무발급 개인사업자가 아닌 사업자도 전자세금계산서를 발급할 수 있다.","w":"의무 대상이 아닌 사업자도 임의로 전자세금계산서를 발급하고 발급명세를 전송할 수 있다.","c":"상","v":1},"관세사2024_41-18-4":{"f":"단가와 수량은 세금계산서의 임의적 기재사항이다.","w":"필요적 기재사항은 공급자·공급받는 자의 등록번호, 공급가액과 부가가치세액, 작성연월일이다. 단가와 수량은 임의적 기재사항이다.","c":"상","v":1},"관세사2024_41-18-5":{"f":"매입자발행세금계산서를 발행하려는 자는 해당 재화의 공급시기가 속하는 과세기간의 종료일부터 1년 이내에 신청인의 관할 세무서장에게 거래사실의 확인을 신청하여야 한다.","w":"거래사실 확인 신청 기한은 공급시기가 속하는 과세기간의 종료일부터 1년 이내이다(부가가치세법 시행령 제71조의2 제3항). 2024년 2월 개정 전에는 6개월 이내였다.","c":"중","v":1},"관세사2024_41-22-1":{"f":"음식점업을 경영하는 사업자가 농어민으로부터 면세농산물등을 직접 공급받고 매입세액 공제를 받으려면 의제매입세액 공제신고서와 함께 증빙을 제출한다.","w":"공제신고서만으로 공제받을 수 있는 것은 제조업자가 농어민에게서 직접 공급받은 경우이다. 음식점업은 계산서나 신용카드 매출전표 등 증빙이 필요하다.","c":"상","v":1},"관세사2024_41-24-2":{"f":"국내 사업장이 없는 외국법인으로부터 국내에서 용역을 공급받는 자가 공급받은 용역을 면세사업에 제공하는 경우에는 대리납부의무가 있다.","w":"대리납부는 과세사업에 제공하는 경우에는 면제된다. 매입세액 공제가 되지 않는 면세사업 등에 쓰는 경우에 의무가 생긴다.","c":"상","v":1},"관세사2024_41-25-1":{"f":"납세지 관할 세무서장은 사업자가 폐업 상태에 있을 경우에도 결정 또는 경정을 할 수 있다.","w":"휴업 또는 폐업 상태에 있는 경우는 결정·경정 사유이다.","c":"중","v":1},"관세사2024_41-26-1":{"f":"사업자가 대통령령으로 정하는 재무구조개선계획을 이행 중인 경우는 조기환급 사유에 해당한다.","w":"재무구조개선계획을 이행 중인 경우는 조기환급 사유이다.","c":"상","v":1},"관세사2024_41-26-3":{"f":"납세지 관할 세무서장은 사업자가 영세율을 적용받는 경우에 해당하여 조기에 환급을 신고한 사업자에게 환급세액을 그 예정신고기한이 지난 후 15일 이내에 환급하여야한다.","w":"예정신고로 조기환급을 신고한 경우 환급세액은 예정신고기한이 지난 후 15일 이내에 환급한다(부가가치세법 시행령 제107조 제1항). 30일은 일반 환급의 기한이다.","c":"상","v":1},"관세사2024_41-26-4":{"f":"납세지 관할 세무서장은 사업자가 예정신고를 할 때에 신고한 납부세액을 납부하지 아니한 경우에는 그 미납세액을 징수하여야 한다.","w":"예정신고 때 신고만 하고 내지 않은 세액은 확정신고기한이 지나기를 기다리지 않고 징수한다.","c":"상","v":1},"관세사2024_41-26-5":{"f":"납세지 관할 세무서장은 개인사업자가 「소득세법 시행령」에 따른 감가상각자산을 취득하고, 환급세액을 확정신고한 사업자에게 그 확정신고기한이 지난 후 15일 이내에 환급한다.","w":"감가상각자산인 사업 설비를 취득한 경우는 조기환급 사유여서 확정신고한 환급세액도 확정신고기한이 지난 후 15일 이내에 환급한다(부가가치세법 제59조 제1항 괄호, 제2항 제2호). 내용연수에 걸쳐 나누어 환급하지 않는다.","c":"상","v":1},"관세사2024_41-30-3":{"f":"위반행위가 중대한 과실에 따른 것으로 인정되는 경우 과태료 금액의 2분의 1 범위에서 그 금액을 늘려 부과할 수 있으나, 과태료는 법령이 정한 최고액을 넘을 수 없다.","w":"과태료를 가중해도 법정 한도(부가가치세법은 2천만원 이하)를 넘을 수 없다. 최대 3천만원이 될 수 있다는 부분이 틀렸다.","c":"중","v":1},"관세사2025_42-18-1":{"f":"사업자가 부가가치세가 과세되는 재화를 공급하는 경우 공급받는 자가 사업자가 아닌 경우에도 세금계산서를 발급할 수 있다.","w":"공급받는 자가 사업자가 아니거나 등록하지 않은 사업자인 경우에는 고유번호나 주민등록번호를 적어 세금계산서를 발급한다(부가가치세법 제32조 제1항 제2호 단서).","c":"상","v":1},"관세사2025_42-18-2":{"f":"전자세금계산서를 발급하여야 하는 사업자가 아닌 사업자도 전자세금계산서를 발급할 수 있다.","w":"의무 대상이 아닌 사업자도 전자세금계산서를 발급할 수 있다.","c":"상","v":1},"관세사2025_42-18-3":{"f":"전자세금계산서 의무발급 개인사업자는 직전 연도의 사업장별 재화 및 용역의 공급가액(면세공급가액을 포함한다)의 합계액이 8천만원 이상인 개인사업자를 말한다.","w":"현행 기준의 공급가액 합계에는 면세공급가액이 포함된다. 면세공급가액을 제외한다는 부분이 틀렸다.","c":"상","v":1},"관세사2025_42-18-5":{"f":"전자세금계산서를 발급한 법인사업자는 그 발급일의 다음 날까지 전자세금계산서 발급명세를 국세청장에게 전송하여야 한다.","w":"발급명세 전송기한은 발급일의 다음 날까지이다. 5일이 아니다.","c":"상","v":1},"관세사2025_42-28-5":{"f":"간이과세자가 간이과세 포기신고를 한 때에는 일반과세자에 관한 규정을 적용받으려는 달의 1일부터 3년이 되는 날이 속하는 과세기간까지는 간이과세자에 관한 규정을 적용받지 못한다.","w":"제한 기간은 3년이 되는 날까지가 아니라 3년이 되는 날이 속하는 과세기간까지이다.","c":"상","v":1},"관세사2026_43-19-1":{"f":"법인사업자는 직전 연도 공급가액에 관계없이 전자세금계산서를 발급하여야 한다. 직전 연도 공급가액이 8천만원 이상이라는 요건은 개인사업자에게 적용된다.","w":"법인사업자는 금액 기준 없이 전자세금계산서 의무발급 대상이다. 8천만원 기준은 개인사업자의 것이다.","c":"상","v":1},"관세사2026_43-19-2":{"f":"세금계산서의 작성연월일은 필요적 기재사항이고 공급연월일은 임의적 기재사항이다.","w":"필요적 기재사항은 공급자·공급받는 자의 등록번호, 공급가액과 세액, 작성연월일이다. 공급연월일은 임의적 기재사항이다.","c":"상","v":1},"관세사2026_43-19-4":{"f":"매입자발행세금계산서를 발행하려는 자가 거래사실의 확인신청을 하는 경우 거래건당 공급대가가 5만원 이상이어야 한다.","w":"거래건당 공급대가 5만원 이상이면 신청할 수 있다. 50만원이 아니다.","c":"상","v":1},"관세사2026_43-19-5":{"f":"세관장은 수입되는 재화에 대하여 수입된 재화에 대한 수입세금계산서를 수입하는 자에게 발급하여야 한다.","w":"수입세금계산서는 세관장이 수입하는 자에게 발급한다. 발급 주체와 상대방이 뒤바뀌었다.","c":"상","v":1},"관세사2026_43-22-1":{"f":"면세를 포기하고 영세율을 적용받는 경우에는 의제매입세액 공제를 적용받을 수 없다.","w":"면세를 포기하고 영세율을 적용받는 경우는 의제매입세액 공제 대상에서 제외된다.","c":"상","v":1},"관세사2026_43-22-2":{"f":"음식점업과 제조업을 영위하는 사업자 외에도 면세농산물등을 원재료로 제조·가공한 재화 또는 용역이 과세되는 사업자는 의제매입세액 공제가 가능하다.","w":"의제매입세액 공제는 음식점업과 제조업에 한정되지 않고 면세농산물을 원재료로 제조·가공해 과세되는 재화·용역을 공급하는 사업자 모두에게 적용된다.","c":"상","v":1},"관세사2026_43-22-3":{"f":"음식점업을 영위하는 과세표준 1억원 이하인 개인사업자도 과세표준에 일정 비율을 곱한 한도 안에서 의제매입 세액 공제가 가능하다.","w":"의제매입세액 공제에는 과세표준 대비 한도가 있다. 과세표준 1억원 이하 개인 음식점업은 한도율이 높을 뿐 한도가 없는 것은 아니다.","c":"상","v":1},"관세사2026_43-22-4":{"f":"면세농산물을 당기 중에 매입하였으나 사용하지 않은 경우에도 의제매입세액 공제를 적용받을 수 있다.","w":"의제매입세액은 면세농산물을 공급받은 때가 속하는 예정·확정신고에서 공제하며 사용 여부와 관계없다.","c":"중","v":1},"관세사2026_43-27-1":{"f":"조기환급에 해당하지 않는 환급의 경우 납세지 관할 세무서장은 확정신고기간에 대한 환급세액을 그 확정신고기한이 지난 후 30일 이내에 환급해야 한다.","w":"일반 환급은 확정신고기한 후 30일 이내이다. 예정신고기간의 환급세액은 따로 환급하지 않고 확정신고 때 정산한다.","c":"상","v":1},"관세사2026_43-27-2":{"f":"납세지 관할 세무서장은 경정에 의하여 추가로 발생한 환급세액이 있는 경우에는 지체 없이 환급하여야 한다.","w":"경정으로 늘어난 환급세액은 지체 없이 환급한다.","c":"상","v":1},"관세사2026_43-27-3":{"f":"납세지 관할 세무서장은 사업자가 감가상각자산을 취득하는 경우 환급세액을 조기에 환급할 수 있다.","w":"감가상각자산의 취득은 조기환급 사유이지만 감가상각자산이 아닌 자산은 해당하지 않는다.","c":"상","v":1},"관세사2026_43-27-4":{"f":"조기환급을 받으려는 사업자는 조기환급기간이 끝나는 날부터 25일 이내에 환급세액을 납세지 관할 세무서장에게 신고해야 한다.","w":"조기환급 신고기한은 조기환급기간이 끝난 날부터 25일 이내이다. 15일은 환급기한이다.","c":"상","v":1},"관세사2017_34-21-1":{"f":"위탁매매 또는 대리인에 의한 매매를 할 때에는 위탁자 또는 본인에게 부가 가치세 납세의무가 있다(단, 위탁자 또는 본인을 알 수 없는 경우는 제외).","w":"위탁매매·대리인 매매는 위탁자 또는 본인이 직접 공급한 것으로 보아 위탁자 또는 본인이 납세의무자이다. 위탁자나 본인을 알 수 없는 경우에만 수탁자 또는 대리인이 공급한 것으로 본다(부가가치세법 제10조 제7항).","c":"하","v":1},"관세사2017_34-24-5":{"f":"사업장 관할 세무서장은 사업자등록의 신청 내용을 보정할 필요가 있다고 인정될 때에는 10일 이내의 기간을 정하여 보정을 요구할 수 있다.","w":"사업자등록 신청 내용의 보정 요구 기간은 10일 이내이다(부가가치세법 시행령 제11조 제13항).","c":"상","v":1},"관세사2017_34-25-1":{"f":"재화를 수입하는 자에 대한 부가가치세는 세관장이 징수한다.","w":"재화의 수입에 대한 부가가치세는 관세와 함께 수입신고를 수리하는 세관장이 징수한다. 납세지 관할 세무서장이 과세하는 것이 아니고, 납세지는 수입신고하는 세관의 소재지이다.","c":"상","v":1},"관세사2017_34-40-5":{"f":"주사업장 총괄 납부를 포기한 경우에는 그 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장에서 납부하여야 한다.","w":"총괄 납부를 포기하면 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장에서 납부한다. 포기한 과세기간 중에는 계속 총괄 납부가 적용된다.","c":"상","v":1},"관세사2018_35-02-5":{"f":"간이과세를 포기하여 일반과세자로 되는 경우 간이과세자의 과세기간은 그 과세기간의 개시일부터 포기 신고일이 속하는 달의 마지막 날까지로 한다.","w":"간이과세를 포기하면 그 과세기간 개시일부터 포기 신고일이 속하는 달의 마지막 날까지가 간이과세자의 과세기간이고, 신고일이 속하는 달의 다음 달 1일부터 그 과세기간 종료일까지가 일반과세자의 과세기간이다(부가가치세법 제5조 제5항).","c":"상","v":1},"관세사2018_35-03-4":{"f":"사업자가 부동산상의 권리만을 대여하는 경우에는 사업에 관한 업무를 총괄하는 장소를 사업장으로 한다.","w":"부동산 임대업은 부동산의 등기부상 소재지가 사업장이지만, 부동산상의 권리만 대여하는 경우에는 사업에 관한 업무를 총괄하는 장소가 사업장이다(부가가치세법 시행령 제8조).","c":"상","v":1},"관세사2018_35-04-5":{"f":"사업자 단위 과세 사업자가 사업자 단위 과세 적용 사업장을 변경하는 경우에는 지체 없이 사업자등록정정신고서를 관할 세무서장에게 제출하여야 한다.","w":"사업자등록 정정 사유가 생기면 지체 없이 정정신고서를 제출한다. 사업자 단위 과세 적용 사업장을 변경할 때 변경 사유 발생일로부터 20일 이내라는 별도 기한을 둔 것은 아니다.","c":"상","v":1},"관세사2018_35-27-3":{"f":"간편사업자등록을 한 사업자가 국내에 공급하는 전자적 용역에 대해서는 국내사업자와 달리 세금계산서 및 영수증을 발급하지 아니한다.","w":"간편사업자등록을 한 국외사업자가 국내에 공급하는 전자적 용역은 세금계산서 발급의무가 면제되고 영수증도 발급하지 않는다(부가가치세법 시행령 제71조 제1항 제8호, 제73조 제6항).","c":"상","v":1},"관세사2019_36-06-5":{"f":"사업자 단위 과세를 포기한 경우에는 그 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장별로 신고ㆍ납부하여야 하며, 주사업장 총괄 납부를 신청할 수 있다.","w":"사업자 단위 과세를 포기하면 각 사업장별로 신고·납부하거나, 요건을 갖춰 주사업장 총괄 납부를 신청할 수 있다. 주사업장 총괄 납부를 신청할 수 없다는 부분이 틀렸다.","c":"상","v":1},"관세사2019_36-07-2":{"f":"재화를 수입하는 자의 부가가치세 납세지는 관세법에 따라 수입을 신고하는 세관의 소재지로 한다.","w":"재화를 수입하는 자의 납세지는 수입신고하는 세관의 소재지이고, 수입하는 자의 주소·거소와는 관계없다(부가가치세법 제6조 제6항).","c":"상","v":1},"관세사2019_36-10-5":{"f":"법인의 대표자 변경으로 사업자로부터 사업자등록 정정신고를 받은 세무서장은 신청을 받은 날부터 2일 이내에 사업자등록증을 정정하여 재발급하여야 한다.","w":"정정신고 후 사업자등록증 재발급 기한은 신고일부터 2일 이내가 원칙이다. 당일 재발급은 상호 변경 같은 일부 사유에만 해당하고, 법인 대표자 변경은 2일 이내이다.","c":"상","v":1},"관세사2020_37-01-1":{"f":"사업자가 사업자등록을 하지 않고 부가가치세가 과세되는 재화를 공급하는 경우에도 납세의무가 있다.","w":"부가가치세 납세의무는 사업상 독립적으로 재화·용역을 공급하는 사실에서 생긴다. 사업자등록 여부와 관계없이 납세의무가 있고, 미등록은 가산세 사유가 된다.","c":"상","v":1},"관세사2020_37-01-2":{"f":"사업자가 부가가치세가 과세되는 재화를 공급하는 경우 부가가치세를 거래징수하지 않았더라도 납세의무가 있다.","w":"거래징수 여부는 납세의무의 성립과 관계없다. 과세되는 재화를 공급한 사업자는 거래상대방에게 받지 못했더라도 납세의무가 있다.","c":"상","v":1},"관세사2020_37-01-3":{"f":"청산중에 있는 내국법인은 계속등기 여부에 관계없이 사실상 사업을 계속하는 경우에는 납세의무가 있다.","w":"청산 중인 법인도 사실상 사업을 계속하면 계속등기 여부와 관계없이 사업자로서 납세의무가 있다.","c":"상","v":1},"관세사2020_37-01-4":{"f":"새마을금고가 사업상 독립적으로 부가가치가 과세되는 재화를 공급하는 경우에는 납세의무가 있다.","w":"영리 여부와 관계없이 사업상 독립적으로 재화·용역을 공급하는 자는 사업자이므로 비영리 법인인 새마을금고도 과세되는 재화를 공급하면 납세의무가 있다.","c":"상","v":1},"관세사2020_37-03-4":{"f":"간이과세자가 간이과세자에 관한 규정의 적용을 포기함으로써 일반과세자로 되는 경우 일반과세자의 과세기간은 일반과세자에 관한 규정을 적용받으려는 달의 1일부터 그 날이 속하는 과세기간의 종료일까지의 기간으로 한다.","w":"간이과세 포기 후 일반과세자의 과세기간은 일반과세자 규정을 적용받으려는 달의 1일부터 시작한다. 포기 신고일이 속하는 달의 1일부터가 아니다. 포기는 적용받으려는 달의 전달 말일까지 신고한다.","c":"상","v":1},"관세사2020_37-04-4":{"f":"운수업을 하는 사업자가 법인인 경우 법인의 등기부상 소재지를 사업장으로 한다.","w":"운수업은 개인이면 업무를 총괄하는 장소, 법인이면 법인의 등기부상 소재지(본점)를 사업장으로 한다.","c":"상","v":1},"관세사2020_37-24-1":{"f":"사업장이 둘 이상인 사업자가 주사업장 총괄 납부를 신청한 경우에는 주된 사업장에서 총괄하여 납부할 수 있다.","w":"주사업장 총괄 납부는 세액의 납부만 주된 사업장에서 총괄하는 제도이다. 신고는 각 사업장별로 한다.","c":"상","v":1},"관세사2020_37-24-2":{"f":"주사업장 총괄 납부 시 법인의 경우에 지점(분사무소를 포함한다)을 주된 사업장으로 할 수 있다.","w":"법인의 주된 사업장은 본점 또는 지점(분사무소 포함)으로 선택할 수 있다. 개인은 주사무소만 가능하다.","c":"상","v":1},"관세사2020_37-24-3":{"f":"주사업장 총괄 납부 시 각 사업장의 관할 세무서장이 해당 사업장에 대해 결정 또는 경정한다.","w":"총괄 납부를 해도 과세표준 신고·결정·경정은 각 사업장별이므로 각 사업장 관할 세무서장이 한다. 주된 사업장 관할 세무서장이 모든 종된 사업장에 대해 하는 것이 아니다.","c":"상","v":1},"관세사2020_37-24-5":{"f":"주사업장 총괄 납부 사업자가 주된 사업장의 이동이 빈번한 경우 주된 사업장 관할 세무서장은 주사업장 총괄 납부를 적용하지 아니할 수 있다.","w":"총괄 납부 배제 사유는 주된 사업장의 이동이 빈번한 경우나 사업 내용 변경으로 총괄 납부가 부적당한 경우이다. 종된 사업장의 변경신청이 잦은 것은 사유가 아니고, 적용하지 않을 수 있다는 임의 규정이다.","c":"상","v":1},"관세사2022_39-01-1":{"f":"간이과세자란 직전 연도의 공급대가의 합계액이 1억 400만원에 미달하는 사업자로서 간편한 절차로 부가가치세를 신고ㆍ납부하는 개인사업자를 말한다.","w":"(출제 당시 기준 8천만원 미달이어서 X. 현행은 1억 400만원 미달.) 간이과세자는 직전 연도 공급대가 합계액이 1억 400만원에 미달하는 개인사업자이다.","c":"중","v":1},"관세사2022_39-01-2":{"f":"전기, 가스, 열등 관리할 수 있는 자연력은 재산 가치가 있는 경우에 재화에 해당한다.","w":"관리할 수 있는 자연력은 재산 가치가 있어야 재화로 본다. 재산 가치가 없으면 재화가 아니다.","c":"상","v":1},"관세사2022_39-01-4":{"f":"외국기관의 사업은 용역에 포함된다.","w":"용역의 범위를 정하는 시행령 제3조에는 국제 및 외국기관의 사업도 들어 있다.","c":"상","v":1},"관세사2022_39-01-5":{"f":"사업자란 사업 목적이 영리이든 비영리이든 관계없이 사업상 독립적으로 재화 또는 용역을 공급하는 자를 말한다.","w":"사업자 개념에 영리 목적은 요건이 아니다. 영리·비영리를 가리지 않는다.","c":"상","v":1},"관세사2022_39-02-5":{"f":"사업자가 자기의 사업과 관련하여 생산한 재화를 직접 판매하기 위해 설치한 직매장은 사업장으로 본다.","w":"직매장은 사업장이다. 생산·취득한 재화를 직접 판매하려고 특별히 판매시설을 갖춘 장소는 사업장에 포함된다.","c":"상","v":1},"관세사2022_39-03-4":{"f":"합병으로 인한 소멸법인의 경우 합병법인의 변경등기일 또는 설립등기일을 폐업일로 한다.","w":"합병으로 소멸하는 법인의 폐업일은 사업을 실질적으로 폐업하는 날이 아니고 합병법인의 변경등기일 또는 설립등기일이다.","c":"상","v":1},"관세사2022_39-04-1":{"f":"신규로 사업을 시작하려는 자는 사업 개시일부터 20일 이내에 사업장 관할 세무서장에게 사업자등록을 신청하여야 한다(사업 개시 전에도 신청할 수 있다).","w":"사업자등록 신청 기한은 사업 개시일부터 20일 이내이고, 신규 사업자는 개시일 전에도 신청할 수 있다. 개시일 20일 전에 신청해야 하는 것이 아니다.","c":"상","v":1},"관세사2022_39-04-2":{"f":"사업자는 사업자등록의 신청을 사업장 관할 세무서장이 아닌 다른 세무서장에게도 할 수 있으며 이 경우 사업장 관할 세무서장에게 사업자등록을 신청한 것으로 본다.","w":"관할이 아닌 세무서장에게 신청해도 사업장 관할 세무서장에게 한 것으로 본다.","c":"상","v":1},"관세사2022_39-04-4":{"f":"공동사업자의 출자지분이 변경되는 경우에는 사업자등록 사항의 변경신고를 하여야 한다.","w":"공동사업자의 구성원이나 출자지분이 변경되면 사업자등록 정정신고 사유이다.","c":"상","v":1},"관세사2022_39-04-5":{"f":"상호를 변경하는 경우 사업자가 이를 신고하면 신고를 받은 세무서장은 신고일 당일에 사업자등록증의 기재사항을 정정하여 재발급해야 한다.","w":"상호 변경은 신고일 당일 재발급 사유이고, 그 밖의 정정 사유는 신고일부터 2일 이내에 재발급한다.","c":"상","v":1},"관세사2022_39-29-1":{"f":"개인사업자가 6개월 이상 국외에 체류하려는 경우 부가가치세에 관한 신고ㆍ납부ㆍ환급, 그 밖에 필요한 사항을 처리하는 납세관리인을 정하여야 한다.","w":"국외 체류로 납세관리인을 정해야 하는 기준 기간은 6개월 이상이다. 3개월이 아니다.","c":"상","v":1},"관세사2023_40-01-3":{"f":"부동산매매업을 영위하는 개인의 사업장은 사업에 관한 업무를 총괄하는 장소로 한다.","w":"부동산매매업의 사업장은 법인이면 법인 등기부상 소재지, 개인이면 업무를 총괄하는 장소이다. 부동산 등기부상 소재지가 사업장인 것은 부동산임대업이다.","c":"상","v":1},"관세사2023_40-02-1":{"f":"사업자가 사업자 단위 과세 사업자로 적용을 받는 과세기간에 자기의 사업과 관련하여 생산 또는 취득한 재화를 판매할 목적으로 자기의 다른 사업장에 반출하는 것은 재화의 공급으로 보지 아니한다.","w":"사업자 단위 과세 사업자가 판매 목적으로 자기의 다른 사업장에 반출하는 것은 재화의 공급으로 보지 않는다(부가가치세법 제10조 제3항 제1호). 주사업장 총괄 납부 사업자의 반출도 공급으로 보지 않으며, 세금계산서를 발급하고 신고한 경우에만 공급으로 본다(같은 항 제2호).","c":"상","v":1},"관세사2023_40-02-3":{"f":"사업자 단위 과세를 포기한 경우에는 그 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장별로 신고ㆍ납부하거나 주사업장 총괄 납부를 할 수 있다.","w":"포기한 날이 속하는 과세기간부터가 아니라 그 다음 과세기간부터 각 사업장별로 신고·납부하고, 요건을 갖추면 주사업장 총괄 납부도 신청할 수 있다.","c":"상","v":1},"관세사2023_40-02-4":{"f":"사업자 단위 과세 사업자가 법인인 경우 각 사업장을 대신하여 그 사업자의 본점을 부가가치세 납세지로 한다.","w":"사업자 단위 과세 사업자의 납세지는 본점 또는 주사무소 소재지이다. 지점은 납세지가 될 수 없다.","c":"상","v":1},"관세사2023_40-02-5":{"f":"사업자 단위 과세 사업자가 종된 사업장을 이전하는 경우 사업자등록 정정 신고를 받은 세무서장은 신고일부터 2일 이내에 사업자등록증을 정정하여 재발급해야 한다.","w":"사업자 단위 과세 사업자가 종된 사업장을 신설하거나 이전한 경우 세무서장은 정정신고일부터 2일 이내에 사업자등록증을 재발급한다(부가가치세법 시행령 제14조 제1항 제9호, 제3항 제2호). 신고일 당일에 재발급하는 것은 상호 변경과 통신판매업자의 사이버몰 명칭·도메인 변경뿐이다.","c":"상","v":1},"관세사2023_40-03-5":{"f":"재화를 수입하는 자로서 법인격이 없는 사단ㆍ재단은 해당 수입재화에 대한 부가가치세를 납부할 의무가 있다.","w":"재화를 수입하는 자는 사업자인지와 관계없이 납세의무가 있고, 개인·법인(국가·지자체 포함)·법인격 없는 사단·재단 모두 해당한다.","c":"상","v":1},"관세사2023_40-04-1":{"f":"사업자가 법정기한까지 등록을 신청하지 아니한 경우에는 사업 개시일부터 등록을 신청한 날의 직전일까지의 공급가액 합계액의 1퍼센트를 납부세액에 더하거나 환급세액에서 뺀다.","w":"미등록 가산세 기간은 사업 개시일부터 등록 신청일의 직전일까지이다. 신청한 날까지가 아니다. 세율은 공급가액의 1퍼센트이다.","c":"상","v":1},"관세사2024_41-01-3":{"f":"사업자란 사업 목적이 영리이든 비영리이든 관계없이 사업상 독립적으로 재화 또는 용역을 공급하는 자를 말하므로 국가ㆍ지방자치단체도 포함된다.","w":"영리 목적은 요건이 아니고, 국가·지방자치단체·지방자치단체조합도 납세의무자인 사업자에 포함된다.","c":"상","v":1},"관세사2024_41-04-3":{"f":"각종 박람회 등 행사가 개최되는 장소에 개설한 임시사업장으로서 대통령령으로 정하는 바에 따라 신고된 장소는 사업장으로 보지 아니한다.","w":"신고된 임시사업장(박람회·경기대회 등)은 사업장으로 보지 않으므로 별도 사업장 등록 대상이 아니다.","c":"상","v":1},"관세사2024_41-05-2":{"f":"사업자등록신청을 받은 관할세무서장은 등록내용을 조사하여 2일 이내에 사업자등록증을 발급하여야 한다.","w":"사업자등록증은 신청일부터 2일 이내에 발급한다. 현장 확인이 필요하다고 국세청장이 인정하면 발급기한을 5일 이내에서 연장할 수 있다.","c":"하","v":1},"관세사2024_41-05-3":{"f":"사업을 영위하면서 사업자등록을 하지 아니한 사업자에 대하여 납세지 관할 세무서장은 조사하여 등록할 수 있다.","w":"사업자등록을 하지 않은 사업자는 납세지 관할 세무서장이 조사하여 직권으로 등록할 수 있다(부가가치세법 시행령 제11조 제6항).","c":"상","v":1},"관세사2024_41-05-4":{"f":"사업장이 하나이나 추가로 사업장을 개설하려는 사업자는 사업자 단위로 사업자등록을 신청할 수 있다.","w":"사업장이 하나인 사업자가 추가 사업장을 개설하는 경우에도 사업자 단위 과세를 선택해 본점 또는 주사무소에 사업자 단위로 등록을 신청할 수 있다. 신청은 의무가 아니고 선택이다.","c":"상","v":1},"관세사2024_41-05-5":{"f":"사업자는 사업자등록신청을 사업장 관할세무서장이 아닌 다른 세무서장에게 하여도 사업장 관할세무서장에게 한 것으로 본다.","w":"다른 세무서장에게 신청해도 유효하고 사업장 관할 세무서장에게 신청한 것으로 본다.","c":"상","v":1},"관세사2025_42-01-4":{"f":"법령으로 정하는 신탁재산과 관련된 재화를 수탁자 명의로 공급하는 경우 「신탁법」 에 따른 수탁자가 부가가치세를 납부할 의무가 있다.","w":"신탁재산 관련 재화·용역을 수탁자 명의로 공급하면 수탁자가 납세의무자이다. 위탁자 명의로 공급하면 위탁자가 납세의무를 진다.","c":"상","v":1},"관세사2025_42-02-5":{"f":"무인자동판매기를 통하여 재화를 공급하는 사업의 경우 사업에 관한 업무를 총괄하는 장소 외의 장소는 사업자의 신청에 따라 추가로 사업장으로 등록할 수 없다.","w":"무인자동판매기 사업은 사업에 관한 업무를 총괄하는 장소만 사업장이고 다른 장소를 추가 등록할 수 없다.","c":"상","v":1},"관세사2025_42-06-5":{"f":"간이과세자가 일반과세자로 변경되는 경우 그 변경되는 해에 간이과세자에 관한 규정이 적용되는 기간의 과세기간은 그 해 1월 1일부터 6월 30일까지로 한다.","w":"간이과세 적용기간의 과세기간은 1월 1일부터 6월 30일까지이고, 7월 1일부터 12월 31일까지는 일반과세자의 과세기간이다.","c":"상","v":1},"관세사2025_42-07-1":{"f":"법인의 경우에는 본점 또는 지점(분사무소를 포함한다)을 주된 사업장으로 할 수 있다.","w":"법인은 본점 또는 지점(분사무소 포함)을 주된 사업장으로 정할 수 있다. 개인사업자는 주사무소만 가능하다.","c":"상","v":1},"관세사2026_43-02-1":{"f":"주사업장 총괄 납부에 있어 사업자가 개인인 경우 주된 사업장은 주사무소로 한다.","w":"개인의 주된 사업장은 주사무소이고 분사무소는 될 수 없다. 법인은 본점 또는 지점(분사무소 포함)이 가능하다.","c":"상","v":1},"관세사2026_43-02-2":{"f":"주사업장 총괄 납부 사업자가 종된 사업장을 신설하는 경우에는 그 신설하는 종된 사업장 관할 세무서장에게 변경사유 등이 적힌 주사업장 총괄 납부 변경신청서를 제출하여야 한다.","w":"종된 사업장을 신설하면 주사업장 총괄 납부 변경신청서를 내야 하고, 제출처는 신설하는 종된 사업장의 관할 세무서장이다(부가가치세법 시행령 제93조 제1항 제1호). 주된 사업장 관할 세무서장에게 내는 것이 아니다.","c":"상","v":1},"관세사2026_43-02-4":{"f":"사업자 단위 과세 사업자가 사업자 단위 과세를 적법하게 포기한 경우에는 그 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장별로 신고ㆍ납부한다.","w":"포기한 날이 속하는 과세기간이 아니라 그 다음 과세기간부터 각 사업장별로 신고·납부한다.","c":"상","v":1},"관세사2026_43-02-5":{"f":"사업장단위로 등록한 사업자가 사업자 단위 과세 사업자로 변경하려면 사업자 단위 과세 사업자로 적용받으려는 과세기간 개시 20일 전까지 사업자의 본점 또는 주사무소 관할 세무서장에게 변경등록을 신청하여야 한다.","w":"변경등록은 적용받으려는 과세기간 개시 20일 전까지 신청하는 것이고 허가를 받는 절차가 아니다.","c":"상","v":1},"관세사2026_43-03-2":{"f":"국가ㆍ지방자치단체 또는 지방자치단체조합이 직접 공급하는 부동산 임대용역(과세사업)은 사업에 관한 업무를 총괄하는 장소를 사업장으로 한다.","w":"부동산 임대업은 부동산 등기부상 소재지가 원칙이지만 국가·지방자치단체·지방자치단체조합이 공급하는 경우에는 업무를 총괄하는 장소가 사업장이다.","c":"상","v":1},"관세사2017_34-01":{"w":"납세의무자는 과세물품을 제조해 반출하는 자(ㄷ), 과세유흥장소의 경영자(ㄱ), 과세영업장소인 카지노의 경영자(ㄴ)이다(개별소비세법 제3조). 폐광지역 카지노도 과세영업장소에 들어간다.\nㄹ: 입장행위 과세장소는 투전기를 설치한 장소이고 오락용 사행기구 설치 장소는 과세장소가 아니다. 사행기구는 제조해 반출하는 자가 물품분 개별소비세를 낸다.\nㅁ: 주세가 부과되는 주류는 개별소비세 비과세 물품이다(제2조). ㄱ, ㄴ, ㄷ이므로 3번이다.","c":"상","v":1},"관세사2017_34-03":{"w":"수렵용 총포류는 물품가격의 100분의 20이다(개별소비세법 제1조제2항제1호나목). 1번이다.\n이륜자동차는 물품가격의 100분의 5, 고급 융단과 보석은 기준가격을 넘는 부분(과세가격)의 100분의 20이고, 천연가스는 킬로그램당 세액을 매기는 종량세이다.","c":"상","v":1},"관세사2018_35-31":{"w":"무조건 면세 물품은 수출 물품의 재수입 용기, 외국 자선·구호기관 기증 물품, 조난 해체재와 장비품, 외국 박람회 출품용 반출 물품이다.\n의료용·의약품 제조용·비료 제조용·농약 제조용·석유화학공업용 원료 석유류는 조건부 면세이다. 4번이다.","c":"중","v":1},"관세사2018_35-32":{"w":"물품가격의 100분의 20 세율을 적용하는 것은 투전기(ㄱ)와 수렵용 총포류(ㅁ)이다.\n귀금속 제품과 고급 가구는 기준가격 초과분에 대해 20퍼센트이고, 전기승용자동차는 100분의 5이다. 2번이다.","c":"중","v":1},"관세사2018_35-33":{"w":"개별소비세 납세의무자는 과세물품 제조·반출자, 보세구역 반출자, 과세유흥장소·과세영업장소 경영자 등이다.\n고급 모피를 일시적으로 직접 판매하는 소비자는 납세의무자가 아니다. 5번이다.","c":"상","v":1},"관세사2018_35-34":{"w":"500만원을 한도로 하는 조건부 면세는 대통령령으로 정하는 장애인이 구입하는 승용자동차(장애인 1명당 1대)이다. 5번이다.","c":"중","v":1},"관세사2019_36-31":{"w":"물품가격의 100분의 20 세율을 적용하는 것은 오락용 사행기구이다. 귀금속·고급 시계는 기준가격 초과분의 100분의 20이고, 배기량 2,000cc 초과 승용자동차는 100분의 5이며, 유연탄은 종량세이다. 1번이다.","c":"중","v":1},"관세사2019_36-33":{"w":"조건부 면세는 보석 중 이화학 실험연구용·공업용·축음기 침 제작용(ㄴ), 재수출할 물품으로 관세가 면제되는 것(ㄷ), 여객자동차운송사업용 승용자동차(ㄹ) 등이다.\n외국 자선·구호기관 기증물품(ㄱ), 국가·지방자치단체 기증물품(ㅁ), 상업용 견본·광고용품(ㅂ)은 무조건 면세이다. 4번이다.","c":"중","v":1},"관세사2020_37-32":{"w":"투전기의 세율은 물품가격의 100분의 20이다(제1조제2항제1호가목). 2번이다.\n수렵용 총포류에서 공기총은 과세물품에서 빠진다(시행령 별표 1). 경유는 리터당 340원이고 리터당 90원은 등유의 세율이다. 토끼 모피와 공업용 다이아몬드는 과세물품에서 제외된다.","c":"상","v":1},"관세사2020_37-34":{"w":"조건부 면세 물품은 이화학 실험연구용 보석, 외국 무역선에서 쓸 연료 외 소모품, 외국에서 자선·구호·학술연구 목적으로 기증되는 물품이다.\n외국의 자선·구호기관·단체에 기증하는 물품은 무조건 면세이다. 5번이다.","c":"중","v":1},"관세사2022_39-33":{"w":"ㄱ O: 수출할 물품을 다른 장소로 반출하는 것은 미납세반출 대상이다.\nㄴ X: 미납세반출 물품이 반입 전에 재해 등 부득이한 사유로 멸실되면 개별소비세를 징수하지 않는다.\nㄷ X: 보세구역에서 반출하려는 자는 수입신고 수리 전에 미납세반출 승인을 신청해야 한다.\nㄹ X: 승인 사실의 통보는 세관장이 하는 일이다.\nㄱ만 옳아 1번이다.","c":"중","v":1},"관세사2022_39-36":{"w":"조 단위로 판매되는 고급 가구는 1조당 800만원을 초과하는 부분의 가격에 100분의 20이다. 4번이다.\n수렵용 총포류는 100분의 20, 고급 모피는 기준가격 초과분의 100분의 20, 전기승용자동차는 100분의 5, 투전기 설치 장소 입장은 1명 1회 1만원이다.","c":"중","v":1},"관세사2023_40-31":{"w":"과세물품이 아닌 것은 수렵용 공기총(ㄴ), 공업용 다이아몬드(ㄷ), 토끼모피(ㄹ), 시각장애인용 고급시계(ㅁ)이다. 핀볼머신(ㄱ)과 액화 천연가스(ㅂ)는 과세물품이다. 4번이다.","c":"하","v":1},"관세사2023_40-32":{"w":"유연탄의 세율은 킬로그램당 46원이다(개별소비세법 제1조제2항제4호자목). 5번이 옳지 않다.\n투전기는 물품가격의 100분의 20, 휘발유는 리터당 475원, 경유는 리터당 340원, 제1종 궐련은 20개비당 594원(별표)으로 모두 법에 적힌 세율과 같다.","c":"상","v":1},"관세사2023_40-33":{"w":"외국인전용판매장 반입을 위해 제조장에서 반출할 때 개별소비세를 면제받을 수 있는 물품은 귀금속, 고급 가구, 고급 융단, 고급 가방 등이다. 고급 시계는 포함되지 않는다. 5번이다.","c":"중","v":1},"관세사2023_40-35":{"w":"외상이나 할부로 반출하면 해당 물품을 인도한 날의 실제 반출가격을 반출가격으로 한다(시행령 제8조제1항제1호). 외상대금 청산일의 가격이 아니므로 1번이 옳지 않다.\n저가 교환은 교환한 날의 실제 반출가격, 운송비 균일 포함은 운송비 포함 가격, 무상 반출은 반출한 날의 실제 반출가격, 반출 뒤 일정액 환급은 처음의 반출가격으로 한다.","c":"상","v":1},"관세사2023_40-36":{"w":"과세장소 경영자는 매 분기 과세장소의 종류별·세율별로 입장 인원과 입장 수입을 적은 신고서를 입장한 날이 속하는 분기의 다음 달 25일까지 과세장소 관할 세무서장에게 제출한다. 5번이다.","c":"중","v":1},"관세사2024_41-34":{"w":"운송비를 운송거리나 운송방법에 상관없이 같은 금액으로 하여 반출가격에 포함시키거나 별도로 받는 경우(운송기관이 운송을 담당하는 경우 포함)에는 운송비를 포함한 가격을 반출가격으로 한다. 4번이다.","c":"중","v":1},"관세사2024_41-35":{"w":"ㄱ O: 미납세반출 승인신청서에는 반입장소와 반입자의 인적사항을 적는다(시행령 제19조제1항).\nㄴ X: 미납세반출하면 반입 장소를 제조장으로, 반입자를 제조자로 본다(법 제14조제4항).\nㄷ X: 반입한 자는 반입지 관할 세무서장 또는 세관장에게 반입 사실을 신고한다(법 제14조제5항).\n옳지 않은 것은 ㄴ, ㄷ이므로 4번이다.","c":"상","v":1},"관세사2024_41-36":{"w":"기준가격 초과분을 과세표준으로 하는 물품은 귀금속 제품, 고급 시계, 고급 융단, 고급 가방, 고급 가구, 고급 모피이다.\n전기승용자동차는 물품가격 전체에 세율을 적용한다. 2번이다.","c":"중","v":1},"관세사2025_42-33":{"w":"미납세반출 대상은 동일 제조장에서 다른 제품 원료로 쓰는 것, 박람회 출품 조건 수입 물품, 승용자동차를 판매장에 30일 이상 전시하는 반출·환입, 판매장·제조장 이전 반출 등이다.\n수출하는 것은 미납세반출이 아니라 면세 대상이다. 5번이다.","c":"중","v":1},"관세사2025_42-35":{"w":"무조건 면세는 외국에 항행 중인 군함이나 재외공관으로부터 송부되는 공용품(ㄴ)이다.\n외국에서 학술연구단체에 기증되는 물품(ㄱ)과 이화학 실험연구용 보석(ㄷ)은 조건부 면세이다. 2번이다.","c":"중","v":1},"관세사2025_42-36":{"w":"금전등록기를 설치·사용하고 감사테이프를 보관하면 장부에 기록한 것으로 보는 사업자는 과세유흥장소의 경영자 중 대통령령으로 정하는 자이다. 4번이다.","c":"중","v":1},"관세사2026_43-32":{"w":"일정 금액을 한도로 면제하는 조건부 면세는 대통령령으로 정하는 장애인이 구입하는 승용자동차(장애인 1명당 1대, 500만원 한도)이다. 1번이다.","c":"상","v":1},"관세사2026_43-33":{"w":"투전기를 설치한 장소는 1명 1회 입장에 1만원이다. 3번이다.","c":"중","v":1},"관세사2026_43-34":{"w":"입찰로 반출하면서 입찰견적서에 운송비가 따로 계상돼 있더라도 낙찰가격에 운송비가 포함돼 있으면 운송비를 포함한 가격이 반출가격이다. 「운송비를 포함하지 않은 가격」이라고 한 1번이 옳지 않다.","c":"중","v":1},"관세사2026_43-36":{"w":"국내에서 제조해 개별소비세가 부과되지 않은 물품이 국외로 반출된 뒤 수출신고 수리일부터 6개월 내에 재수입돼 과세물품이 되는 경우, 원재료에 대해 면제·환급·공제를 받은 사실이 없다고 관할 세무서장이 증명하면 무조건 면세이다. ㄱ 수출신고, ㄴ 6, ㄷ 없다로 1번이다.","c":"중","v":1},"관세사2017_34-06":{"w":"납세증명표지가 없는 주류를 판매하거나 보유한 경우는 3개월 이내의 판매 정지 사유이고 면허 취소 사유가 아니다(현행 주류 면허 등에 관한 법률 제12조). 1번이다.\n부정한 방법의 면허 취득, 무면허 제조 주류나 주세 면제 주류의 판매·보유, 2주조연도 이상 계속 미판매, 타인과의 동업 경영은 판매업면허 취소 사유이다(같은 법 제14조의2).","c":"상","v":1},"관세사2017_34-07":{"w":"(2019 개정 전 기준) 출제 당시 주정은 수량, 주정 외의 주류는 가격을 과세표준으로 했다.\nㄱ X: 주정의 과세표준은 출고·수입신고하는 수량이었다.\nㄴ O: 주정 외 주류는 출고하는 때의 가격, 수입하면 관세의 과세가격과 관세를 합한 금액이었다.\nㄷ X: 출고 가격에는 용기 대금과 포장비용을 모두 포함한다.\nㄹ X: 상거래 관습상 일정액을 통상가격에서 공제해 출고하면 공제 전 통상가격을 주류 가격으로 한다.\nㅁ O: 거리와 상관없이 받는 운송비가 같으면 운송비를 포함한 가격을 주류 가격으로 한다.\nㄴ, ㅁ이므로 2번이다. 2020년부터 탁주와 맥주도 수량을 과세표준으로 하므로(현행 주세법 제7조제1항) 현행법으로는 ㄴ도 틀린 진술이 된다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 주정은 수량, 주정 외의 주류는 가격을 과세표준으로 했다.\nㄱ X: 주정의 과세표준은 출고·수입신고하는 수량이었다.\nㄴ O: 주정 외 주류는 출고하는 때의 가격, 수입하면 관세의 과세가격과 관세를 합한 금액이었다.\nㄷ X: 출고 가격에는 용기 대금과 포장비용을 모두 포함한다.\nㄹ X: 상거래 관습상 일정액을 통상가격에서 공제해 출고하면 공제 전 통상가격을 주류 가격으로 한다.\nㅁ O: 거리와 상관없이 받는 운송비가 같으면 운송비를 포함한 가격을 주류 가격으로 한다.\nㄴ, ㅁ이므로 2번이다. 2020년부터 탁주와 맥주도 수량을 과세표준으로 하므로(현행 주세법 제7조제1항) 현행법으로는 ㄴ도 틀린 진술이 된다."},"관세사2017_34-10":{"w":"주류 제조장에서 출고한 자는 매 분기 출고한 주류의 종류·알코올분·수량·가격·세율·산출세액 등을 적은 신고서를 출고한 날이 속하는 분기의 다음 달 25일까지 관할 세무서장에게 제출한다. 4번이다.","c":"하","v":1},"관세사2018_35-38":{"w":"주한외국공관에 납품하는 주류는 면세되지만 영사관 가운데 명예영사관은 제외된다(주세법 시행령 제19조제2항). 2번이다.\n출입국항 보세구역 안에서 출국자에게 판매하는 것은 수출에 포함되어 면세되고, 우리나라에 주둔하는 외국 군대 납품과 외국 선원 휴게소 안에서 음용에 제공하는 납품도 면세이다. 여행자가 입국할 때 직접 가지고 오는 주류로서 관세가 면제되는 것은 수입 면세이다(주세법 제20조).","c":"상","v":1},"관세사2018_35-39":{"w":"(2019 개정 전 기준) 출제 당시 탁주의 세율은 100분의 5였다. 1번이다. 맥주는 100분의 72, 과실주·청주·약주는 100분의 30이었다.\n2020년부터 탁주와 맥주는 종량세로 바뀌어 현행 세율은 탁주 1킬로리터당 4만4400원, 맥주 1킬로리터당 88만5700원이다(주세법 제8조제1항). 현행법으로는 옳은 선지가 없다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 탁주의 세율은 100분의 5였다. 1번이다. 맥주는 100분의 72, 과실주·청주·약주는 100분의 30이었다.\n2020년부터 탁주와 맥주는 종량세로 바뀌어 현행 세율은 탁주 1킬로리터당 4만4400원, 맥주 1킬로리터당 88만5700원이다(주세법 제8조제1항). 현행법으로는 옳은 선지가 없다."},"관세사2018_35-40":{"w":"제조장에 있는 주류가 부가가치세법상 재화의 공급으로 보는 경우(ㄱ)와 공매·경매되거나 파산절차로 환가된 경우(ㄴ)는 제조장에서 반출(출고)된 것으로 본다(주세법 제15조).\nㄷ: 부패로 폐기한 주류는 반출로 보는 경우에 없다.\nㄹ: 제조면허가 취소된 뒤 제조장에 남은 주류는 반출로 보지만, 세무서장이 기간을 정해 반제품의 제조·반출을 계속하게 한 경우는 그 예외로 반출로 보지 않는다.\nㄱ, ㄴ이므로 1번이다.","c":"상","v":1},"관세사2019_36-35":{"w":"면세주류는 우리나라에 주둔하는 외국 군대에 납품하는 것, 수출하는 것, 외국 선원 휴게소 납품, 검사목적 수거, 의약품 제조 원료 사용 등이다.\n「외국에 주둔하는」 외국 군대는 면세 대상이 아니다. 1번이다.","c":"중","v":1},"관세사2019_36-36":{"w":"(2019 개정 전 기준) 출제 당시 세율은 탁주 100분의 5, 약주·과실주·청주 100분의 30, 맥주 100분의 72, 증류주류 100분의 72였다. 청주를 100분의 20으로 적은 3번이 옳지 않다.\n2020년부터 탁주와 맥주는 종량세로 바뀌어 현행 세율은 탁주 1킬로리터당 4만4400원, 맥주 1킬로리터당 88만5700원이다(주세법 제8조제1항). 현행법으로는 1번과 4번도 틀린 선지가 된다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 세율은 탁주 100분의 5, 약주·과실주·청주 100분의 30, 맥주 100분의 72, 증류주류 100분의 72였다. 청주를 100분의 20으로 적은 3번이 옳지 않다.\n2020년부터 탁주와 맥주는 종량세로 바뀌어 현행 세율은 탁주 1킬로리터당 4만4400원, 맥주 1킬로리터당 88만5700원이다(주세법 제8조제1항). 현행법으로는 1번과 4번도 틀린 선지가 된다."},"관세사2019_36-38":{"w":"판매정지 사유에 해당하는 것은 납세증명표지가 없는 주류를 판매하거나 보유한 경우이다. 5번이다.\n주세 포탈, 면허 양도·대여, 면허 주류 외 제조는 제조면허 취소·정지 등의 사유이다.","c":"중","v":1},"관세사2019_36-40":{"w":"제조장에서 마신 경우, 제조장에 있는 주류가 파산절차로 환가되거나 공매·경매된 경우, 부가가치세법상 재화의 공급으로 보는 경우는 제조장에서 반출(출고)된 것으로 본다(주세법 제15조).\n면허 취소 신청서를 낼 때 제조장에 남아 있는 주류를 기간을 정해 계속 반출하도록 관할 세무서장의 승인을 받은 경우는 반출로 보는 경우에서 빠진다(시행령 제13조제1항제2호). 5번이다.","c":"상","v":1},"관세사2020_37-36":{"w":"ㄱ O: 관할 세무서장은 주세 보전을 위해 금액과 기간을 정해 담보 제공이나 납세보증주류 보존을 명할 수 있다.\nㄴ O: 납세 보증으로 보존하는 주류의 가격은 통상가격이다.\nㄷ X: 가격 변경 신고는 변경일이 속하는 분기의 다음 달 25일까지 한다(현행 주류 면허 등에 관한 법률 시행령 제23조). 「달의 다음 달」이 아니다.\nㄹ X: 같은 제조장에서 제조업을 승계하는 자의 주류 제조에 쓰려고 양도하는 밑술은 승인 없이 처분·반출할 수 있다(같은 영 제26조).\nㅁ O: 판매업면허를 받은 자가 납세증명표지 없는 주류를 가지고 있으면 판매 목적으로 가진 것으로 본다.\nㄷ, ㄹ이므로 4번이다.","c":"상","v":1},"관세사2020_37-37":{"w":"주정의 세율은 1킬로리터당 5만 7천원이고 알코올분 95도를 초과하는 1도마다 600원을 더한다. 96도이면 5만 7천 6백원이므로 5만 7천원으로 적은 1번이 옳지 않다.\n2020년 탁주 41,700원/킬로리터, 약주·과실주·청주 100분의 30, 소주 100분의 72는 맞다.","c":"중","v":1},"관세사2020_37-39":{"w":"면세 주류는 출입국항 보세구역 안 판매, 검사목적 수거, 의약품 제조 원료로 수입하는 것, 변질 등으로 동일 제조자의 제조장에 다시 들어온 수출 주류, 외국에서 기증한 의식용 주류이다.\n사원·교회 등에 의식용으로 「국내에서」 기증한 것은 면세 대상이 아니다. 1번이다.","c":"중","v":1},"관세사2022_39-37":{"w":"환입 주류 세액공제·환급의 생산 중단 사유는 신고한 주류 상품을 2주조연도 이상 계속 제조하지 않은 경우이다(주세법 시행령 제17조제1항). 1주조연도로 적은 2번은 적용 사유가 아니다.\n품질불량으로 같은 제조자의 제조장에 다시 들어온 경우, 수입주류가 품질불량·변질로 수입신고자의 본점 소재지나 하치장에서 폐기된 경우, 유통과정 중 파손·자연재해로 멸실된 경우는 모두 적용된다(주세법 제18조제1항).","c":"상","v":1},"관세사2022_39-39":{"w":"ㄱ X: 조주정도 주정에 포함된다.\nㄴ O: 불휘발분은 전체용량에 포함되어 휘발되지 않는 성분이다.\nㄷ O: 대한민국식품명인이 제조하는 주류는 주원료 생산지와 무관하게 전통주로 인정된다.\nㄹ X: 주류 제조 수탁자는 위탁자의 상표명으로 주류를 제조하는 자이다.\n옳지 않은 것은 ㄱ, ㄹ이므로 4번이다.","c":"중","v":1},"관세사2023_40-37":{"w":"면세주류는 외국에 주둔하는 국군부대에 납품하는 주류(ㄱ), 검사목적으로 수거하는 주류(ㄴ), 약사법에 따라 의약품 원료로 수입하는 주류(ㅂ)이다.\n종교단체에 국내에서 기증한 주류(ㄷ), 무형문화재 기능보유자가 판매 목적으로 제조한 주류(ㄹ), 명예영사관이 수입하는 주류(ㅁ)는 면세가 아니다. 2번이다.","c":"중","v":1},"관세사2024_41-38":{"w":"소주 등 증류주류의 세율은 100분의 72이다. 100분의 80으로 적은 5번이 옳지 않다.\n맥주 수입은 수입신고 수량, 위스키 수입은 수입신고 때의 가격이 과세표준이고, 주정 세율은 1킬로리터당 5만 7천원(95도 초과 1도마다 600원 가산), 청주는 100분의 30이다.","c":"상","v":1},"관세사2024_41-39":{"w":"수출하는 것, 주한외교관의 자가 소비용 수입, 의약품 제조 원료, 검사목적 수거는 면세 주류이다.\n사원·교회 등에 의식용으로 국내에서 기증한 것은 면세 주류가 아니다. 2번이다.","c":"중","v":1},"관세사2025_42-38":{"w":"반출로 보는 경우 가운데 제조면허 취소 뒤 남은 주류(제15조제2호), 공매·경매·파산 환가(제3호), 담보 미제공(제16조)은 사유가 생긴 달의 다음 달 말일까지 신고한다(주세법 제9조제2항). ㄷ만 해당해 3번이다.\n제조장에서 마신 경우(ㄱ, 제15조제1호)와 재화의 공급으로 보는 경우(ㄴ, 제4호)는 일반 신고처럼 분기의 다음 달 25일까지 신고한다.","c":"상","v":1},"관세사2025_42-39":{"w":"면세 주류는 주한외국공관의 외교관이 자가 소비용으로 직접 수입하는 것(ㄱ), 검사목적으로 수거하는 것(ㄴ), 수출된 주류가 품질불량 등으로 동일 제조자의 제조장에 다시 들어온 것(ㄷ)이다. 5번이다.","c":"중","v":1},"관세사2025_42-40":{"w":"주류는 알코올분 1도 이상의 음료이고, 알코올분 도수는 섭씨 15도에서 전체용량 100분 중 알코올분의 용량이다. 약사법상 의약품으로서 알코올분 6도 미만인 것은 주류에서 제외한다. ㄱ 1, ㄴ 15, ㄷ 6으로 1번이다.","c":"상","v":1},"관세사2026_43-39":{"w":"전통주는 무형유산 보유자(시·도무형유산 보유자 포함)와 대한민국식품명인이 제조하는 주류이다(ㄱ, ㄴ).\n주류제조장 소재지 관할 시·군·구에서 생산한 농산물을 쓰는 것(ㄷ)만으로는 전통주가 아니다. 2번이다.","c":"중","v":1},"관세사2026_43-40":{"w":"주류 제조장에서 주류를 반출한 자는 매 분기 반출한 주류의 종류·알코올분·수량·가격·세율·산출세액 등을 적은 신고서를 반출한 날이 속하는 분기의 다음 달 25일까지 관할 세무서장에게 제출한다. 4번이다.","c":"중","v":1},"관세사2017_34-12":{"w":"ㄹ O: 내국신용장이나 구매확인서에 따라 국내 다른 사업자에게 공급하는 재화(금지금 제외)는 수출에 포함되어 영세율이 적용된다(부가가치세법 시행령 제31조).\nㅁ O: 선박이나 항공기에 의한 외국항행용역은 영세율 대상이다(법 제23조).\nㄱ X: 국내 부동산 임대용역은 비거주자에게 제공하고 외화를 원화로 받더라도 영세율 대상 용역에 들어 있지 않다.\nㄴ X: 국내사업장 없는 비거주자와의 국내 거래 재화는 비거주자가 지정하는 국내사업자에게 인도되어 그 사업자의 과세사업에 쓰일 때 영세율이 적용된다(시행령 제33조제2항제1호). 비거주자에게 직접 인도하면 해당하지 않는다.\nㄷ X: 수출재화임가공용역이라도 부가가치세를 별도로 적은 세금계산서를 발급하면 영세율에서 제외된다(시행령 제31조제2항제3호 단서).\nㄹ, ㅁ이므로 3번이다.","c":"상","v":1},"관세사2017_34-23":{"w":"부동산을 취득하고 판매하는 부동산매매업은 용역이 아니라 재화(부동산)를 공급하는 사업이다. 음식점업, 운수업, 가구 내 고용활동, 공공행정 등은 용역에 해당한다. 3번이다.","c":"중","v":1},"관세사2017_34-26":{"w":"재화의 공급으로 보지 않는 것은 저당권 목적의 부동산 제공(ㄱ), 민사집행법에 따른 경매(ㄴ), 조달청 보세창고 창고증권의 양도로서 임치물의 반환이 수반되지 않는 것(ㄷ)이다.\n자기가 주요자재 일부를 부담해 가공한 새로운 재화를 인도하는 것(ㄹ)은 재화의 공급이다. 4번이다.","c":"중","v":1},"관세사2017_34-27":{"w":"저작권의 양도는 권리의 양도로서 재화의 공급이다. 건설자재 일부를 부담하는 건설용역, 방송프로그램 방영, 산업상 정보 제공, 주요자재 없이 단순 가공만 해 주는 것은 용역의 공급이다. 2번이다.","c":"중","v":1},"관세사2017_34-30":{"w":"사업장이 둘 이상인 사업자가 사업자 단위 과세 적용을 받는 과세기간에 자기 사업과 관련한 재화를 다른 사업장으로 반출하는 것은 재화의 공급으로 보지 않는다. 1번이다.\n개인적 목적 사용, 면세사업용 사용, 폐업 시 남은 재화, 운수업자가 영업 외 용도로 쓰는 자동차 등은 재화의 공급으로 본다.","c":"중","v":1},"관세사2018_35-01":{"w":"도매 및 소매업은 재화를 공급하는 사업이다. 운수업, 금융 및 보험업, 방송통신 및 정보서비스업, 숙박 및 음식점업은 용역을 공급하는 사업이다. 3번이다.","c":"상","v":1},"관세사2018_35-05":{"w":"자기가 주요 자재 일부 또는 전부를 부담하고 상대방에게서 인도받은 재화를 가공해 새로운 재화를 만드는 가공계약에 따라 재화를 인도하는 것은 재화의 공급이어서 과세거래이다. 2번이다.\n견본품의 무상 인도, 상속세 물납, 신탁 수탁자 변경, 담보권 실행을 위한 경매는 재화의 공급으로 보지 않는다.","c":"중","v":1},"관세사2018_35-07":{"w":"ㄱ O: 폐업 전에 공급한 재화·용역의 공급시기가 폐업일 이후이면 폐업일이 공급시기이다.\nㄴ X: 조건부 판매·기한부 판매는 조건이 성취되거나 기한이 지나 판매가 확정되는 때가 공급시기이다.\nㄷ O: 용역의 대가를 미리 전부 받고 세금계산서를 발급하면 발급하는 때가 공급시기이다.\nㄹ X: 수출재화는 수출재화의 선(기)적일이 공급시기이다.\nㄱ, ㄷ이므로 2번이다.","c":"중","v":1},"관세사2018_35-08":{"w":"재화의 인도 대가로 다른 재화를 인도받거나 용역을 제공받는 교환계약은 재화의 공급이다. 4번이다.\n수용절차에서의 수용 대가, 특별재난지역에 대한 증여, 담보 제공, 시험용 사용·소비는 재화의 공급으로 보지 않는다.","c":"중","v":1},"관세사2018_35-09":{"w":"외국을 항행하는 선박·항공기나 원양어선에 공급하는 재화는 영세율 대상이지만 부가가치세를 별도로 적은 세금계산서를 발급하면 영세율에서 제외된다(부가가치세법 시행령 제33조제2항제5호 단서). 5번이다.\n중계무역 방식의 수출(시행령 제31조제1항제1호), 국내사업장 없는 외국법인에게 제공하고 대금을 외국환은행에서 원화로 받는 보세운송용역, 선박·항공기에 의한 외국항행용역, 대한민국 선박이 잡은 수산물의 외국 반출은 영세율이 적용된다.","c":"상","v":1},"관세사2018_35-10":{"w":"은행업에 관련된 전산시스템과 소프트웨어의 판매·대여 용역은 면세가 아니라 과세이다.\n의료법상 의사가 제공하는 악안면 교정술, 장의용역, 보험회사에 제공하는 손해사정용역, 관세가 면제되는 상품 견본과 광고용 물품은 면세이다. 1번이다.","c":"중","v":1},"관세사2019_36-03":{"w":"대가 없이 국외 수탁가공 사업자에게 원자재를 반출하는 것의 공급시기는 외국에서 해당 재화가 인도되는 때이다. 반출하는 때로 적은 1번이 옳지 않다.","c":"중","v":1},"관세사2019_36-04":{"w":"ㄱ O: 특허권 대여는 용역의 공급이다.\nㄴ O: 공익사업 관련 지역권·지상권의 설정·대여는 과세 용역에서 제외된다.\nㄷ O: 주사업장 총괄 납부 적용 시 세금계산서를 발급하고 신고하면 공급으로 본다.\nㄹ O: 영세율을 적용받는 재화가 폐업 시 남아 있으면 자기에게 공급하는 것으로 본다.\nㅁ X: 사업양도에서 양수자가 대가 지급 때 부가가치세를 징수해 대리납부한 경우에는 재화의 공급으로 본다.\n옳지 않은 것은 ㅁ이므로 2번이다.","c":"중","v":1},"관세사2019_36-08":{"w":"수용절차에서 수용대상 재화의 소유자가 수용 대가를 받는 것은 재화의 공급으로 보지 않는다. 4번이다.\n건물의 현물출자는 재화의 공급이고, 주요자재 없이 단순 가공만 해 주는 것은 용역의 공급이며, 상품권을 받고 재화를 넘기는 것도 재화의 공급이다. 창립기념일 관련 재화는 사용인 1명당 연간 10만원까지만 공급으로 보지 않으므로 15만원짜리를 주면 초과한 5만원은 재화의 공급이다(시행령 제19조의2제3호).","c":"상","v":1},"관세사2019_36-13":{"w":"ㄱ O: 영세율 적용 대상인 면세 재화(식용이 아닌 임산물 수출 등)는 면세 포기를 신고해 면제를 받지 않을 수 있다.\nㄴ X: 구매확인서에 의해 공급하는 재화에도 영세율을 적용한다.\nㄷ X: 영세율 적용 시 매입세액은 매출세액을 한도로 하지 않고 전액 공제·환급된다.\nㄹ O: 영세율 적용 사업자도 부가가치세 납세의무와 신고의무가 있다.\nㄱ, ㄹ이므로 2번이다.","c":"중","v":1},"관세사2019_36-14":{"w":"면세 대상이 아닌 것은 은행이 제공하는 상품권에 관한 대행용역이다. 3번이다.\n원시가공 농산물, 수급자가 기르는 동물의 수의사 진료용역, 국선대리인 용역, 도서대여 용역은 면세이다.","c":"중","v":1},"관세사2020_37-07":{"w":"전력처럼 공급단위를 구획할 수 없는 재화를 계속 공급하면 대가의 각 부분을 받기로 한 때가 공급시기이다(부가가치세법 시행령 제28조제3항제4호). 5번이다.\n반환조건부 판매는 조건이 성취되어 판매가 확정되는 때이다. 완성도기준지급조건부와 중간지급조건부에서 인도일 이후에 받기로 한 대가 부분은 재화가 인도되거나 이용가능하게 되는 날이 공급시기이다(같은 항 단서). 장기할부판매는 이 단서가 적용되지 않아 인도일 이후 대가도 대가의 각 부분을 받기로 한 때가 공급시기이다.","c":"상","v":1},"관세사2020_37-09":{"w":"ㄱ 공급: 판매 목적으로 자기의 다른 사업장에 반출하는 경우(총괄납부·사업자단위 과세 적용 제외)\nㄴ 공급: 대가의 전부를 받고 견본품을 인도하면 판매이다.\nㄷ 아님: 특별재난지역에 대한 증여는 재화의 공급으로 보지 않는다.\nㄹ 아님: 양도담보 목적의 제공은 재화의 공급이 아니다.\nㄱ, ㄴ이므로 1번이다.","c":"중","v":1},"관세사2020_37-11":{"w":"국외 소재 부동산의 임대용역은 국외에서 공급하는 용역이어서 국내 과세대상이 아니고 영세율 적용 대상도 아니다. 2번이다.","c":"상","v":1},"관세사2020_37-12":{"w":"면세 대상은 여성용 생리 처리 위생용품(ㄱ)과 감염병예방법상 소독업자가 공급하는 소독용역(ㄹ)이다.\n보건용 마스크(ㄴ)와 삭도에 의한 여객운송 용역(ㄷ)은 과세이다. 3번이다.","c":"중","v":1},"관세사2020_37-22":{"w":"부가가치세법 시행령 제101조 제1항 표: 내국물품의 외국 반출(직수출)은 수출실적명세서, 소포우편 수출은 우체국장이 발행한 소포수령증, 용역의 국외공급은 외화입금증명서나 용역 계약서, 한국국제협력단에 공급하는 재화는 협력단이 교부한 공급사실 증명서류를 첨부한다.\n중계무역·위탁판매·외국인도·위탁가공무역 방식의 수출(법 제21조 제2항 제2호)은 수출계약서 사본이나 외국환은행이 발행하는 외화입금증명서를 낸다. 수출업자가 발급하는 상업송장은 첨부서류가 아니다.\n정답 ③.","c":"상","v":1},"관세사2022_39-05":{"w":"재화 공급으로 과세되는 금액을 항목별로 따진다.\n무인판매기: 현금을 꺼낸 때가 공급시기이므로 2022년 1월 5,000,000원이 제1기에 해당한다.\n장기할부판매: 인도 시에 세금계산서를 전액 발급했으므로 2021년 공급이다.\n시험사용 후 구매확정 조건부 판매: 구매가 확정되는 때(2022년 8월경)가 공급시기이므로 제1기가 아니다.\n재화와 용역을 교환하는 계약: 인도하는 때(2022년 6월)가 공급시기이므로 5,000,000원이 제1기에 해당한다.\n합계 10,000,000원으로 2번이다.","c":"상","v":1},"관세사2022_39-06":{"w":"사업을 위해 착용하는 작업복을 사용인에게 무상 제공하는 것은 재화의 공급으로 보지 않는다. 4번이다.\n고객에게 증여, 개인적 목적 소비, 면세사업용 사용, 폐업 시 남은 재화는 공급으로 본다.","c":"중","v":1},"관세사2022_39-08":{"w":"ㄱ O: 상품권은 현물로 교환될 때 재화가 실제로 인도되는 때가 공급시기이다.\nㄴ O: 가공은 가공된 재화를 인도하는 때이다.\nㄷ O: 동의조건부 판매는 조건이 성취되어 판매가 확정되는 때이다.\nㄹ X: 공급시기 전에 세금계산서를 발급하고 7일 이내에 대가를 받으면 세금계산서 발급일이 공급시기이다.\nㄱ, ㄴ, ㄷ이므로 4번이다.","c":"상","v":1},"관세사2022_39-10":{"w":"겸용주택은 주택 면적이 점포 면적보다 크면 전부를 주택으로 보고, 같거나 작으면 주택 부분만 주택으로 보며 부수토지는 총토지면적 × 주택면적/총건물면적으로 나눈다(부가가치세법 시행령 제41조). 면세되는 부수토지는 도시지역 밖이므로 주택 정착면적의 10배까지이다.\n사례 ㄷ: 1층 주택 100㎡가 점포보다 커서 전부 주택이다. 정착면적 100 × 10 = 1,000㎡가 면세된다.\n사례 ㄱ: 주택 180㎡ > 점포 60㎡이므로 전부 주택이다. 정착면적 60 × 10 = 600㎡가 면세된다.\n사례 ㄴ: 주택 120㎡(1층 60, 3층 60)가 점포 160㎡(1층 60, 2층 60·40)보다 작아 주택 부분만 주택이다. 1,200 × 120/280 ≈ 514㎡이고 한도(주택 정착면적 약 51.4㎡ × 10)도 같은 값이다.\nㄷ(1,000) > ㄱ(600) > ㄴ(약 514) 순으로 5번이다. 표의 「점포 40」은 사례 ㄴ의 2층 칸으로 읽었다.","c":"중","v":1},"관세사2022_39-11":{"w":"면세 교육 용역은 공립학교, 청소년수련시설, 사회적기업, 과학관 등에서 하는 교육이다.\n체육시설법에 따른 무도학원은 면세 교육 용역이 아니다. 5번이다.","c":"중","v":1},"관세사2022_39-12":{"w":"재화 중 면세 대상은 가공되지 않은 식료품, 도서(광고 제외), 토지이다. 유연탄은 과세이다. 4번이다.","c":"중","v":1},"관세사2022_39-14":{"w":"영세율 적용 대상인 재화·용역은 면세 포기를 신고해 부가가치세 면제를 받지 않을 수 있다. 면세 포기를 신고한 사업자는 신고한 날부터 3년이 지난 뒤 면세를 받으려면 면세적용신고서를 제출한다. 5번이다.","c":"중","v":1},"관세사2023_40-05":{"w":"부동산업 및 임대업은 용역을 공급하는 사업이지만 전·답·과수원·목장용지·임야 또는 염전 임대업은 용역의 범위에서 빠진다(부가가치세법 시행령 제3조제1항). 1번이다.\n교육 서비스업, 운수 및 창고업, 금융 및 보험업, 보건업 및 사회복지 서비스업은 용역의 범위에 들어간다.","c":"상","v":1},"관세사2023_40-07":{"w":"재화의 공급은 기계의 현물출자(ㄱ), 특허권 같은 권리의 양도(ㄴ), 가스의 공급(ㅁ)이다.\n저당권 목적 제공(ㄷ)과 상속세 물납(ㄹ)은 재화의 공급이 아니다. 3번이다.","c":"중","v":1},"관세사2023_40-08":{"w":"ㄱ O: 수입신고 수리 전 보세구역 보관 물품의 외국 반출은 수출재화의 선(기)적일이 공급시기이다.\nㄴ O: 보세구역 안에서 보세구역 밖의 국내로 공급하는 것이 재화의 수입에 해당하면 수입신고 수리일이다(부가가치세법 시행령 제28조제7항).\nㄷ O: 원료를 대가 없이 국외 수탁가공 사업자에게 반출하는 경우는 외국에서 해당 재화가 인도되는 때이다.\nㄹ X: 무환으로 수출해 판매된 범위에서 대금을 결제하는 위탁판매수출은 수출재화의 공급가액이 확정되는 때가 공급시기이다(시행령 제28조제6항).\nㄱ, ㄴ, ㄷ이므로 4번이다.","c":"상","v":1},"관세사2023_40-10":{"w":"외국항행사업자가 사업에 부수해 공급하는 재화·용역 중 영세율 대상: 다른 외국항행사업자의 탑승권 판매·운송계약 체결, 항공기 안에서 승객에게 하는 공급, 자기 승객 전용 버스 탑승 용역이다. ㄱ, ㄴ, ㄷ 모두이므로 5번이다.","c":"중","v":1},"관세사2023_40-13":{"w":"국가가 공급하는 재화·용역 중 면세 범위는 민간투자법 방식으로 기부채납받고 부여하는 시설관리운영권(ㄴ)과 소속 직원 복리후생용 구내식당 용역(ㄷ)이다.\n군인에게 제공하는 골프 연습장 운영 용역(ㄱ)은 과세이다. 4번이다.","c":"중","v":1},"관세사2024_41-02":{"w":"보세구역 안에서 밖의 국내로 재화를 공급하는 경우가 재화의 수입에 해당하면 수입신고 수리일이 공급시기이다. 4번이다.\n폐업 전 공급한 재화의 공급시기가 폐업일 이후이면 폐업일이고, 반환조건부 판매는 조건이 성취되어 확정되는 때이다. 무인판매기는 현금을 꺼내는 때이고, 위탁판매수출은 공급가액이 확정되는 때이다.","c":"중","v":1},"관세사2024_41-09":{"w":"전자적 용역의 공급장소는 용역을 공급받는 자의 사업장 소재지, 주소지 또는 거소지이다. 용역을 공급하는 자의 사업장 소재지로 적은 3번이 옳지 않다.","c":"중","v":1},"관세사2024_41-11":{"w":"국내사업장이 없는 비거주자에게 국내에서 조경 관리 서비스를 제공하는 것은 영세율 대상 용역에 해당하지 않는다. 1번이다.","c":"중","v":1},"관세사2024_41-12":{"w":"도로교통법상 자동차운전학원의 교육 용역은 면세 교육 용역에 해당하지 않는다. 2번이다.","c":"중","v":1},"관세사2024_41-13":{"w":"재화의 수입 면세: 상속으로 수입하는 관세 면제 재화(ㄱ), 정부 위탁으로 정부 외의 자가 수입하는 무세 군수품(ㄴ), 외국에서 영상 관련 공익단체에 기증되는 재화(ㄷ)가 모두 면세이다. 5번이다.","c":"중","v":1},"관세사2025_42-04":{"w":"재화의 공급으로 보는 것은 주요자재 일부를 부담하고 가공해 새로운 재화를 만드는 가공계약에 따른 인도(ㄷ)이다.\n수용 대가, 경매 양도, 대가 없는 견본품 양도는 공급으로 보지 않는다. 1번이다.","c":"상","v":1},"관세사2025_42-08":{"w":"중간지급조건부 재화 공급에는 계약금 지급 다음 날부터 인도일까지 6개월 이상이고 그 사이에 계약금 외 대가를 분할해 받는 경우, 국고금관리법에 따라 경비를 미리 받는 경우, 지방회계법에 따라 선금을 받는 경우가 포함된다. ㄱ, ㄴ, ㄷ 모두이므로 5번이다.","c":"중","v":1},"관세사2025_42-09":{"w":"대금 청구시기와 지급시기 사이가 30일 이내이면 세금계산서 발급일부터 7일이 지난 후 대가를 받더라도 발급한 때가 공급시기이다. 외국항행용역은 선하증권 발행일부터 90일 이내이면 발급한 때가 공급시기이다.\nㄱ 30, ㄴ 7, ㄷ 90이고 합이 127이므로 4번이다.","c":"중","v":1},"관세사2025_42-12":{"w":"영세율 적용 대상은 국외에서 공급하는 용역(건설용역 등), 선박·항공기에 의한 국제 운송, 우리나라에 상주하는 외교공관 등에 공급하는 재화, 국내사업장이 없는 외국법인에 공급하는 컨테이너수리업 용역(대금을 외국환은행에서 원화로 수령)이다. ㄱ~ㄹ 모두이므로 5번이다.","c":"중","v":1},"관세사2025_42-14":{"w":"의사가 제공하는 비급여대상 탈모치료술은 면세되는 의료보건 용역이 아니다. 1번이다.\n안마사의 안마용역, 분뇨수집·운반용역, 산후조리원 용역, 장의용역은 면세이다.","c":"중","v":1},"관세사2026_43-05":{"w":"영세율을 적용받은 재화(내국신용장에 의해 공급받은 재화)를 자기의 면세사업을 위해 직접 사용하면 재화의 공급으로 보아 과세한다. 3번이다.\n사업자 단위 과세 사업자의 다른 사업장 반출, 신탁재산의 위탁자 이전, 작업복 제공, 사업용 자산 물납은 재화의 공급으로 보지 않는다.","c":"상","v":1},"관세사2026_43-07":{"w":"건설자재 일부 또는 전부를 부담하는 건설업(ㄱ), 주요자재 없이 인도받은 재화를 단순히 가공만 해 주는 것(ㄴ), 산업상·상업상·과학상 지식·경험·숙련에 관한 정보 제공(ㄷ)은 모두 용역의 공급이다. 5번이다.","c":"상","v":1},"관세사2026_43-09":{"w":"ㄱ O: 현금판매와 외상판매는 재화가 인도되거나 이용가능하게 되는 때가 공급시기이다.\nㄴ O: 상품권을 판매한 뒤 현물과 교환되면 재화가 실제로 인도되는 때가 공급시기이다.\nㄷ X: 무환으로 수출해 판매된 범위에서 대금을 결제하는 위탁판매수출은 수출재화의 공급가액이 확정되는 때가 공급시기이다(부가가치세법 시행령 제28조제6항).\nㄱ, ㄴ이므로 2번이다.","c":"상","v":1},"관세사2017_34-13":{"w":"매출세액 계산(원 단위):\n국내매출액 146,000,000원 × 10% = 14,600,000원 (매출할인은 이미 차감)\n종업원 장기근속기념품 시가 1,300,000원 × 10% = 130,000원\n거래처 판매장려물품 시가 2,600,000원 × 10% = 260,000원\n대표이사 가사용 소비재화 시가 2,000,000원 × 10% = 200,000원\n대손세액 990,000원 × 10/110 = 90,000원 차감\n합계 14,600,000 + 130,000 + 260,000 + 200,000 − 90,000 = 15,100,000원이므로 3번이다.","c":"상","v":1},"관세사2017_34-16":{"w":"공급시기가 속하는 과세기간이 끝난 뒤 20일 이내에 사업자등록을 신청하면, 등록신청일부터 공급시기가 속하는 과세기간 기산일까지 역산한 기간 안의 매입세액은 공제된다. 2번이다.\n기업업무추진비 관련, 사업과 직접 관련 없는 지출, 면세사업 투자, 토지 취득·형질변경에 관련된 매입세액은 공제되지 않는다.","c":"중","v":1},"관세사2017_34-17":{"w":"면세사업용 재화를 과세사업에 전용하면 매입세액 × (1 − 감가율 × 경과된 과세기간 수) × 과세전용 시 과세공급가액 비율만큼 공제한다.\n2017년 제1기 과세공급가액 비율은 3억 / 4억 = 75%이다.\n건물: 5,000,000 × (1 − 5% × 3) = 4,250,000원 (2015년 제2기 취득, 3기 경과)\n기계장치: 3,000,000 × (1 − 25% × 1) = 2,250,000원 (2016년 제2기 취득, 1기 경과)\n(4,250,000 + 2,250,000) × 75% = 4,875,000원이므로 4번이다.","c":"상","v":1},"관세사2017_34-19":{"w":"예정신고기간의 과세표준:\n매출액 50,000,000원 + 수출액 30,000,000원(영세율도 과세표준에 포함) + 대표이사 개인 주택 수리비 사용 재화의 시가 6,000,000원 = 86,000,000원.\n기계장치 양도는 계약금 지급일 다음 날부터 인도일까지 6개월 이상이고 그 사이 대가를 분할 수령하는 중간지급조건부이므로 대가의 각 부분을 받기로 한 때가 공급시기이다. 계약금 5,000,000원과 중도금 20,000,000원이 1기 예정기간에 들어간다.\n합계 86,000,000 + 25,000,000 = 111,000,000원이므로 3번이다.","c":"상","v":1},"관세사2017_34-33":{"w":"관할 세무서장이 부가가치세를 조사해 결정·경정하는 사유는 신고 내용의 오류·누락(ㄱ), 확정신고 때 세금계산서합계표 미제출(ㄴ), 합계표의 기재사항 누락·불일치(ㄷ), 사업장 이동이 빈번해 포탈 우려가 있는 경우(ㄹ)이다. 모두 해당하여 5번이다.","c":"중","v":1},"관세사2017_34-37":{"w":"장기할부판매의 이자상당액은 과세표준에 포함된다.\n지체된 대가에 대한 연체이자, 도달 전 파손·멸실 재화의 가액, 약정기일 전 대가 수령으로 할인해 준 금액, 환입된 재화의 가액은 과세표준에 포함하지 않는다. 3번이다.","c":"중","v":1},"관세사2017_34-38":{"w":"간이과세자 납부세액 = 공급대가 × 업종별 부가가치율 × 10%이다.\n부동산임대업 30,000,000 × 30% × 10% = 900,000원\n소매업 10,000,000 × 10% × 10% = 100,000원\n공통사용재화 5,000,000원은 업종별 공급대가 비율(75% : 25%)로 안분한다.\n임대업분 3,750,000 × 30% × 10% = 112,500원, 소매업분 1,250,000 × 10% × 10% = 12,500원\n합계 900,000 + 100,000 + 112,500 + 12,500 = 1,125,000원이므로 4번이다.","c":"상","v":1},"관세사2018_35-14":{"w":"공급가액에 포함하지 않는 것은 도달 전에 파손·훼손·멸실한 재화의 가액(ㄴ), 대가를 약정기일 전에 받았다는 이유로 할인해 준 금액(ㄹ), 통상의 대가에서 직접 깎아 주는 금액(ㅁ)이다.\n공급받는 자에게 지급하는 장려금(ㄱ)과 공급과 직접 관련된 국고보조금·공공보조금(ㄷ)은 공급가액에 포함된다. 5번이다.","c":"중","v":1},"관세사2018_35-16":{"w":"기업업무추진비 및 이와 유사한 비용의 지출에 관련된 매입세액은 매출세액에서 공제할 수 없다. 3번이다.\n나머지는 등록 전 매입으로 주민등록번호 기재, 공급시기 이후 확정신고기한까지 발급, 전자 외 세금계산서의 기한 내 발급, 미전송 전자세금계산서로서 발급 사실이 확인되는 경우여서 공제된다.","c":"상","v":1},"관세사2018_35-18":{"w":"사업자등록을 과세기간이 끝난 뒤 20일 이내에 신청하면 공급시기가 속하는 과세기간 기산일까지 역산한 기간의 매입세액도 공제된다. 5월분 매입세액도 공제 대상이다.\n매출세액 90,000,000 × 10% = 9,000,000원, 매입세액 7,000,000원\n납부세액 9,000,000 − 7,000,000 = 2,000,000원이므로 2번이다.","c":"중","v":1},"관세사2018_35-20":{"w":"보세구역 안에서 수입재화를 가공해 보세구역 밖의 국내사업자에게 공급하면, 공급가액에서 수입 시의 과세표준(관세 과세가격 + 관세 + 개별소비세 + 교육세 등)을 뺀 금액이 과세표준이다.\n수입 시 과세표준 5,000,000 + 300,000 + 150,000 + 50,000 = 5,500,000원\n10,000,000 − 5,500,000 = 4,500,000원이므로 2번이다.","c":"상","v":1},"관세사2018_35-21":{"w":"공통매입세액 재계산: 가산·공제세액 = 총공통매입세액 × (1 − 25% × 경과된 과세기간 수) × 증감된 면세공급가액 비율이다. 총공통매입세액은 5,000,000원이다.\n2017년 제1기 면세비율 240/600 = 40%, 제2기 350/700 = 50%(+10%p, 재계산 375,000원 가산), 2018년 제1기 324/900 = 36%이다.\n2018년 제1기는 직전 재계산 비율 50% 대비 −14%p이고 경과된 과세기간 수는 2이다.\n5,000,000 × (1 − 25% × 2) × (−14%) = −350,000원이므로 납부세액에서 350,000원을 공제한다. 2번이다.","c":"중","v":1},"관세사2018_35-23":{"w":"(2021 개정 전 기준) 출제 당시 재고매입세액은 취득가액 × 10/110 × (1 − 업종별 부가가치율)로 계산했고, 건물은 경과된 과세기간 1기마다 5%씩 줄였다. 감가상각자산은 취득한 해의 부가가치율, 재고품은 변경 직전 과세기간의 부가가치율을 쓴다.\n상품: 22,000,000 × 10/110 × (1 − 25%) = 1,500,000원\n건물: 550,000,000 × 10/110 × (1 − 5% × 4) × (1 − 20%) = 32,000,000원 (2016년 제1기 취득, 2016년 제1기~2017년 제2기 4기 경과)\n합계 33,500,000원으로 5번이다.\n2021년 7월부터는 부가가치율 대신 0.5% × 110/10을 빼는 방식으로 바뀌어(부가가치세법 시행령 제86조제3항) 현행법으로는 금액이 달라진다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 재고매입세액은 취득가액 × 10/110 × (1 − 업종별 부가가치율)로 계산했고, 건물은 경과된 과세기간 1기마다 5%씩 줄였다. 감가상각자산은 취득한 해의 부가가치율, 재고품은 변경 직전 과세기간의 부가가치율을 쓴다.\n상품: 22,000,000 × 10/110 × (1 − 25%) = 1,500,000원\n건물: 550,000,000 × 10/110 × (1 − 5% × 4) × (1 − 20%) = 32,000,000원 (2016년 제1기 취득, 2016년 제1기~2017년 제2기 4기 경과)\n합계 33,500,000원으로 5번이다.\n2021년 7월부터는 부가가치율 대신 0.5% × 110/10을 빼는 방식으로 바뀌어(부가가치세법 시행령 제86조제3항) 현행법으로는 금액이 달라진다."},"관세사2018_35-26":{"w":"전자세금계산서 발급명세를 전송기한이 지난 뒤 과세기간 말의 다음 달 11일까지 전송하는 경우의 가산세율은 공급가액의 1천분의 3으로, 선지 중 가장 낮다. 1번이다.\n세금계산서를 발급받거나 발급한 사실과 다르게 처리한 나머지 선지의 가산세율은 이보다 높다.","c":"중","v":1},"관세사2018_35-30":{"w":"공급받은 사업자의 가산세는 세금계산서합계표의 공급가액을 사실과 다르게 과다하게 적은 경우(ㄴ)와 경정 시 세금계산서를 경정기관에 제출해 매입세액을 공제받는 경우(ㄷ)에 부과된다.\n수정신고서와 함께 제출하는 경우(ㄱ)와 예정신고 때 못 낸 합계표를 확정신고 때 제출하는 경우(ㄹ)는 가산세 대상이 아니다. 3번이다.","c":"중","v":1},"관세사2019_36-12":{"w":"외상으로 공급한 재화의 대가 일부로 받은 운송비는 과세표준에 포함된다. 3번이다.\n도달 전 파손 재화, 약정기일 전 대가 수령에 따른 할인액, 공급과 관련 없는 국고보조금, 환입된 재화의 가액은 과세표준에 포함하지 않는다.","c":"중","v":1},"관세사2019_36-15":{"w":"보세구역 안의 수입재화를 국내사업자에게 공급하면 공급가액에서 수입 시 과세표준을 뺀 금액이 과세표준이다.\n공급대가 7,150,000 ÷ 1.1 = 6,500,000원, 수입 시 과세표준 5,000,000원\n6,500,000 − 5,000,000 = 1,500,000원이므로 1번이다.","c":"상","v":1},"관세사2019_36-16":{"w":"(2022 개정 전 기준) 출제 당시 법인사업자의 의제매입세액 한도는 면세농산물 관련 과세표준의 40%였다.\n한도 205,000,000 × 40% = 82,000,000원으로 수입 농산물 가액 100,000,000원(관세의 과세가격)보다 작다.\n82,000,000 × 2/102 = 1,607,843원으로 2번이다.\n현행 시행령 제84조제2항 단서는 2027년 12월 31일까지 법인 한도를 50%로 두므로 한도가 102,500,000원이 되어 100,000,000 × 2/102 = 1,960,784원(4번)이 답이 된다.","c":"상","v":1,"old":1,"ow":"(2022 개정 전 기준) 출제 당시 법인사업자의 의제매입세액 한도는 면세농산물 관련 과세표준의 40%였다.\n한도 205,000,000 × 40% = 82,000,000원으로 수입 농산물 가액 100,000,000원(관세의 과세가격)보다 작다.\n82,000,000 × 2/102 = 1,607,843원으로 2번이다.\n현행 시행령 제84조제2항 단서는 2027년 12월 31일까지 법인 한도를 50%로 두므로 한도가 102,500,000원이 되어 100,000,000 × 2/102 = 1,960,784원(4번)이 답이 된다."},"관세사2019_36-18":{"w":"매출세액 = 과세표준 × 10%이다. 수출액은 영세율이라 세액이 0이고, 할부판매 이자상당액은 과세표준에 포함하며, 연체이자는 포함하지 않는다.\n과세표준 200,000,000 + 20,000,000 = 220,000,000원\n220,000,000 × 10% = 22,000,000원이므로 2번이다.","c":"상","v":1},"관세사2019_36-19":{"w":"ㄱ~ㄹ 모두 옳다. 면세사업 투자 관련 매입세액은 불공제이고, 공급시기 후 확정신고기한까지 발급받은 세금계산서는 공제되며, 겸영 시 실지귀속이 원칙이고, 미전송이어도 발급 사실이 확인되면 공제된다. 5번이다.","c":"중","v":1},"관세사2019_36-20":{"w":"특수관계인에게 용역을 낮은 대가로 공급하면 시가를 과세표준으로 본다. 특허권A는 시가 3,000,000원이 과세표준이다.\n특허권B의 무상 대여는 특수관계인에게 무상으로 제공하는 용역 중 부동산 임대용역만 공급으로 보므로 과세표준에 들어가지 않는다.\n과세표준 3,000,000원이므로 3번이다.","c":"중","v":1},"관세사2019_36-21":{"w":"결정·경정 사유는 신고 내용의 오류·누락, 신고 불이행, 합계표 미제출, 휴업·폐업 상태에서 포탈 우려 등이다.\n확정신고를 하였으나 납부세액을 기한까지 납부하지 않은 경우는 결정·경정이 아니라 징수의 문제이다. 1번이다.","c":"중","v":1},"관세사2019_36-27":{"w":"(2021 개정 전 기준) 출제 당시 재고납부세액은 재고금액 × 10/100 × (1 − 업종별 부가가치율)이었고, 감가상각자산은 취득가액에 (1 − 감가율 × 경과된 과세기간 수)를 곱했다. 장부금액은 쓰지 않는다.\n원재료 5,000,000원\n기계장치 10,000,000 × (1 − 25% × 2) = 5,000,000원 (2018년 제2기 취득, 2018년 제2기·2019년 제1기 경과)\n건물 100,000,000 × (1 − 5% × 4) = 80,000,000원 (2017년 제2기 취득, 4기 경과)\n90,000,000 × 10% × (1 − 20%) = 7,200,000원으로 5번이다.\n2021년 7월부터는 (1 − 부가가치율) 대신 (1 − 0.5% × 110/10)을 곱하므로(부가가치세법 시행령 제112조제3항) 현행법으로는 금액이 달라진다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 재고납부세액은 재고금액 × 10/100 × (1 − 업종별 부가가치율)이었고, 감가상각자산은 취득가액에 (1 − 감가율 × 경과된 과세기간 수)를 곱했다. 장부금액은 쓰지 않는다.\n원재료 5,000,000원\n기계장치 10,000,000 × (1 − 25% × 2) = 5,000,000원 (2018년 제2기 취득, 2018년 제2기·2019년 제1기 경과)\n건물 100,000,000 × (1 − 5% × 4) = 80,000,000원 (2017년 제2기 취득, 4기 경과)\n90,000,000 × 10% × (1 − 20%) = 7,200,000원으로 5번이다.\n2021년 7월부터는 (1 − 부가가치율) 대신 (1 − 0.5% × 110/10)을 곱하므로(부가가치세법 시행령 제112조제3항) 현행법으로는 금액이 달라진다."},"관세사2019_36-29":{"w":"현금매출명세서 제출 대상 업종은 부동산중개업, 예식장업, 병원·의원, 통관업 등이다. 부동산임대업은 현금매출명세서가 아니라 부동산임대공급가액명세서를 제출한다. 2번이다.","c":"중","v":1},"관세사2020_37-10":{"w":"(2020 개정 전 기준) 확정신고 대상은 4월~6월 거래이고 3월 15일 거래는 예정신고 몫이다(축산물은 어차피 면세).\n5월 3일: 출제 당시에는 경조사 관련 재화만 공급에서 빠졌으므로 사용인 생일선물은 개인적 공급으로 시가 200,000원이 과세표준이다.\n5월 24일: 김치는 미가공식료품에 포함되어 면세이다.\n5월 31일: 자기적립마일리지로 결제받은 300,000원은 공급가액에서 빼므로 현금 700,000원이 과세표준이다.\n200,000 + 700,000 = 900,000원으로 3번이다.\n2020년 10월 개정 뒤 생일 관련 재화는 사용인 1명당 연간 10만원까지 공급으로 보지 않으므로(시행령 제19조의2제3호) 현행법으로는 초과분 100,000원만 과세되어 800,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2020 개정 전 기준) 확정신고 대상은 4월~6월 거래이고 3월 15일 거래는 예정신고 몫이다(축산물은 어차피 면세).\n5월 3일: 출제 당시에는 경조사 관련 재화만 공급에서 빠졌으므로 사용인 생일선물은 개인적 공급으로 시가 200,000원이 과세표준이다.\n5월 24일: 김치는 미가공식료품에 포함되어 면세이다.\n5월 31일: 자기적립마일리지로 결제받은 300,000원은 공급가액에서 빼므로 현금 700,000원이 과세표준이다.\n200,000 + 700,000 = 900,000원으로 3번이다.\n2020년 10월 개정 뒤 생일 관련 재화는 사용인 1명당 연간 10만원까지 공급으로 보지 않으므로(시행령 제19조의2제3호) 현행법으로는 초과분 100,000원만 과세되어 800,000원이 된다."},"관세사2020_37-13":{"w":"면세 전용 공급가액 = 취득가액 × (1 − 25% × 경과된 과세기간 수)이다. 2019년 제1기에 취득했고 경과된 과세기간 수는 2이므로 20,000,000 × (1 − 25% × 2) = 10,000,000원이다.\n공통사용이므로 면세공급가액 비율을 곱한다. 100,000,000 / (100,000,000 + 300,000,000) = 25%\n10,000,000 × 25% = 2,500,000원이므로 1번이다.","c":"상","v":1},"관세사2020_37-14":{"w":"(2024 개정 전 기준) 토지와 건물을 함께 공급할 때 실지거래가액 구분이 안분계산 금액과 100분의 30 이상 차이 나면 안분계산 금액을 공급가액으로 한다(30).\n출제 당시 전자세금계산서 의무발급 개인사업자는 공급가액 합계가 3억원 이상인 해의 다음 해 제2기부터 발급했다(3).\n면세공급가액이 5퍼센트 미만이면 공통매입세액(500만원 이상인 경우 제외)을 안분하지 않고 공제한다(5).\n대손세액 공제는 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고 기한까지 확정된 대손에 적용한다(10).\n30 + 3 + 5 + 10 = 48로 3번이다.\n현행 기준은 공급가액 합계 8천만원 이상(부가가치세법 시행령 제68조)이어서 둘째 빈칸이 억원 단위로 맞지 않는다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 토지와 건물을 함께 공급할 때 실지거래가액 구분이 안분계산 금액과 100분의 30 이상 차이 나면 안분계산 금액을 공급가액으로 한다(30).\n출제 당시 전자세금계산서 의무발급 개인사업자는 공급가액 합계가 3억원 이상인 해의 다음 해 제2기부터 발급했다(3).\n면세공급가액이 5퍼센트 미만이면 공통매입세액(500만원 이상인 경우 제외)을 안분하지 않고 공제한다(5).\n대손세액 공제는 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고 기한까지 확정된 대손에 적용한다(10).\n30 + 3 + 5 + 10 = 48로 3번이다.\n현행 기준은 공급가액 합계 8천만원 이상(부가가치세법 시행령 제68조)이어서 둘째 빈칸이 억원 단위로 맞지 않는다."},"관세사2020_37-15":{"w":"감가상각자산의 공통매입세액은 안분계산 후 안분기준 비율과 취득 과세기간(또는 재계산한 과세기간)의 비율이 5퍼센트 이상 차이 나면 다시 계산하고 해당 과세기간의 확정신고와 함께 신고·납부한다. 1번이다.","c":"상","v":1},"관세사2020_37-16":{"w":"면세농산물 의제매입세액 공제율은 102분의 2, 104분의 4, 106분의 6, 109분의 9 등이다. 103분의 3은 없다. 2번이다.","c":"중","v":1},"관세사2020_37-17":{"w":"과세표준 계산:\n판매 매출액 500,000,000원에서 연체이자 20,000,000원과 자기적립마일리지 결제분 10,000,000원을 뺀다. → 470,000,000원\n특수관계인에게 부당하게 낮은 가격으로 판 50,000,000원은 시가 100,000,000원으로 본다. → +50,000,000원 = 520,000,000원\n특수관계인에게 복사기(동산) 임대용역을 무상 제공한 것은 공급으로 보지 않는다.\n토지·건물·구축물 일괄 공급 180,000,000원은 토지분을 뺀 건물·구축물 부분만 과세한다. 기준시가가 없는 구축물은 장부가액 비율로 먼저 안분한다. 구축물 180,000,000 × 12,500,000 / 150,000,000 = 15,000,000원\n나머지 165,000,000원을 토지·건물 기준시가(70 : 40)로 나누면 건물분은 165,000,000 × 40/110 = 60,000,000원이다. 건물·구축물 합계 75,000,000원\n520,000,000 + 75,000,000 = 595,000,000원이므로 2번이다.","c":"중","v":1},"관세사2020_37-20":{"w":"수정세금계산서 발급 사유는 환입, 계약 해제, 공급가액 증감, 내국신용장 사후 개설, 기재사항 착오와 착오 외 사유 정정, 이중 발급, 발급 대상 아닌 거래에 발급, 세율 오적용이다. 9개 모두 해당하여 5번이다.","c":"중","v":1},"관세사2020_37-21":{"w":"과세 관련 매입세액 6,000,000원은 공제한다. 면세 관련 4,000,000원은 공제하지 않고, 토지 철거비 600,000원도 공제하지 않는다.\n공통매입세액 2,400,000원 중 해당 과세기간에 취득해 처분한 기계장치분 800,000원은 직전 과세기간 비율, 나머지 1,600,000원은 당기 비율로 안분한다.\n직전 과세기간 과세비율 80 / 200 = 40%이므로 800,000 × 40% = 320,000원\n당기 과세비율 120 / 200 = 60%이므로 1,600,000 × 60% = 960,000원\n공제 매입세액 6,000,000 + 320,000 + 960,000 = 7,280,000원이므로 2번이다.","c":"상","v":1},"관세사2020_37-23":{"w":"확정신고 때 제출하는 서류는 신용카드매출전표등 발행금액 집계표, 영세율 매출명세서, 건물 등 감가상각자산 취득명세서, 공제받지 못할 매입세액 명세서 등이다.\n기업업무추진비는 매입세액 불공제 대상이어서 신용카드매출전표등 수령명세서를 제출하지 않는다. 4번이다.","c":"중","v":1},"관세사2020_37-26":{"w":"사업자등록 신청 기한 내에 등록하지 않으면 사업 개시일부터 등록을 신청한 날의 직전일까지의 공급가액 합계액의 1퍼센트가 가산세이다. 「신청한 날이 속하는 과세기간의 종료일까지」라고 적은 1번이 틀렸다.","c":"중","v":1},"관세사2020_37-28":{"w":"간이과세를 적용받을 수 있는 사업은 용달 및 개별 화물자동차운송업이다. 통관업, 측량사업, 심판변론인업, 부동산매매업은 간이과세 배제 업종이다. 1번이다.","c":"중","v":1},"관세사2020_37-29":{"w":"(2021 개정 전 기준) 출제 당시 간이과세자 납부세액은 공급대가 × 업종별 부가가치율 × 10%이고, 세금계산서 매입세액은 매입세액 × 부가가치율만큼 공제했다.\n납부세액: 과세 공급대가 30,000,000원(현금 20,000,000 + 카드 10,000,000) × 10% × 10% = 300,000원. 수출 10,000,000원은 영세율이라 세액이 없다.\n매입세액공제: 1,000,000 × 10% = 100,000원\n신용카드매출전표 발행세액공제: 10,000,000 × 1.3% = 130,000원\n300,000 − 100,000 − 130,000 = 70,000원을 납부하므로 4번이다.\n현행법은 매입세액공제를 매입 공급대가 × 0.5%로 계산하고 소매업 부가가치율도 15%여서 금액이 달라진다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 간이과세자 납부세액은 공급대가 × 업종별 부가가치율 × 10%이고, 세금계산서 매입세액은 매입세액 × 부가가치율만큼 공제했다.\n납부세액: 과세 공급대가 30,000,000원(현금 20,000,000 + 카드 10,000,000) × 10% × 10% = 300,000원. 수출 10,000,000원은 영세율이라 세액이 없다.\n매입세액공제: 1,000,000 × 10% = 100,000원\n신용카드매출전표 발행세액공제: 10,000,000 × 1.3% = 130,000원\n300,000 − 100,000 − 130,000 = 70,000원을 납부하므로 4번이다.\n현행법은 매입세액공제를 매입 공급대가 × 0.5%로 계산하고 소매업 부가가치율도 15%여서 금액이 달라진다."},"관세사2022_39-15":{"w":"비품은 기준시가가 없어 장부가액 비율로 안분한다. 104,220,000 × 14,850,000 / 86,850,000 = 17,820,000원이 비품분이다.\n토지와 건물의 합계는 104,220,000 − 17,820,000 = 86,400,000원이고, 건물분이 52,800,000원이므로 건물 비율은 52,800,000 / 86,400,000이다.\n기준시가 합계 54,000,000원 × (52,800,000 / 86,400,000) = 33,000,000원이 건물의 기준시가(B)이다. 1번이다.","c":"중","v":1},"관세사2022_39-18":{"w":"영수증 발급 대상 일반과세자라도 공급받는 자가 사업자등록증을 제시하고 요구하면 세금계산서를 발급해야 하는 업종은 소매업, 숙박업, 양복점업, 도정업 등이다. 전세버스가 아닌 여객운송업은 해당하지 않는다. 1번이다.","c":"하","v":1},"관세사2022_39-21":{"w":"과세매출 225,000,000원 × 10% = 22,500,000원\n공통사용 지게차 매각 7,500,000원은 직전 과세기간의 과세공급가액 비율로 과세표준을 계산한다. 123,750,000 / (123,750,000 + 101,250,000) = 55%\n7,500,000 × 55% = 4,125,000원, 세액 412,500원\n매출세액 22,500,000 + 412,500 = 22,912,500원이므로 5번이다.","c":"상","v":1},"관세사2022_39-22":{"w":"신용카드 등 사용에 대한 세액공제 대상은 신용카드매출전표, 현금영수증, 직불카드영수증, 직불전자지급수단 영수증이다. 실제 명의가 확인되지 않는 선불카드영수증은 해당하지 않는다. 5번이다.","c":"중","v":1},"관세사2022_39-23":{"w":"ㄱ X: 예정신고는 예정신고기간이 끝난 후 25일 이내에 한다.\nㄴ O: 예정신고서를 낼 때 건물 등 감가상각자산 취득명세서를 함께 제출한다.\nㄷ O: 재화 수입에 대한 부가가치세 납부유예의 유예기간은 1년이다.\nㄹ X: 주사업장 총괄 납부 신청서는 납부하려는 과세기간 개시 20일 전에 제출한다.\nㄴ, ㄷ이므로 2번이다.","c":"하","v":1},"관세사2022_39-24":{"w":"세무서장은 납세보전을 위해 장부 제출을 요구할 수 있고(ㄱ), 국세청장은 조사를 위해 현금영수증 발급장치의 설치·사용을 명할 수 있으며(ㄴ), 제75조 자료제출의무자는 매 분기 말일의 다음 달 15일까지 명세를 제출한다(ㄷ). 모두 옳아 5번이다.","c":"중","v":1},"관세사2022_39-26":{"w":"추계 기준은 원단위 투입량, 비용관계비율, 상품회전율, 부가가치율 등이다. 당기순이익률은 열거된 기준이 아니다. 4번이다.","c":"중","v":1},"관세사2022_39-27":{"w":"사업 개시일부터 20일 이내에 사업자등록을 신청하지 않으면 사업 개시일부터 등록을 신청한 날의 직전일까지의 공급가액 합계액의 1퍼센트를 가산세로 한다. 3번이다.","c":"중","v":1},"관세사2022_39-28":{"w":"출제 당시 일반과세자가 간이과세자로 전환될 때 재고품의 재고납부세액은 재고금액 × 10/100 × (1 − 0.5% × 110/10)이다.\n400,000,000 × 10% × (1 − 5.5%) = 37,800,000원이므로 1번이다.","c":"상","v":1},"관세사2023_40-09":{"w":"(2024 개정 전 기준) 거래처별 1역월 공급가액을 합해 말일자로 발급하는 세금계산서는 다음 달 10일까지 발급할 수 있다(10).\n공급시기 전에 세금계산서를 발급하고 발급일부터 7일 이내에 대가를 받으면 발급한 때가 공급시기이다(7).\n출제 당시 매입자발행세금계산서의 거래사실 확인 신청은 공급시기가 속하는 과세기간 종료일부터 6개월 이내였다(6).\n10 + 7 + 6 = 23으로 4번이다.\n2024년 2월 개정으로 신청기한이 1년이 되어(부가가치세법 시행령 제71조의2제3항) 현행법으로는 합이 28이 되고 맞는 선지가 없다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 거래처별 1역월 공급가액을 합해 말일자로 발급하는 세금계산서는 다음 달 10일까지 발급할 수 있다(10).\n공급시기 전에 세금계산서를 발급하고 발급일부터 7일 이내에 대가를 받으면 발급한 때가 공급시기이다(7).\n출제 당시 매입자발행세금계산서의 거래사실 확인 신청은 공급시기가 속하는 과세기간 종료일부터 6개월 이내였다(6).\n10 + 7 + 6 = 23으로 4번이다.\n2024년 2월 개정으로 신청기한이 1년이 되어(부가가치세법 시행령 제71조의2제3항) 현행법으로는 합이 28이 되고 맞는 선지가 없다."},"관세사2023_40-15":{"w":"국고보조금·공공보조금 중 재화의 공급과 직접 관련되어 받은 것은 공급가액에 포함한다(ㄴ).\n약정기일 전 대가 수령에 따른 할인액(ㄱ), 반환 조건으로 공제한 용기대금·포장비용(ㄷ), 도달 전 파손 재화의 가액(ㄹ)은 공급가액에 포함하지 않는다. 2번이다.","c":"상","v":1},"관세사2023_40-16":{"w":"특수관계인에게 광고용역을 무상 제공한 것은 부동산 임대용역이 아니므로 과세표준에 넣지 않는다.\n토지·건물 일괄 공급 240,000,000원은 감정가가 없으므로 기준시가 비율로 안분한다. 건물 기준시가 비율 60,000,000 / 150,000,000 = 40%\n건물 공급가액 240,000,000 × 40% = 96,000,000원이므로 2번이다.","c":"상","v":1},"관세사2023_40-17":{"w":"과세표준은 국내 매출 200,000,000원 + 직수출 50,000,000원 + 구매확인서 공급 100,000,000원 = 350,000,000원이다. 직수출과 구매확인서 공급은 영세율이라 세액이 없고, 세액은 국내 매출분만 계산한다.\n매출세액 200,000,000 × 10% = 20,000,000원\n공제 매입세액 18,000,000 − 토지 형질변경 관련 1,000,000 = 17,000,000원\n납부세액 20,000,000 − 17,000,000 = 3,000,000원이므로 1번이다.","c":"상","v":1},"관세사2023_40-18":{"w":"폐업 시 잔존재화의 과세표준은 원재료는 시가, 감가상각자산은 취득가액 × (1 − 감가율 × 경과된 과세기간 수), 토지는 면세이므로 제외한다.\n원재료 시가 4,000,000원\n건물: 취득세를 뺀 취득가액 10,000,000원 × (1 − 5% × 3) = 8,500,000원 (2021년 제2기 취득, 경과 3기)\n합계 4,000,000 + 8,500,000 = 12,500,000원이므로 3번이다.","c":"상","v":1},"관세사2023_40-19":{"w":"처음 세금계산서의 작성일을 쓰는 수정세금계산서 발급 사유는 내국신용장이 사후에 개설된 경우(ㄹ)이다. 환입, 계약 해제, 공급가액 차감은 각각 환입일, 계약해제일, 증감 발생일을 작성일로 쓴다. 2번이다.","c":"중","v":1},"관세사2023_40-20":{"w":"구매확인서에 따라 영세율이 적용되는 재화의 공급은 세금계산서를 발급해야 한다(ㄷ). 한국국제협력단에 공급하는 재화는 영세율이지만 세금계산서 발급의무 면제가 아니고(ㄱ), 주사업장총괄납부 사업자가 판매 목적으로 타 사업장에 반출하는 경우는 재화 공급으로 보지 않는다(ㄴ). 3번이다.","c":"중","v":1},"관세사2023_40-21":{"w":"실질귀속을 구분할 수 없는 공통매입세액 3,000,000원은 해당 과세기간 공급가액 비율로 안분한다. 과세 비율 300,000,000 / 400,000,000 = 75%\n공제액 3,000,000 × 75% = 2,250,000원, 불공제액 750,000원\n매입세액 공제액 20,000,000 − 750,000 = 19,250,000원이므로 5번이다.","c":"상","v":1},"관세사2023_40-22":{"w":"의제매입세액 공제 대상 매입가액은 국내 구입액 104,000,000원과 수입 과일의 관세 과세가격 48,000,000원(관세 2,400,000원은 제외)이다. 합계 152,000,000원이 한도 360,000,000 × 50% = 180,000,000원 이내이다.\n152,000,000 × 4/104 = 5,846,153원이므로 5번이다.","c":"상","v":1},"관세사2023_40-23":{"w":"현금매출명세서 제출 대상 사업은 예식장업, 부동산중개업, 병원·의원, 통관업을 포함한다. ㄱ~ㄹ 모두 해당하여 5번이다.","c":"중","v":1},"관세사2023_40-24":{"w":"매입처별 세금계산서합계표를 과세기간 종료 후 25일 이내에 제출해야 하는 자는 국가, 지방자치단체조합, 각급학교 기성회, 특별법에 따라 설립된 법인 등 사업자등록 없이 세금계산서를 받는 자이다. ㄱ~ㄹ 모두 해당하여 5번이다.","c":"하","v":1},"관세사2023_40-27":{"w":"재화를 공급하지 않고 세금계산서를 발급하면 공급가액의 3퍼센트, 공급받는 자가 아닌 자의 명의로 발급하면 2퍼센트, 공급하는 자가 아닌 자의 명의로 발급받으면 2퍼센트이다. ㄱ 3, ㄴ 2, ㄷ 2로 3번이다.","c":"중","v":1},"관세사2023_40-29":{"w":"납세보전·조사를 위한 장부·서류 제출 명령을 위반한 자에게는 2천만원 이하의 과태료를 부과한다. 2번이다.","c":"중","v":1},"관세사2023_40-30":{"w":"부가가치세 납부세액에서 감면·공제세액을 빼고 가산세를 더한 세액의 1천분의 747을 부가가치세로, 나머지를 지방소비세로 한다. 2번이다.","c":"중","v":1},"관세사2024_41-15":{"w":"재화의 공급과 직접 관련되어 받은 국고보조금·공공보조금은 공급가액에 포함한다. 2번이다.\n연체이자, 도달 전에 멸실한 재화의 가액, 거래징수한 부가가치세, 자기적립마일리지로 전부 결제받은 금액은 공급가액에 포함하지 않는다.","c":"중","v":1},"관세사2024_41-16":{"w":"재화의 수입에 대한 부가가치세 과세표준은 관세의 과세가격 + 관세 + 개별소비세 + 주세 + 교육세 + 농어촌특별세 + 교통·에너지·환경세이다.\n3,000,000 + 600,000 + 500,000 + 150,000 + 50,000 = 4,300,000원이므로 5번이다.","c":"상","v":1},"관세사2024_41-17":{"w":"영세율 과세표준은 외화 대금을 공급시기(선적일) 이전에 원화로 환가했으면 환가액, 이후에 받았으면 선적일의 기준환율로 환산한 금액이다.\n수출: 선적일(2월 20일) 전에 환가한 선수금 50,000달러는 환가액 66,000,000원, 선적 후 받은 250,000달러는 250,000 × 1,350 = 337,500,000원이다.\n외국법인이 지정한 국내 다른 사업자에게 인도하고 그대로 반출되는 공급은 영세율 대상이며 대금 50,000,000원이다.\n66,000,000 + 337,500,000 + 50,000,000 = 453,500,000원이므로 4번이다.","c":"중","v":1},"관세사2024_41-19":{"w":"ㄱ X: 세율 오적용은 과세자료해명안내 통지를 받은 뒤에는 수정세금계산서를 발급할 수 없다.\nㄴ O: 면세 등 발급대상이 아닌 거래에 발급한 세금계산서는 수정할 수 있다.\nㄷ O: 처음 공급한 재화가 환입된 경우 수정세금계산서를 발급한다.\nㄴ, ㄷ이므로 4번이다.","c":"중","v":1},"관세사2024_41-20":{"w":"매입자발행세금계산서는 공급자가 부도·폐업한 경우, 계약의 해제·변경으로 수정세금계산서를 발급하지 않은 경우, 공급자가 소재불명·연락두절인 경우, 휴업 등으로 발급받기 곤란하다고 국세청장이 인정하는 경우에 발급할 수 있다. ㄱ~ㄹ 모두 해당하여 5번이다.","c":"하","v":1},"관세사2024_41-21":{"w":"ㄱ X: 대손세액공제는 부가가치세가 과세되는 재화·용역의 공급과 관련된 대손이다.\nㄴ O: 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고 기한까지 확정되는 대손세액이다.\nㄷ O: 대손세액은 대손금액(부가가치세 포함) × 10/110이다.\nㄹ X: 대손세액공제는 확정신고 때만 적용한다.\nㄴ, ㄷ이므로 2번이다.","c":"중","v":1},"관세사2024_41-23":{"w":"면세사업에만 쓰던 재화를 과세·면세 공통으로 쓰면 매입세액 × (1 − 감가율 × 경과된 과세기간 수) × 과세공급가액 비율만큼 공제한다. 2024년 제2기 과세 비율은 10억 / 16억 = 62.5%이다.\n기계장치 매입세액 44,000,000 × 10/110 = 4,000,000원, 2023년 제2기 취득이므로 경과 2기: 4,000,000 × (1 − 25% × 2) = 2,000,000원\n공장건물 매입세액 220,000,000 × 10/110 = 20,000,000원, 2022년 제1기 취득이므로 경과 5기: 20,000,000 × (1 − 5% × 5) = 15,000,000원\n(2,000,000 + 15,000,000) × 62.5% = 10,625,000원이므로 1번이다.","c":"상","v":1},"관세사2024_41-27":{"w":"착오로 필요적 기재사항이 사실과 다른 경우 공급가액의 1퍼센트, 발급시기가 지난 뒤 확정신고기한까지 발급하는 경우 1퍼센트, 실제 공급자가 아닌 자의 명의로 발급받은 경우 2퍼센트이다. ㄱ 1, ㄴ 1, ㄷ 2로 4번이다.","c":"하","v":1},"관세사2024_41-28":{"w":"직전 연도 공급대가의 합계액이 8천만원부터 8천만원의 130퍼센트에 해당하는 금액까지의 범위에서 대통령령으로 정하는 금액에 미달하는 개인사업자가 간이과세자이다. 부동산임대업은 직전 연도 공급대가 합계액이 4천800만원 이상이면 간이과세자로 보지 않는다. 3번이다.","c":"중","v":1},"관세사2024_41-29":{"w":"납세보전·조사를 위해 세무서장이 명할 수 있는 사항은 세금계산서의 발급, 신용카드 조회기 설치·사용, 현금영수증 발급장치 설치·사용, 표찰 게시이다. ㄱ~ㄹ 모두이므로 5번이다.","c":"중","v":1},"관세사2025_42-15":{"w":"둘 이상의 과세기간에 걸쳐 용역을 제공하고 대가를 선불로 받으면 선불 대가에 각 과세기간의 용역제공 개월 수를 계약기간 개월 수로 나눈 비율을 곱해 공급가액으로 한다. 개시일이 속하는 달이 1개월 미만이면 1개월로 보고, 종료일이 속하는 달이 1개월 미만이면 넣지 않는다.\n계약기간 2025.2.1~2027.3.9는 2025년 2월부터 2027년 2월까지 25개월이고 2027년 3월(9일)은 빼며, 2025년 제1기 해당 개월은 2월~6월 5개월이다.\n46억원 × 5/25 = 9억 2천만원으로 2번이다.","c":"상","v":1},"관세사2025_42-16":{"w":"토지와 건물의 가액 구분이 불분명하면 감정평가가액으로 안분하는데, 쓸 수 있는 감정평가가액은 공급시기가 속하는 과세기간의 직전 과세기간 개시일부터 공급시기가 속하는 과세기간 종료일까지 평가한 것이다(부가가치세법 시행령 제64조제1항제1호). 공급시기 2025년 2월 1일 기준으로 2024년 7월 1일 이후 평가분만 쓸 수 있어 2023년 10월 1일 평가액은 쓰지 못하고, 기준시가로 안분한다.\n건물 비율 2억 / (6억 + 2억) = 25%\n실지거래가액 = 4억 5천만원 ÷ 25% = 18억원으로 5번이다.","c":"상","v":1},"관세사2025_42-17":{"w":"수정세금계산서 발급 사유는 환입(ㄱ), 계약 해제(ㄴ), 발급대상이 아닌 면세 거래에 발급한 경우(ㄹ) 등이다.\n내국신용장은 과세기간 종료 후 25일 이내에 개설된 경우만 해당하므로 30일 이후는 사유가 아니다(ㄷ). 세무조사 통지를 받아 경정을 미리 알고 있는 경우의 착오 정정도 사유가 아니다(ㅁ). 2번이다.","c":"중","v":1},"관세사2025_42-19":{"w":"의제매입세액 공제율: 제조업은 중소기업과 개인사업자 104분의 4, 그 외 법인은 102분의 2이다. 음식점업은 과세유흥장소 102분의 2, 법인 106분의 6이다. 제분업 등 개인사업자 제조업은 106분의 6, 그 외 사업은 102분의 2이다.\n중소기업 이외의 법인 제조업을 104분의 4로 적은 1번이 옳지 않다.","c":"중","v":1},"관세사2025_42-20":{"w":"감가상각자산의 공통매입세액은 면세비율이 취득 과세기간(또는 마지막 재계산 과세기간)의 비율과 5퍼센트포인트 이상 차이 나면 재계산한다.\n2024년 제1기 면세비율은 10 / 20 = 50%, 제2기는 12 / 30 = 40%로 10%포인트 차이라 제2기에 재계산 대상이 되었고, 이후 비교 기준은 40%가 된다.\n2025년 제1기에 재계산하지 않으려면 면세비율이 35% 초과 45% 미만이어야 한다. 과세 20억원이면 면세는 약 10.8억~16.4억원이고, 선지 중 15억원(15 / 35 = 42.9%)이 해당한다. 1번이다.","c":"중","v":1},"관세사2025_42-21":{"w":"개별소비세법상 자동차의 구입·임차·유지 매입세액은 공제하지 않되, 운수업, 자동차 판매업, 자동차 임대업, 운전학원업, 기계경비업무를 하는 경비업 등 직접 영업에 쓰는 경우는 공제한다. 기계경비업무를 하지 않는 경비업은 제외되는 업종이 아니다. 3번이다.","c":"중","v":1},"관세사2025_42-22":{"w":"신용카드 등 사용에 따른 세액공제는 연간 500만원 한도이고 2026년 12월 31일까지는 연간 1천만원 한도이다. 1번이다.","c":"중","v":1},"관세사2025_42-23":{"w":"직전 과세기간 공급가액 합계액이 1억 5천만원 미만인 법인사업자에게는 각 예정신고기간마다 직전 과세기간 납부세액의 50퍼센트를 결정·징수한다. 1번이다.","c":"중","v":1},"관세사2025_42-24":{"w":"수시부과 사유는 허위 세금계산서 발급·수취, 실제 공급자가 아닌 자의 명의로 발급받은 경우, 공급가액을 과다 기재한 경우 등이다. 지연발급(확정신고기한까지 발급하지 않음)은 수시부과 사유가 아니다. 5번이다.","c":"중","v":1},"관세사2025_42-25":{"w":"조기환급 대상은 영세율 적용 사업자(ㄱ), 사업설비를 취득한 사업자(ㄴ), 재무구조개선계획을 이행 중인 사업자(ㄷ)이다. 중소기업진흥법에 따른 조기환급 승인(ㄹ)은 사유가 아니다. 3번이다.","c":"중","v":1},"관세사2025_42-26":{"w":"조사해 결정·경정할 수 있는 경우는 사업장 이동이 빈번한 지역에 있는 경우(ㄱ), 조기환급 신고 내용에 오류가 있는 경우(ㄴ), 휴업·폐업 상태로 포탈 우려가 있는 경우(ㄹ)이다. 강제징수처분이 있다는 사정(ㄷ)만으로는 해당하지 않는다. 4번이다.","c":"하","v":1},"관세사2025_42-27":{"w":"사업자미등록 가산세 규정이 적용되는 경우에도 세금계산서 관련 가산세는 중복 적용하지 않고, 현금매출명세서 불성실 가산세는 함께 적용할 수 있다. 2번이다.","c":"중","v":1},"관세사2025_42-30":{"w":"세무서장은 과태료를 늘릴 필요가 있으면 개별기준 금액의 2분의 1 범위에서 늘릴 수 있고, 늘려도 2천만원을 넘을 수 없다. 3번이다.","c":"중","v":1},"관세사2026_43-14":{"w":"공통사용 재화를 공급하면 직전 과세기간(2025년 제2기)의 과세공급가액 비율을 적용한다. 6억 / 10억 = 60%\n200,000,000 × 60% = 120,000,000원이므로 5번이다.","c":"상","v":1},"관세사2026_43-15":{"w":"ㄱ O: 반환 조건으로 공제한 용기대금은 공급가액에 포함하지 않는다.\nㄴ X: 지체된 대가에 대한 연체이자는 공급가액에 포함하지 않는다.\nㄷ O: 공급과 직접 관련되지 않는 국고보조금·공공보조금은 공급가액에 포함하지 않는다.\nㄱ, ㄷ이므로 4번이다.","c":"중","v":1},"관세사2026_43-16":{"w":"재화 수입의 과세표준은 관세의 과세가격과 관세, 개별소비세, 주세, 교육세, 농어촌특별세, 교통·에너지·환경세의 합계이다. 담배소비세는 포함하지 않는다. 2번이다.","c":"중","v":1},"관세사2026_43-17":{"w":"실지귀속을 구분할 수 없는 공통매입세액은 해당 과세기간의 총공급가액 중 과세공급가액 비율로 안분한다.\n1기 전체 과세공급가액 5억 + 10억 = 15억원, 면세 3억 + 2억 = 5억원이므로 과세 비율은 15 / 20 = 75%이다.\n매입세액 120,000,000 × 10% = 12,000,000원, 공제액 12,000,000 × 75% = 9,000,000원이므로 4번이다.","c":"상","v":1},"관세사2026_43-18":{"w":"세금계산서는 합병 소멸 법인의 합병 기간 공급분을 존속·신설 법인이 발급할 수 있고, 수용으로 재화를 공급하면 위탁판매를 준용해 사업시행자가 발급할 수 있다. 이중 발급과 면세 거래에 발급한 경우에는 수정세금계산서를 발급할 수 있다. ㄱ~ㄹ 모두이므로 5번이다.","c":"중","v":1},"관세사2026_43-20":{"w":"공급시기 이후 확정신고기한까지 발급받은 세금계산서(ㄱ), 등록 전 거래를 주민등록번호로 발급받은 경우(ㄴ), 공급시기 전에 발급받았지만 6개월 이내에 공급시기가 도래하고 거래사실이 확인되는 경우(ㄷ)의 매입세액은 모두 공제된다. 5번이다.","c":"중","v":1},"관세사2026_43-21":{"w":"원재료 구입의 세금계산서에 착오가 있어도 기재사항으로 거래사실이 확인되면 공제한다. 구입액 5,000,000원의 매입세액은 500,000원이다.\n공장부지 조성비용, 면세사업 투자 관련 매입, 기업업무추진비 관련 구입은 매입세액을 공제하지 않는다.\n공제액 500,000원이므로 2번이다.","c":"상","v":1},"관세사2026_43-23":{"w":"국내사업장이 없는 외국법인에게서 용역을 공급받는 경우 대리납부의무자는 매입세액공제를 받을 수 없는 자이다. 면세사업만 하는 사업자(ㄱ)와 사업자가 아닌 자(ㄴ)가 해당한다.\n과세사업에 제공하는 과세사업자(ㄷ)는 매입세액을 공제받을 수 있어 대리납부의무가 없다. 4번이다.","c":"중","v":1},"관세사2026_43-24":{"w":"예정신고 때 적용하는 것은 면세농산물 등 의제매입세액 공제(ㄱ)이다. 공통매입세액 재계산, 대손세액공제, 가산세는 확정신고 때 적용한다. 1번이다.","c":"중","v":1},"관세사2026_43-25":{"w":"타인 명의로 사업자등록을 한 경우는 공급가액 합계액의 2퍼센트(부가가치세법 제60조제1항제2호), 재화나 용역을 공급하지 않고 세금계산서등을 발급한 경우는 3퍼센트(제60조제3항제1호), 사업 개시일부터 20일 이내에 등록을 신청하지 않은 경우는 1퍼센트(제60조제1항제1호)이다.\n2 + 3 + 1 = 6이므로 3번이 된다. 데이터 정답 ④(7)와 다르다: 미등록 가산세율을 2퍼센트로 보아야 7이 나오는데 현행 조문은 1퍼센트이다.","c":"의심","v":1},"관세사2026_43-26":{"w":"수시부과 사유는 사업장 이동이 빈번해 포탈 우려가 있는 경우(ㄱ)와 실제로 공급받는 자가 아닌 자의 명의로 세금계산서를 발급한 경우(ㄷ)이다. 신고 내용의 오류·누락(ㄴ)은 수시부과가 아니라 결정·경정 사유이다. 3번이다.","c":"중","v":1},"관세사2026_43-28":{"w":"간이과세자로 보지 않는 업종은 광업, 제조업의 일부, 상품중개업, 부동산매매업 등이다. 재생용 재료수집 및 판매업은 간이과세 배제 업종이 아니다. ㄱ, ㄴ, ㄷ이므로 4번이다.","c":"중","v":1},"관세사2026_43-29":{"w":"일반과세자가 간이과세자로 바뀔 때 재고납부세액은 재고금액 × 10/100 × (1 − 0.5% × 110/10)이다. 감가상각자산은 취득가액에 (1 − 5% × 경과된 과세기간 수)를 곱한다.\n상품: 10,000,000 × 10% × 0.945 = 945,000원\n건물: 2024년 제1기 취득, 경과 5기(2024 제1·2기, 2025 제1·2기, 2026 제1기) → 200,000,000 × (1 − 5% × 5) = 150,000,000원, 150,000,000 × 10% × 0.945 = 14,175,000원\n합계 945,000 + 14,175,000 = 15,120,000원이므로 3번이다.","c":"상","v":1},"관세사2026_43-30":{"w":"ㄱ O: 개인사업자가 6개월 이상 국외에 체류하려면 납세관리인을 정한다.\nㄴ X: 공무원은 납세의무자와 거래하는 자에게도 질문하거나 장부·서류를 조사할 수 있다.\nㄷ X: 납세보전·조사 명령 위반의 과태료는 2천만원 이하이다.\nㄱ만 옳아 1번이다.","c":"중","v":1},"관세사2017_34-28":{"w":"사업자등록 정정신고를 받은 세무서장은 상호 변경의 경우 신청일 당일에 재발급하고, 법인 대표자 변경, 공동사업자 구성원·출자지분 변경, 상속에 의한 명의 변경 등은 신청일부터 2일 이내에 재발급한다. 4번이다.","c":"중","v":1},"관세사2019_36-09":{"w":"(2021 개정 전 기준) 출제 당시에는 신탁재산을 수탁자 명의로 매매하면 위탁자가 직접 재화를 공급하는 것으로 보았다(ㄱ O). 다만 위탁자의 채무이행을 담보하려고 맺은 신탁에서 수탁자가 채무이행을 위해 신탁재산을 처분하면 수탁자가 재화를 공급하는 것으로 보았으므로 ㄴ은 X이다.\nㄷ X: 신탁 종료로 수탁자가 위탁자에게 신탁재산을 이전하는 것은 재화의 공급이 아니다.\nㄹ X: 수탁자 변경으로 새 수탁자에게 신탁재산을 이전하는 것도 재화의 공급이 아니다.\nㅁ O: 수탁자가 변경되면 새 수탁자는 이전 수탁자에게 고지된 납세의무를 승계했다.\n옳지 않은 것은 ㄴ, ㄷ, ㄹ로 4번이다.\n2022년부터는 신탁재산 관련 공급의 납세의무자가 원칙적으로 수탁자이므로(부가가치세법 제3조제2항) 현행법으로는 ㄱ도 틀린 진술이 된다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시에는 신탁재산을 수탁자 명의로 매매하면 위탁자가 직접 재화를 공급하는 것으로 보았다(ㄱ O). 다만 위탁자의 채무이행을 담보하려고 맺은 신탁에서 수탁자가 채무이행을 위해 신탁재산을 처분하면 수탁자가 재화를 공급하는 것으로 보았으므로 ㄴ은 X이다.\nㄷ X: 신탁 종료로 수탁자가 위탁자에게 신탁재산을 이전하는 것은 재화의 공급이 아니다.\nㄹ X: 수탁자 변경으로 새 수탁자에게 신탁재산을 이전하는 것도 재화의 공급이 아니다.\nㅁ O: 수탁자가 변경되면 새 수탁자는 이전 수탁자에게 고지된 납세의무를 승계했다.\n옳지 않은 것은 ㄴ, ㄷ, ㄹ로 4번이다.\n2022년부터는 신탁재산 관련 공급의 납세의무자가 원칙적으로 수탁자이므로(부가가치세법 제3조제2항) 현행법으로는 ㄱ도 틀린 진술이 된다."},"관세사2020_37-02":{"w":"등록 정정 후 재발급 기한은 상호 변경은 신청일 당일이고, 사업 종류 변경, 상속에 의한 명의 변경, 공동사업자 구성원 변경, 사업장 이전은 신청일부터 2일 이내이다. 기한이 다른 것은 1번이다.","c":"중","v":1},"관세사2024_41-03":{"w":"ㄱ X: 사업개시일 전에 사업자등록을 신청한 신규사업자의 최초 과세기간은 신청한 날부터 시작한다(부가가치세법 제5조제2항 단서).\nㄴ O: 폐업하면 폐업일이 속하는 과세기간 개시일부터 폐업일까지가 최종 과세기간이다.\nㄷ X: 간이과세를 포기하면 간이과세자 과세기간은 1월 1일부터 포기신고일이 속하는 달의 마지막 날(4월 30일)까지이고, 다음 달 1일부터 일반과세자 과세기간이 시작된다.\nㄴ만 옳아 2번이다.","c":"상","v":1},"관세사2025_42-29":{"w":"납세관리인을 정해야 하는 경우는 사업자가 사업장에 통상적으로 머무르지 않는 경우나 6개월 이상 국외에 체류하려는 경우이다. 3개월 이상 국외 체류라는 3번은 기준이 맞지 않는다. 2번이다.","c":"중","v":1},"관세사2026_43-01":{"w":"ㄱ O: 과세되는 재화를 수입하는 자는 사업자인지와 관계없이 납세의무가 있다(부가가치세법 제3조제1항제2호).\nㄴ O: 납세의무자인 법인에는 국가·지방자치단체·지방자치단체조합이 포함된다.\nㄷ X: 소득세가 과세되지 않는 농어가부업은 독립된 사업으로 보지 않지만, 그중 민박·음식물 판매·특산물 제조·전통차 제조와 이와 유사한 활동은 독립된 사업으로 보므로(시행규칙 제2조제3항 단서) 납세의무가 있다.\nㄱ, ㄴ이므로 3번이다.","c":"상","v":1},"관세사2026_43-04":{"w":"등록정정 사유 중 신고일 당일에 재발급하는 것은 상호 변경이다. 1번이다. 대표자 변경, 사업 종류 변동, 상속에 의한 명의 변경, 공동사업자 구성원·지분 변경은 신청일부터 2일 이내에 재발급한다.","c":"상","v":1},"관세사2017_34-18-2":{"old":1,"ow":"출제 당시 정답 O. 전자세금계산서 의무발급 개인사업자 기준이 3억원에서 2억원, 1억원을 거쳐 2023.2.28 시행령 개정으로 2024.7.1부터 8천만원(면세공급가액 포함)으로 내려갔으므로 3억원을 기준으로 적은 지금 문장은 틀린 문장이다(부가가치세법 시행령 제68조제1항)."},"관세사2017_34-20-1":{"old":1,"ow":"출제 당시 정답 O. 2020.2.11 시행령 개정으로 대손세액 공제 범위가 공급일부터 5년에서 10년이 지난 날이 속하는 과세기간의 확정신고기한까지로 늘었으므로 지금은 틀린 문장이다(부가가치세법 시행령 제87조제2항)."},"관세사2017_34-36-2":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 개정(2021.7.1 시행)으로 간이과세자의 의제매입세액공제(법 제65조)가 삭제되어 지금은 간이과세자가 의제매입세액을 공제받을 수 없으므로 틀린 문장이다(부가가치세법 제65조 삭제, 제63조제3항)."},"관세사2019_36-22-4":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 개정(2021.7.1 시행)으로 간이과세자의 의제매입세액공제가 폐지되어 106분의 6 공제를 적용할 수 없으므로 지금은 틀린 문장이다(부가가치세법 제65조 삭제)."},"관세사2018_35-36-2":{"old":1,"ow":"출제 당시 정답 O. 2019.12.31 개정(2020.1.1 시행)으로 탁주와 맥주가 종량세로 바뀌어 주정·탁주·맥주는 수량, 그 밖의 주류만 가격이 과세표준이므로 '주정 외의 주류'를 모두 가격으로 정한 지금 문장은 틀린 문장이다(주세법 제7조)."},"관세사2022_39-17-2":{"old":1,"ow":"출제 당시 정답 O. 2024.2.29 시행령 개정으로 매입자발행세금계산서 거래사실 확인 신청기한이 과세기간 종료일부터 6개월에서 1년 이내로 늘었으므로 지금은 틀린 문장이다(부가가치세법 시행령 제71조의2제3항)."}};
